const ChatModule = () => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string, urls?: any[] }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;
    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: userMsg,
        config: { tools: [{ googleSearch: {} }] }
      });

      const text = response.text || "No response received.";
      const urls = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

      setMessages(prev => [...prev, { role: 'model', text, urls }]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'model', text: "Error connecting to Gemini." }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full max-w-4xl mx-auto w-full p-6">
      <div className="flex-1 overflow-y-auto space-y-6 pb-24">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-2xl ${m.role === 'user' ? 'bg-indigo-600' : 'glass border-white/10'}`}>
              <p className="whitespace-pre-wrap">{m.text}</p>
              {m.urls && m.urls.length > 0 && (
                <div className="mt-4 pt-4 border-t border-white/10 text-sm space-y-1">
                  <p className="text-zinc-400 mb-1">Sources:</p>
                  {m.urls.map((u, idx) => u.web && (
                    <a key={idx} href={u.web.uri} target="_blank" className="block text-indigo-400 hover:underline overflow-hidden text-ellipsis whitespace-nowrap">
                      {u.web.title}
                    </a>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
        {loading && <div className="text-zinc-500 italic animate-pulse">Gemini is thinking...</div>}
      </div>
      <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-2xl px-4">
        <div className="relative glass p-1 rounded-2xl flex items-center gap-2 border-white/20">
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
            placeholder="Ask anything..."
            className="flex-1 bg-transparent border-none outline-none p-4 text-white"
          />
          <button onClick={sendMessage} className="w-12 h-12 bg-indigo-500 rounded-xl flex items-center justify-center hover:bg-indigo-600 transition-colors">
            <i className="fas fa-arrow-up text-white"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

