const LiveModule = () => {
  const [active, setActive] = useState(false);
  const [transcription, setTranscription] = useState<string[]>([]);
  const audioContexts = useRef<{ input: AudioContext; output: AudioContext } | null>(null);
  const sessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef(new Set<AudioBufferSourceNode>());

  const startSession = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContexts.current = {
        input: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 }),
        output: new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 }),
      };

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setActive(true);
            const source = audioContexts.current!.input.createMediaStreamSource(stream);
            const scriptProcessor = audioContexts.current!.input.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContexts.current!.input.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
             if (message.serverContent?.outputTranscription) {
               setTranscription(prev => [...prev.slice(-10), `AI: ${message.serverContent!.outputTranscription!.text}`]);
             }
             if (message.serverContent?.inputTranscription) {
               setTranscription(prev => [...prev.slice(-10), `You: ${message.serverContent!.inputTranscription!.text}`]);
             }

             const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
             if (base64Audio) {
               const ctx = audioContexts.current!.output;
               nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
               const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
               const source = ctx.createBufferSource();
               source.buffer = audioBuffer;
               source.connect(ctx.destination);
               source.start(nextStartTimeRef.current);
               nextStartTimeRef.current += audioBuffer.duration;
               sourcesRef.current.add(source);
               source.onended = () => sourcesRef.current.delete(source);
             }

             if (message.serverContent?.interrupted) {
               sourcesRef.current.forEach(s => s.stop());
               sourcesRef.current.clear();
               nextStartTimeRef.current = 0;
             }
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: 'You are a friendly companion. Talk concisely and naturally.'
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error(err);
      alert("Microphone access or connection failed.");
    }
  };

  const stopSession = () => {
    sessionRef.current?.close();
    setActive(false);
    audioContexts.current?.input.close();
    audioContexts.current?.output.close();
  };

  return (
    <div className="h-full flex flex-col items-center justify-center p-8">
      <div className="w-full max-w-xl text-center space-y-8">
        <div className={`w-64 h-64 mx-auto rounded-full flex items-center justify-center relative ${active ? 'bg-indigo-500/10' : 'bg-zinc-800'}`}>
          {active && (
             <>
               <div className="absolute inset-0 rounded-full border-4 border-indigo-500 animate-ping opacity-20"></div>
               <div className="absolute inset-4 rounded-full border-2 border-indigo-400 animate-ping opacity-30" style={{ animationDelay: '0.5s' }}></div>
             </>
          )}
          <i className={`fas fa-microphone text-6xl ${active ? 'text-indigo-500' : 'text-zinc-600'}`}></i>
        </div>

        <div className="space-y-4">
          <h2 className="text-3xl font-bold">{active ? 'Listening...' : 'Ready to Talk?'}</h2>
          <p className="text-zinc-400">Experience real-time, low-latency conversation with Gemini.</p>
        </div>

        <button 
          onClick={active ? stopSession : startSession}
          className={`px-12 py-4 rounded-2xl font-bold text-lg transition-all shadow-xl ${active ? 'bg-red-500 hover:bg-red-600' : 'bg-indigo-500 hover:bg-indigo-600'}`}
        >
          {active ? 'STOP SESSION' : 'START CONVERSATION'}
        </button>

        <div className="glass p-4 rounded-xl min-h-[100px] text-left text-sm text-zinc-300 border-white/5 h-40 overflow-y-auto">
           {transcription.length === 0 ? "Transcription will appear here..." : transcription.map((t, i) => <div key={i}>{t}</div>)}
        </div>
      </div>
    </div>
  );
};

const VideoModule = () => {
  const [prompt, setPrompt] = useState('');
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [status, setStatus] = useState<'idle' | 'checking_key' | 'generating' | 'downloading'>('idle');
  const [progress, setProgress] = useState(0);

  const checkAndGenerate = async () => {
    if (!prompt) return;
    setStatus('checking_key');

    try {
      if (!(window as any).aistudio) {
          throw new Error("AI Studio context not found.");
      }

      const hasKey = await (window as any).aistudio.hasSelectedApiKey();
      if (!hasKey) {
        await (window as any).aistudio.openSelectKey();
        // Proceeding as per instructions: assume key selection successful after trigger
      }

      setStatus('generating');
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt,
        config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
      });

      // Polling
      let pollCount = 0;
      while (!operation.done) {
        await new Promise(r => setTimeout(r, 10000));
        pollCount++;
        setProgress(Math.min(pollCount * 8, 95));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadUri = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadUri) {
        setStatus('downloading');
        const response = await fetch(`${downloadUri}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      }
    } catch (err) {
      console.error(err);
      alert("Video generation failed. Ensure you have a paid project selected.");
    } finally {
      setStatus('idle');
      setProgress(0);
    }
  };

  return (
    <div className="p-8 h-full flex flex-col items-center">
      <div className="w-full max-w-2xl space-y-6">
        <div className="glass p-6 rounded-3xl border-white/10">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-2xl font-bold">Cinema Cinema</h2>
            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-xs text-indigo-400 underline">Billing Docs</a>
          </div>
          <input
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="Describe a cinematic scene (e.g. 'A futuristic drone flying through a neon city at night')..."
            className="w-full bg-zinc-900/50 rounded-xl p-4 border border-white/5 outline-none mb-4"
          />
          <button 
            onClick={checkAndGenerate}
            disabled={status !== 'idle'}
            className="w-full bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 py-4 rounded-xl font-bold transition-all"
          >
            {status === 'idle' ? 'GENERATE VIDEO' : 'PRODUCING...'}
          </button>
        </div>

        {status !== 'idle' && (
          <div className="w-full space-y-2">
             <div className="flex justify-between text-xs text-zinc-400">
               <span>{status === 'generating' ? 'AI is rendering frames...' : 'Preparing...'}</span>
               <span>{progress}%</span>
             </div>
             <div className="w-full h-2 bg-zinc-800 rounded-full overflow-hidden">
                <div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${progress}%` }}></div>
             </div>
          </div>
        )}

        <div className="w-full aspect-video rounded-2xl overflow-hidden glass border border-white/10 flex items-center justify-center bg-black shadow-2xl">
           {videoUrl ? (
             <video src={videoUrl} controls autoPlay loop className="w-full h-full object-cover" />
           ) : (
             <div className="text-zinc-600 flex flex-col items-center">
               <i className="fas fa-film text-4xl mb-4 opacity-10"></i>
               <p className="opacity-40">Ready for action</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );
};

