import React, { useState, useLayoutEffect, useRef, useEffect } from 'react';
import { Project, Template, TemplateStep } from '../types';
import { PromptEditor } from './PromptEditor';
import { Button } from './Button';

interface ProjectRunnerProps {
  project: Project;
  template: Template;
  onUpdateProject: (projectId: string, updates: Partial<Project>) => void;
  onUpdateTemplate: (templateId: string, updates: Partial<Template>) => void;
  onRequestConfirm: (title: string, message: string, onConfirm: () => void) => void;
  fontSizeClass?: string;
  rightPanelWidth: number;
  onRightPanelWidthChange: (width: number) => void;
  isRightPanelOpen: boolean;
  onRightPanelOpenChange: (isOpen: boolean) => void;
}

const AutoResizeTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) { el.style.height = '0px'; el.style.height = `${el.scrollHeight}px`; }
  };
  useLayoutEffect(() => { adjustHeight(); }, [value]);
  return (
    <textarea ref={textareaRef} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className={`block w-full resize-none overflow-hidden bg-transparent outline-none focus:ring-0 p-0 m-0 ${className}`} rows={1} spellCheck={false} />
  );
};

export const ProjectRunner: React.FC<ProjectRunnerProps> = ({
  project, template, onUpdateProject, onUpdateTemplate, onRequestConfirm, fontSizeClass = 'text-sm', rightPanelWidth, onRightPanelWidthChange, isRightPanelOpen, onRightPanelOpenChange
}) => {
  const [collapsedSteps, setCollapsedSteps] = useState<Record<string, boolean>>({});
  const [isResizingRight, setIsResizingRight] = useState(false);

  const interpolate = (templateStr: string): string => {
    if (!templateStr) return "";
    let result = templateStr;

    // 1. Global Inputs <0>, <1>... or <Name>
    template.inputs.forEach((input, index) => {
      const val = project.inputValues[input.id] || "";
      result = result.split(`<${index}>`).join(val);
      result = result.split(`<${input.label}>`).join(val);
    });

    // 2. Local Custom Variables <l1>, <l2>... or <Name>
    (project.customInputs || []).forEach((input, index) => {
       const val = project.inputValues[input.id] || "";
       result = result.split(`<l${index + 1}>`).join(val);
       result = result.split(`<${input.label}>`).join(val);
    });

    // 3. Step Output Referencing [[1]], [[2]]... or [[Step Name]]
    template.steps.forEach((step, index) => {
      const output = project.stepOutputs[step.id] || "";
      result = result.split(`[[${index + 1}]]`).join(output);
      result = result.split(`[[${step.name}]]`).join(output);
    });

    return result;
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingRight) return;
      const newWidth = window.innerWidth - e.clientX;
      if (newWidth > 250 && newWidth < 1000) onRightPanelWidthChange(newWidth);
    };
    const handleMouseUp = () => { setIsResizingRight(false); document.body.style.cursor = 'default'; };
    if (isResizingRight) { window.addEventListener('mousemove', handleMouseMove); window.addEventListener('mouseup', handleMouseUp); document.body.style.cursor = 'col-resize'; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingRight, onRightPanelWidthChange]);

  return (
    <div className={`flex h-full w-full ${fontSizeClass}`}>
      <div className="flex-1 flex flex-col min-w-0">
         <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 pb-40 no-scrollbar">
            {/* Removed max-w-5xl mx-auto to fill horizontal space */}
            <div className="w-full space-y-8">
                {template.steps.map((step, index) => {
                const override = project.stepOverrides[step.id];
                const rawContent = override?.content !== undefined ? override.content : (step.content || "");
                const interpolated = interpolate(rawContent);
                const isCollapsed = collapsedSteps[step.id];

                return (
                    <div key={step.id} id={step.id} className={`border border-slate-800 rounded-2xl bg-slate-900/40 shadow-sm scroll-mt-8 overflow-hidden transition-all duration-300`}>
                    <div className="flex items-center justify-between px-6 py-4 bg-slate-900 border-b border-slate-800 cursor-pointer hover:bg-slate-800/80 transition-colors" onClick={() => setCollapsedSteps(p => ({...p, [step.id]: !isCollapsed}))}>
                        <div className="flex items-center space-x-4">
                            <span className="text-xs font-mono font-bold text-slate-500 bg-slate-800 px-2 py-0.5 rounded-md">{index + 1}</span>
                            <h3 className="font-black text-slate-200 text-sm tracking-tight">{step.name}</h3>
                        </div>
                        <div className="flex items-center gap-4">
                           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className={`w-5 h-5 text-slate-600 transition-transform ${isCollapsed ? '' : 'rotate-180'}`}><path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z" /></svg>
                        </div>
                    </div>

                    {!isCollapsed && (
                        <div className="p-6 bg-slate-900/20">
                            <PromptEditor label="提示词实时预览" templateContent={rawContent} interpolatedContent={interpolated} originalTemplateContent={step.content || ""} onUpdateOverride={(c) => onUpdateProject(project.id, { stepOverrides: { ...project.stepOverrides, [step.id]: { content: c } } })} onRevert={() => { const o = {...project.stepOverrides}; delete o[step.id]; onUpdateProject(project.id, { stepOverrides: o }); }} onSaveToTemplate={(c) => onRequestConfirm("保存到全局", "确定要将此步骤的局部修改保存回全局模版结构中吗？这会影响该模版下的所有项目。", () => { onUpdateTemplate(template.id, { steps: template.steps.map(s => s.id === step.id ? { ...s, content: c } : s) }); const o = {...project.stepOverrides}; delete o[step.id]; onUpdateProject(project.id, { stepOverrides: o }); })} />
                            <div className="mt-6 border-t border-slate-800/50 pt-6">
                                <div className="flex justify-between items-center mb-3">
                                  <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block">步骤输出 / 个人备注 (支持 [[序号]] 引用)</label>
                                  <button onClick={() => onUpdateProject(project.id, { stepOutputs: { ...project.stepOutputs, [step.id]: '' } })} className="text-[10px] text-slate-700 hover:text-red-400 uppercase tracking-tighter font-bold transition-colors">清除内容</button>
                                </div>
                                <div className={`bg-slate-950/50 border border-slate-800/60 rounded-xl px-4 py-3 transition-colors hover:border-slate-700`}>
                                  <AutoResizeTextarea 
                                    className="text-sm text-slate-400 leading-relaxed font-sans min-h-[60px]" 
                                    value={project.stepOutputs[step.id] || ''} 
                                    onChange={(val) => onUpdateProject(project.id, { stepOutputs: { ...project.stepOutputs, [step.id]: val } })} 
                                    placeholder="输入此步骤的生成结果、草稿或用于下一步骤引用的关键信息..." 
                                  />
                                </div>
                            </div>
                        </div>
                    )}
                    </div>
                );
                })}
            </div>
         </div>
      </div>

      {isRightPanelOpen && <div className="w-1.5 bg-slate-800 hover:bg-blue-600 cursor-col-resize z-30 flex-shrink-0 transition-colors" onMouseDown={(e) => { e.preventDefault(); setIsResizingRight(true); }} />}

      <div style={{ width: isRightPanelOpen ? rightPanelWidth : '40px' }} className="bg-slate-900 border-l border-slate-800 flex flex-col flex-shrink-0 transition-all duration-75 relative">
         <div className="flex items-center justify-between p-3 border-b border-slate-800 bg-slate-900 h-12 shrink-0">
             {isRightPanelOpen && <span className="font-bold text-[10px] text-slate-500 uppercase tracking-widest pl-3 truncate">拼接结果实时全览</span>}
             <button onClick={() => onRightPanelOpenChange(!isRightPanelOpen)} className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-500 hover:text-white transition-colors">{isRightPanelOpen ? "»" : "«"}</button>
         </div>
         {isRightPanelOpen && (
           <div className="flex-1 overflow-y-auto p-6 bg-slate-950/30 space-y-8 no-scrollbar">
             {template.steps.map((step, idx) => {
                const override = project.stepOverrides[step.id];
                const content = interpolate(override?.content !== undefined ? override.content : (step.content || ""));
                return (
                  <div key={step.id} className="relative group">
                    <div className="flex items-center gap-3 mb-3">
                      <span className="text-[11px] font-mono text-slate-600 font-bold">&lt;{idx+1}&gt;</span>
                      <span className="text-xs font-black text-slate-500 uppercase truncate tracking-tight">{step.name}</span>
                    </div>
                    <div className="text-slate-300 font-mono text-sm leading-relaxed whitespace-pre-wrap pl-4 py-2 border-l-2 border-slate-800 group-hover:border-blue-500/30 transition-colors relative">
                        {content}
                        <button onClick={() => {
                          navigator.clipboard.writeText(content);
                        }} className="absolute top-0 right-0 p-1.5 opacity-0 group-hover:opacity-100 text-[10px] text-blue-400 uppercase font-black bg-slate-900/90 rounded-md border border-slate-800 shadow-xl transition-all hover:scale-105 active:scale-95">复制</button>
                    </div>
                  </div>
                );
             })}
           </div>
         )}
      </div>
    </div>
  );
};

import React, { useState, useLayoutEffect, useRef, useEffect } from 'react';
import { Template, TemplateInput, TemplateStep } from '../types';
import { Button } from './Button';

interface TemplateEditorProps {
  template: Template;
  onSave: (template: Template) => void;
  onCancel: () => void;
  onRequestConfirm: (title: string, message: string, onConfirm: () => void) => void;
}

const AutoResizeTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = '0px';
      const scrollHeight = el.scrollHeight;
      el.style.height = `${scrollHeight}px`;
    }
  };

  useLayoutEffect(() => {
    adjustHeight();
  }, [value]);

  useEffect(() => {
    const handle = requestAnimationFrame(() => {
      adjustHeight();
    });
    return () => cancelAnimationFrame(handle);
  }, []);

  useEffect(() => {
    window.addEventListener('resize', adjustHeight);
    return () => window.removeEventListener('resize', adjustHeight);
  }, []);

  return (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={`block w-full resize-none overflow-hidden bg-transparent outline-none focus:ring-0 p-0 m-0 ${className}`}
      rows={1}
      spellCheck={false}
    />
  );
};

export const TemplateEditor: React.FC<TemplateEditorProps> = ({ template, onSave, onCancel, onRequestConfirm }) => {
  const [editedTemplate, setEditedTemplate] = useState<Template>(JSON.parse(JSON.stringify(template)));
  const [collapsedSteps, setCollapsedSteps] = useState<Record<number, boolean>>({});

  const addInput = () => {
    const newInput: TemplateInput = {
      id: `input_${Date.now()}`,
      label: '新输入变量'
    };
    setEditedTemplate(prev => ({ ...prev, inputs: [...prev.inputs, newInput] }));
  };

  const updateInput = (idx: number, updates: Partial<TemplateInput>) => {
    setEditedTemplate(prev => {
      const inputs = [...prev.inputs];
      inputs[idx] = { ...inputs[idx], ...updates };
      return { ...prev, inputs };
    });
  };

  const removeInput = (idx: number) => {
    onRequestConfirm('删除变量', '确认删除此输入项？使用此输入的步骤将会显示错误。', () => {
      setEditedTemplate(prev => ({
        ...prev,
        inputs: prev.inputs.filter((_, i) => i !== idx)
      }));
    });
  };

  const addStep = () => {
    const newStep: TemplateStep = {
      id: `step_${Date.now()}`,
      name: '新步骤',
      content: '请在此输入提示词模板...'
    };
    setEditedTemplate(prev => ({ ...prev, steps: [...prev.steps, newStep] }));
  };

  const updateStep = (idx: number, updates: Partial<TemplateStep>) => {
    setEditedTemplate(prev => {
      const steps = [...prev.steps];
      steps[idx] = { ...steps[idx], ...updates };
      return { ...prev, steps };
    });
  };

  const removeStep = (idx: number) => {
    onRequestConfirm('删除步骤', '确认删除此步骤？', () => {
      setEditedTemplate(prev => ({
        ...prev,
        steps: prev.steps.filter((_, i) => i !== idx)
      }));
    });
  };

  const toggleStep = (idx: number) => {
    setCollapsedSteps(prev => ({ ...prev, [idx]: !prev[idx] }));
  };

  return (
    /* Removed max-w-5xl and mx-auto to fill horizontal space */
    <div className="bg-slate-900 p-4 md:p-6 rounded-lg h-full overflow-y-auto w-full">
      <div className="flex justify-between items-center mb-6 sticky top-0 bg-slate-900 z-10 py-2 border-b border-slate-800">
        <h2 className="text-xl font-bold text-white">编辑模版</h2>
        <div className="space-x-2">
          <Button variant="secondary" onClick={onCancel}>取消</Button>
          <Button onClick={() => onSave(editedTemplate)}>保存模版</Button>
        </div>
      </div>

      <div className="space-y-4 mb-8">
        <label className="block text-sm font-bold text-slate-300">模版名称</label>
        <input 
          className="w-full bg-slate-950 border border-slate-700 rounded p-2 text-white"
          value={editedTemplate.name}
          onChange={(e) => setEditedTemplate({...editedTemplate, name: e.target.value})}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-4 space-y-4">
           <div className="border border-slate-800 rounded-lg p-4 bg-slate-950/50 sticky top-24">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-slate-200">1. 输入变量 (Inputs)</h3>
              <Button size="sm" onClick={addInput}>+ 添加</Button>
            </div>
            <p className="text-xs text-slate-500 mb-4">
              提示: 可以使用 <span className="text-emerald-400 font-mono">&lt;序号&gt;</span> 或 <span className="text-emerald-400 font-mono">&lt;变量名&gt;</span> 引用。
            </p>
            <div className="space-y-3">
              {editedTemplate.inputs.map((input, idx) => (
                <div key={input.id} className="relative group bg-slate-900 p-3 rounded border border-slate-700">
                   <div className="absolute -left-2 -top-2 w-6 h-6 flex items-center justify-center bg-emerald-600 text-white text-xs font-bold rounded-full border border-slate-900 shadow-sm z-10">
                     {idx}
                   </div>
                   <div className="space-y-2 mt-1">
                     <input 
                        className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-sm text-slate-200"
                        value={input.label}
                        onChange={(e) => updateInput(idx, { label: e.target.value })}
                        placeholder="变量名称"
                     />
                   </div>
                   <button onClick={() => removeInput(idx)} className="absolute top-1 right-1 text-slate-600 hover:text-red-400 p-1">
                     ✕
                   </button>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="lg:col-span-8">
          <div className="border border-slate-800 rounded-lg p-4 bg-slate-950/50">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold text-slate-200">2. 流程步骤 (Steps)</h3>
            </div>
            <div className="space-y-4">
              {editedTemplate.steps.map((step, idx) => {
                const isCollapsed = collapsedSteps[idx];
                return (
                  <div key={step.id} className="bg-slate-900 border border-slate-700 rounded-lg h-auto overflow-visible">
                    <div 
                      className="flex justify-between items-center p-4 bg-slate-800/50 cursor-pointer select-none hover:bg-slate-800 transition-colors rounded-t-lg"
                      onClick={() => toggleStep(idx)}
                    >
                       <div className="flex items-center gap-3">
                          <span className="bg-slate-700 text-slate-300 px-2 py-0.5 rounded text-xs font-bold">Step {idx + 1}</span>
                          <span className="font-bold text-slate-200 text-sm">{step.name || '未命名步骤'}</span>
                       </div>
                       <div className="flex items-center gap-2">
                           <button 
                             onClick={(e) => { e.stopPropagation(); removeStep(idx); }} 
                             className="text-slate-500 hover:text-red-400 p-1"
                           >
                              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4">
                                <path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" />
                              </svg>
                           </button>
                           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className={`w-4 h-4 text-slate-500 transition-transform ${isCollapsed ? '' : 'rotate-180'}`}>
                             <path fillRule="evenodd" d="M4.22 6.22a.75.75 0 0 1 1.06 0L8 8.94l2.72-2.72a.75.75 0 1 1 1.06 1.06l-3.25 3.25a.75.75 0 0 1-1.06 0L4.22 7.28a.75.75 0 0 1 0-1.06Z" clipRule="evenodd" />
                           </svg>
                       </div>
                    </div>

                    {!isCollapsed && (
                      <div className="p-4 border-t border-slate-800 h-auto overflow-visible">
                        <div className="flex justify-between items-start mb-4 gap-4">
                           <div className="flex-1 space-y-2">
                              <label className="text-xs text-slate-500 font-bold uppercase">步骤名称</label>
                              <input 
                                  className="w-full bg-slate-950 border border-slate-700 rounded px-3 py-2 text-sm text-slate-200 outline-none focus:border-blue-500"
                                  value={step.name}
                                  onChange={(e) => updateStep(idx, { name: e.target.value })}
                                  placeholder="步骤名称"
                              />
                           </div>
                           <div className="flex-1 space-y-2">
                              <label className="text-xs text-slate-500 font-bold uppercase">描述 (可选)</label>
                              <input 
                                className="w-full bg-slate-950 border border-slate-700 rounded px-3 py-2 text-sm text-slate-200 outline-none focus:border-blue-500"
                                value={step.description || ''}
                                onChange={(e) => updateStep(idx, { description: e.target.value })}
                                placeholder="描述 (可选)"
                              />
                           </div>
                        </div>

                        <div className="space-y-2 h-auto overflow-visible">
                          <label className="text-xs font-bold text-slate-400 uppercase">提示词模版内容</label>
                          <div className="bg-slate-950 border border-slate-700 rounded p-4 h-auto flex flex-col">
                            <AutoResizeTextarea
                               className="text-sm font-mono text-slate-300 leading-relaxed"
                               value={step.content}
                               onChange={(val) => updateStep(idx, { content: val })}
                               placeholder="编写提示词，例如：我想做一个 <0> 风格的游戏..."
                            />
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}

              <button 
                onClick={addStep}
                className="w-full py-4 border-2 border-dashed border-slate-800 hover:border-blue-500/50 rounded-lg text-slate-500 hover:text-blue-400 transition-all bg-slate-900/50 hover:bg-slate-900 flex items-center justify-center gap-2 font-bold text-sm"
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4">
                  <path fillRule="evenodd" d="M8 2a.5.5 0 0 1 .5.5v5h5a.5.5 0 0 1 0 1h-5v5a.5.5 0 0 1-1 0v-5h-5a.5.5 0 0 1 0-1h5v-5A.5.5 0 0 1 8 2Z" clipRule="evenodd" />
                </svg>
                添加新步骤
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import ReactDOM from 'react-dom';

export interface ToastInfo {
  id: string;
  message: string;
  x: number;
  y: number;
}

interface FloatingToastProps {
  toasts: ToastInfo[];
  onRemove: (id: string) => void;
}

export const FloatingToast: React.FC<FloatingToastProps> = ({ toasts, onRemove }) => {
  return ReactDOM.createPortal(
    <div className="fixed inset-0 pointer-events-none z-[9999]">
      {toasts.map((toast) => (
        <ToastItem key={toast.id} toast={toast} onRemove={onRemove} />
      ))}
    </div>,
    document.body
  );
};

const ToastItem: React.FC<{ toast: ToastInfo; onRemove: (id: string) => void }> = ({ toast, onRemove }) => {
  const [visible, setVisible] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => {
      setVisible(false);
      setTimeout(() => onRemove(toast.id), 300); // Wait for fade out animation
    }, 1700);
    return () => clearTimeout(timer);
  }, [toast.id, onRemove]);

  return (
    <div
      className={`absolute transition-all duration-300 transform -translate-x-1/2 -translate-y-full flex items-center gap-2 px-3 py-1.5 bg-blue-600/90 backdrop-blur-md text-white text-[10px] font-bold rounded-full shadow-lg border border-blue-400/30 ${
        visible ? 'opacity-100 scale-100' : 'opacity-0 scale-90 -translate-y-[120%]'
      }`}
      style={{ left: toast.x, top: toast.y - 10 }}
    >
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3">
        <path fillRule="evenodd" d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" clipRule="evenodd" />
      </svg>
      {toast.message}
    </div>
  );
};

// Hook for easy usage
export const useToast = () => {
  const [toasts, setToasts] = useState<ToastInfo[]>([]);

  const showToast = useCallback((message: string, x: number, y: number) => {
    const id = Math.random().toString(36).substr(2, 9);
    setToasts((prev) => [...prev, { id, message, x, y }]);
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  return { toasts, showToast, removeToast };
};

import React, { useState, useLayoutEffect, useRef, useEffect } from 'react';
import { Project, Template, TemplateStep } from '../types';
import { PromptEditor } from './PromptEditor';
import { Button } from './Button';
import { FloatingToast, useToast } from './FloatingToast';

interface ProjectRunnerProps {
  project: Project;
  template: Template;
  onUpdateProject: (projectId: string, updates: Partial<Project>) => void;
  onUpdateTemplate: (templateId: string, updates: Partial<Template>) => void;
  onRequestConfirm: (title: string, message: string, onConfirm: () => void) => void;
  fontSizeClass?: string;
  rightPanelWidth: number;
  onRightPanelWidthChange: (width: number) => void;
  isRightPanelOpen: boolean;
  onRightPanelOpenChange: (isOpen: boolean) => void;
}

const AutoResizeTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) { el.style.height = '0px'; el.style.height = `${el.scrollHeight}px`; }
  };
  useLayoutEffect(() => { adjustHeight(); }, [value]);
  return (
    <textarea ref={textareaRef} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className={`block w-full resize-none overflow-hidden bg-transparent outline-none focus:ring-0 p-0 m-0 ${className}`} rows={1} spellCheck={false} />
  );
};

export const ProjectRunner: React.FC<ProjectRunnerProps> = ({
  project, template, onUpdateProject, onUpdateTemplate, onRequestConfirm, fontSizeClass = 'text-sm', rightPanelWidth, onRightPanelWidthChange, isRightPanelOpen, onRightPanelOpenChange
}) => {
  const [collapsedSteps, setCollapsedSteps] = useState<Record<string, boolean>>({});
  const [isResizingRight, setIsResizingRight] = useState(false);
  const { toasts, showToast, removeToast } = useToast();

  const interpolate = (templateStr: string): string => {
    if (!templateStr) return "";
    let result = templateStr;

    // 1. Global Inputs <0>, <1>... or <Name>
    template.inputs.forEach((input, index) => {
      const val = project.inputValues[input.id] || "";
      result = result.split(`<${index}>`).join(val);
      result = result.split(`<${input.label}>`).join(val);
    });

    // 2. Local Custom Variables <l1>, <l2>... or <Name>
    (project.customInputs || []).forEach((input, index) => {
       const val = project.inputValues[input.id] || "";
       result = result.split(`<l${index + 1}>`).join(val);
       result = result.split(`<${input.label}>`).join(val);
    });

    // 3. Step Output Referencing [[1]], [[2]]... or [[Step Name]]
    template.steps.forEach((step, index) => {
      const output = project.stepOutputs[step.id] || "";
      result = result.split(`[[${index + 1}]]`).join(output);
      result = result.split(`[[${step.name}]]`).join(output);
    });

    return result;
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingRight) return;
      const newWidth = window.innerWidth - e.clientX;
      if (newWidth > 250 && newWidth < 1000) onRightPanelWidthChange(newWidth);
    };
    const handleMouseUp = () => { setIsResizingRight(false); document.body.style.cursor = 'default'; };
    if (isResizingRight) { window.addEventListener('mousemove', handleMouseMove); window.addEventListener('mouseup', handleMouseUp); document.body.style.cursor = 'col-resize'; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingRight, onRightPanelWidthChange]);

  const handleDoubleClickCopy = (content: string, e: React.MouseEvent) => {
    navigator.clipboard.writeText(content);
    showToast('复制成功', e.clientX, e.clientY);
  };

  return (
    <div className={`flex h-full w-full ${fontSizeClass}`}>
      <div className="flex-1 flex flex-col min-w-0">
         <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 pb-40 no-scrollbar">
            <div className="w-full space-y-8">
                {template.steps.map((step, index) => {
                const override = project.stepOverrides[step.id];
                const rawContent = override?.content !== undefined ? override.content : (step.content || "");
                const interpolated = interpolate(rawContent);
                const isCollapsed = collapsedSteps[step.id];

                return (
                    <div key={step.id} id={step.id} className={`border border-slate-800 rounded-2xl bg-slate-900/40 shadow-sm scroll-mt-8 overflow-hidden transition-all duration-300`}>
                    <div className="flex items-center justify-between px-6 py-4 bg-slate-900 border-b border-slate-800 cursor-pointer hover:bg-slate-800/80 transition-colors" onClick={() => setCollapsedSteps(p => ({...p, [step.id]: !isCollapsed}))}>
                        <div className="flex items-center space-x-4">
                            <span className="text-xs font-mono font-bold text-slate-500 bg-slate-800 px-2 py-0.5 rounded-md">{index + 1}</span>
                            <h3 className="font-black text-slate-200 text-sm tracking-tight">{step.name}</h3>
                        </div>
                        <div className="flex items-center gap-4">
                           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className={`w-5 h-5 text-slate-600 transition-transform ${isCollapsed ? '' : 'rotate-180'}`}><path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z" /></svg>
                        </div>
                    </div>

                    {!isCollapsed && (
                        <div className="p-6 bg-slate-900/20">
                            <PromptEditor label="提示词实时预览" templateContent={rawContent} interpolatedContent={interpolated} originalTemplateContent={step.content || ""} onUpdateOverride={(c) => onUpdateProject(project.id, { stepOverrides: { ...project.stepOverrides, [step.id]: { content: c } } })} onRevert={() => { const o = {...project.stepOverrides}; delete o[step.id]; onUpdateProject(project.id, { stepOverrides: o }); }} onSaveToTemplate={(c) => onRequestConfirm("保存到全局", "确定要将此步骤的局部修改保存回全局模版结构中吗？这会影响该模版下的所有项目。", () => { onUpdateTemplate(template.id, { steps: template.steps.map(s => s.id === step.id ? { ...s, content: c } : s) }); const o = {...project.stepOverrides}; delete o[step.id]; onUpdateProject(project.id, { stepOverrides: o }); })} />
                            <div className="mt-6 border-t border-slate-800/50 pt-6">
                                <div className="flex justify-between items-center mb-3">
                                  <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block">步骤输出 / 个人备注 (支持 [[序号]] 引用)</label>
                                  <button onClick={() => onUpdateProject(project.id, { stepOutputs: { ...project.stepOutputs, [step.id]: '' } })} className="text-[10px] text-slate-700 hover:text-red-400 uppercase tracking-tighter font-bold transition-colors">清除内容</button>
                                </div>
                                <div className={`bg-slate-950/50 border border-slate-800/60 rounded-xl px-4 py-3 transition-colors hover:border-slate-700`}>
                                  <AutoResizeTextarea 
                                    className="text-sm text-slate-400 leading-relaxed font-sans min-h-[60px]" 
                                    value={project.stepOutputs[step.id] || ''} 
                                    onChange={(val) => onUpdateProject(project.id, { stepOutputs: { ...project.stepOutputs, [step.id]: val } })} 
                                    placeholder="输入此步骤的生成结果、草稿或用于下一步骤引用的关键信息..." 
                                  />
                                </div>
                            </div>
                        </div>
                    )}
                    </div>
                );
                })}
            </div>
         </div>
      </div>

      {isRightPanelOpen && <div className="w-1.5 bg-slate-800 hover:bg-blue-600 cursor-col-resize z-30 flex-shrink-0 transition-colors" onMouseDown={(e) => { e.preventDefault(); setIsResizingRight(true); }} />}

      <div style={{ width: isRightPanelOpen ? rightPanelWidth : '40px' }} className="bg-slate-900 border-l border-slate-800 flex flex-col flex-shrink-0 transition-all duration-75 relative">
         <div className="flex items-center justify-between p-3 border-b border-slate-800 bg-slate-900 h-12 shrink-0">
             {isRightPanelOpen && <span className="font-bold text-[10px] text-slate-500 uppercase tracking-widest pl-3 truncate">拼接结果实时全览</span>}
             <button onClick={() => onRightPanelOpenChange(!isRightPanelOpen)} className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-500 hover:text-white transition-colors">{isRightPanelOpen ? "»" : "«"}</button>
         </div>
         {isRightPanelOpen && (
           <div className="flex-1 overflow-y-auto p-6 bg-slate-950/30 space-y-8 no-scrollbar">
             {template.steps.map((step, idx) => {
                const override = project.stepOverrides[step.id];
                const content = interpolate(override?.content !== undefined ? override.content : (step.content || ""));
                return (
                  <div key={step.id} className="relative group">
                    <div className="flex items-center gap-3 mb-3">
                      <span className="text-[11px] font-mono text-slate-600 font-bold">&lt;{idx+1}&gt;</span>
                      <span className="text-xs font-black text-slate-500 uppercase truncate tracking-tight">{step.name}</span>
                    </div>
                    <div 
                      onDoubleClick={(e) => handleDoubleClickCopy(content, e)}
                      className="text-slate-300 font-mono text-sm leading-relaxed whitespace-pre-wrap pl-4 py-2 border-l-2 border-slate-800 group-hover:border-blue-500/30 transition-colors relative cursor-copy select-none active:bg-blue-500/5"
                      title="双击复制内容"
                    >
                        {content}
                    </div>
                  </div>
                );
             })}
           </div>
         )}
      </div>

      <FloatingToast toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';

interface HighlightEffectProps {
  children: React.ReactNode;
  isActive: boolean;
  duration?: number;
}

export const HighlightEffect: React.FC<HighlightEffectProps> = ({ 
  children, 
  isActive, 
  duration = 3000 
}) => {
  const [show, setShow] = useState(isActive);

  useEffect(() => {
    if (isActive) {
      setShow(true);
      const timer = setTimeout(() => setShow(false), duration);
      return () => clearTimeout(timer);
    }
  }, [isActive, duration]);

  return (
    <div className="relative group/highlight">
      {show && (
        <>
          {/* 外围呼吸光圈 */}
          <div className="absolute -inset-1 bg-blue-500/50 rounded-2xl blur-md animate-pulse z-0 pointer-events-none"></div>
          {/* 边框高亮 */}
          <div className="absolute inset-0 border-2 border-blue-400 rounded-xl z-10 pointer-events-none animate-in fade-in duration-500"></div>
          {/* "NEW" 悬浮标签 */}
          <div className="absolute -top-3 -right-2 z-20 animate-bounce">
            <span className="bg-blue-500 text-white text-[9px] font-black px-2 py-0.5 rounded-full shadow-lg border border-blue-300/50 uppercase tracking-tighter">
              NEW
            </span>
          </div>
        </>
      )}
      <div className={`relative z-10 transition-transform duration-500 ${show ? 'scale-[1.02]' : 'scale-100'}`}>
        {children}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { Button } from './components/Button';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { 
  MenuIcon, 
  SettingsIcon, 
  CloseIcon, 
  VarsIcon, 
  NavIcon, 
  BuildIcon, 
  ChevronDownIcon, 
  DownloadIcon, 
  ProjectEmptyIcon 
} from './components/Icons';

const STORAGE_PROJECTS = 'prompt-splicer-projects-v2';
const STORAGE_TEMPLATES = 'prompt-splicer-templates-v2';
const STORAGE_SETTINGS = 'prompt-splicer-settings-v2';

type SidebarTab = 'vars' | 'nav' | 'build';
type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const AutoResizeSidebarTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = `${Math.max(32, el.scrollHeight)}px`;
    }
  };
  useLayoutEffect(() => {
    const timeout = setTimeout(adjustHeight, 0);
    return () => clearTimeout(timeout);
  }, [value]);
  return (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={`block w-full resize-none overflow-hidden bg-slate-950 border border-slate-700 rounded px-2 py-1.5 text-slate-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all ${className}`}
      rows={1}
      spellCheck={false}
    />
  );
};

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>(null);
  const [isLibraryOpen, setIsLibraryOpen] = useState(false);
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // 设置相关 - 默认比例调整为 8 (50% 模式)
  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(8);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const sidebarRef = useRef<HTMLDivElement>(null);
  const [activeSidebarTab, setActiveSidebarTab] = useState<SidebarTab>('vars');

  const [sidebarSections, setSidebarSections] = useState({ global: true, local: true });
  const [isAddingVariable, setIsAddingVariable] = useState(false);
  const [newVarName, setNewVarName] = useState("");
  const newVarInputRef = useRef<HTMLInputElement>(null);

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  useEffect(() => {
    // 1. 加载项目
    const savedProjects = localStorage.getItem(STORAGE_PROJECTS);
    if (savedProjects) {
       try {
         const loaded = JSON.parse(savedProjects);
         setProjects(loaded.map((p: any) => ({ ...p, customInputs: p.customInputs || [] })));
       } catch (e) {
         console.warn("Failed to load projects, clearing corrupted data...", e);
         localStorage.removeItem(STORAGE_PROJECTS);
         setProjects([]);
       }
    }

    // 2. 加载模版
    const savedTemplates = localStorage.getItem(STORAGE_TEMPLATES);
    if (savedTemplates) {
      try {
        const loadedTemplates = JSON.parse(savedTemplates);
        setTemplates(loadedTemplates);
      } catch (e) {
        console.warn("Failed to load templates, resetting...", e);
        localStorage.removeItem(STORAGE_TEMPLATES);
        setTemplates(DEFAULT_TEMPLATES);
      }
    } else {
      setTemplates(DEFAULT_TEMPLATES);
    }

    // 3. 加载设置
    const savedSettings = localStorage.getItem(STORAGE_SETTINGS);
    if (savedSettings) {
      try {
        const settings = JSON.parse(savedSettings);
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
      } catch (e) {
        console.warn("Failed to load settings, resetting...", e);
        localStorage.removeItem(STORAGE_SETTINGS);
      }
    }

    if (!activeTabId && !openTabIds.length) setIsLibraryOpen(true);
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_TEMPLATES, JSON.stringify(templates)); }, [templates]);
  useEffect(() => { localStorage.setItem(STORAGE_PROJECTS, JSON.stringify(projects)); }, [projects]);
  useEffect(() => {
    localStorage.setItem(STORAGE_SETTINGS, JSON.stringify({ uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize }));
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize]);

  useEffect(() => { if (isAddingVariable && newVarInputRef.current) newVarInputRef.current.focus(); }, [isAddingVariable]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const defaultInputs: Record<string, string> = {};
    template.inputs.forEach(inp => { if (inp.defaultValue) defaultInputs[inp.id] = inp.defaultValue; });
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: defaultInputs, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects([...projects, newProject]);
    // 修改：新建项目后不再自动打开，让用户在库中手动点开
    // openTab(newProject.id); 
  };

  const updateProjectTimestamp = (projectId: string, isModification: boolean = true) => {
    const now = Date.now();
    setProjects(prev => prev.map(p => {
        if (p.id === projectId) {
            return {
                ...p,
                lastOpenedAt: now,
                ...(isModification ? { lastModifiedAt: now } : {})
            };
        }
        return p;
    }));
  };

  const handleInputChange = (projectId: string, inputId: string, value: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const confirmAddLocalVariable = (projectId: string) => {
    const trimmed = newVarName.trim();
    if (!trimmed) { setIsAddingVariable(false); return; }
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    if (project.customInputs?.some(i => i.label === trimmed)) { openAlert("重名警告", "该变量名称已存在。"); return; }
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: trimmed };
    setProjects(prev => prev.map(p => {
      if (p.id === projectId) {
        return { 
          ...p, 
          lastModifiedAt: Date.now(), 
          customInputs: [...(p.customInputs || []), newInput] 
        };
      }
      return p;
    }));
    setNewVarName("");
    setIsAddingVariable(false);
  };

  const handleBakeDownload = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });

    const blob = new Blob([fullText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${project.name}_烘焙结果.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '变量1' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '内容 <0>' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
    setIsLibraryOpen(false);
  };

  const handleDownloadBackup = () => {
    const data = { projects, templates };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `prompt_splicer_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleCreateTemplateFromProject = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const sourceTemplate = templates.find(t => t.id === project.templateId);
    if (!sourceTemplate) return;

    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `${project.name} (从项目提取)`,
      inputs: [
        ...sourceTemplate.inputs.map(i => ({ ...i, defaultValue: project.inputValues[i.id] || i.defaultValue })),
        ...(project.customInputs || []).map(i => ({ ...i, defaultValue: project.inputValues[i.id] }))
      ],
      steps: sourceTemplate.steps.map(s => {
        const override = project.stepOverrides[s.id];
        return {
          ...s,
          content: override?.content !== undefined ? override.content : (s.content || "")
        };
      })
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
    setIsLibraryOpen(false);
  };

  const openTab = (id: string) => { 
    if (!openTabIds.includes(id)) setOpenTabIds([...openTabIds, id]); 
    setActiveTabId(id); 
    setIsLibraryOpen(false); 
    updateProjectTimestamp(id, false);
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    const newTabs = openTabIds.filter(tid => tid !== id);
    setOpenTabIds(newTabs);
    if (activeTabId === id) {
      if (newTabs.length > 0) setActiveTabId(newTabs[newTabs.length - 1]);
      else { setActiveTabId(null); setIsLibraryOpen(true); }
    }
  };

  const sortedProjects = [...projects].sort((a, b) => (b.lastOpenedAt || 0) - (a.lastOpenedAt || 0));

  const activeProject = projects.find(p => p.id === activeTabId);
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      {/* Top Header - Height increased to h-14 for "expanded" look and added overflow-hidden to prevent vertical scroll */}
      <div className="flex items-center bg-slate-900 h-14 border-b border-slate-800 shrink-0 pr-4 z-30 relative shadow-sm overflow-hidden">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className={`w-14 h-full flex items-center justify-center text-slate-400 hover:text-white border-r border-slate-800 hover:bg-slate-800 transition-colors shrink-0 ${isSidebarOpen ? 'bg-slate-800 text-white' : ''}`}>
             <MenuIcon className="w-5 h-5" />
           </button>

           <div className="px-5 font-bold text-slate-400 text-sm hidden sm:flex items-center gap-3 shrink-0">
              <span className="tracking-tight">提示词拼接器 Pro</span>
              <button 
                onClick={() => setIsSettingsOpen(true)}
                className="p-1.5 text-slate-600 hover:text-blue-400 transition-colors"
                title="应用设置"
              >
                <SettingsIcon className="w-4 h-4" />
              </button>
           </div>

           {/* Tab container - Fixed vertical scroll issue with overflow-y-hidden */}
           <div className="flex-1 flex overflow-x-auto overflow-y-hidden no-scrollbar items-end h-full px-3 gap-0.5">
             {openTabIds.map(id => {
               const p = projects.find(proj => proj.id === id);
               if (!p) return null;
               const isActive = activeTabId === id;
               return (
                 <div 
                   key={id} 
                   onClick={() => openTab(id)} 
                   onDoubleClick={(e) => closeTab(id, e)}
                   className={`group relative flex items-center gap-2 px-4 py-2 min-w-[120px] max-w-[200px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${isActive ? 'bg-slate-950 border-slate-800 text-white z-10 border-b-slate-950' : 'bg-slate-900 border-transparent text-slate-500 border-b-slate-800'}`} 
                   style={{ marginBottom: '-1px' }}
                   title="双击可关闭标签页"
                 >
                   <span className="truncate flex-1">{p.name}</span>
                   <button onClick={(e) => closeTab(id, e)} className="p-1 rounded-full hover:bg-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity">
                     <CloseIcon className="w-3 h-3" />
                   </button>
                 </div>
               );
             })}
           </div>

           <button onClick={() => setIsLibraryOpen(true)} className="flex items-center gap-1.5 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg text-sm font-bold shadow-lg shadow-blue-500/20 transition-all shrink-0">文件库</button>
      </div>

      <div className="flex-1 flex overflow-hidden relative">
        {/* Sidebar */}
        <div ref={sidebarRef} style={{ width: isSidebarOpen ? sidebarWidth : 0 }} className={`bg-slate-900 flex flex-shrink-0 z-20 transition-all duration-75 relative border-r border-slate-800 ${!isSidebarOpen && 'opacity-0 overflow-hidden'}`}>
          <div className="w-12 bg-slate-950 flex flex-col items-center py-6 border-r border-slate-800 gap-6 shrink-0">
             {activeProject && (
               <>
                 <button onClick={() => setActiveSidebarTab('vars')} title="变量配置" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'vars' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/30' : 'text-slate-600 hover:text-slate-300'}`}>
                   <VarsIcon className="w-5 h-5" />
                 </button>
                 <button onClick={() => setActiveSidebarTab('nav')} title="步骤导航" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'nav' ? 'bg-amber-600 text-white shadow-lg shadow-amber-600/30' : 'text-slate-600 hover:text-slate-300'}`}>
                   <NavIcon className="w-5 h-5" />
                 </button>
                 <button onClick={() => setActiveSidebarTab('build')} title="导出烘焙" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'build' ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/30' : 'text-slate-600 hover:text-slate-300'}`}>
                   <BuildIcon className="w-5 h-5" />
                 </button>
               </>
             )}
          </div>
          <div className="flex-1 flex flex-col bg-slate-900 overflow-hidden relative">
             <div className="flex-1 overflow-hidden flex flex-col">
                {activeProject && activeProjectTemplate && (
                <>
                    {activeSidebarTab === 'vars' && (
                    <div className="flex flex-col h-full overflow-y-auto p-4 space-y-6">
                        <div className="space-y-3">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, global: !s.global}))}>
                                <span className="text-xs font-bold text-slate-500 uppercase tracking-wider group-hover:text-slate-300 transition-colors">全局变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-slate-600 transition-transform ${sidebarSections.global ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.global && activeProjectTemplate.inputs.map((input, idx) => (
                            <div key={input.id}>
                                <div className="flex items-center gap-2 mb-1.5">
                                    <span className="text-[11px] font-mono text-blue-400 font-bold">&lt;{idx}&gt;</span>
                                    <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                </div>
                                <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                            </div>
                            ))}
                        </div>
                        <div className="space-y-3 border-t border-slate-800 pt-4">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, local: !s.local}))}>
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-wider group-hover:text-emerald-400 transition-colors">本地变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-emerald-600/50 transition-transform ${sidebarSections.local ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.local && (
                            <>
                                {(activeProject.customInputs || []).map((input, idx) => (
                                <div key={input.id} className="group relative">
                                    <div className="flex items-center gap-2 mb-1.5">
                                        <span className="text-[11px] font-mono text-emerald-400 font-bold">&lt;l{idx+1}&gt;</span>
                                        <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                    </div>
                                    <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                                    <button onClick={() => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), customInputs: (p.customInputs || []).filter(i => i.id !== input.id) } : p))} className="absolute top-0 right-0 text-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1">×</button>
                                </div>
                                ))}
                                {isAddingVariable ? (
                                <div className="bg-slate-950 border border-emerald-900/50 rounded-lg p-3 animate-in slide-in-from-top-1 duration-150">
                                    <input ref={newVarInputRef} type="text" className="w-full bg-slate-900 border border-slate-700 rounded-md px-3 py-2 text-sm text-white focus:border-emerald-500 outline-none" placeholder="输入变量名称..." value={newVarName} onChange={(e) => setNewVarName(e.target.value)} onKeyDown={(e) => { if(e.key === 'Enter') confirmAddLocalVariable(activeProject.id); if(e.key === 'Escape') setIsAddingVariable(false); }} />
                                    <div className="flex justify-end gap-2 mt-3">
                                    <button onClick={() => setIsAddingVariable(false)} className="text-xs text-slate-500 px-2 py-1 hover:text-white">取消</button>
                                    <button onClick={() => confirmAddLocalVariable(activeProject.id)} className="text-xs bg-emerald-600 hover:bg-emerald-500 text-white px-3 py-1 rounded-md transition-colors">添加</button>
                                    </div>
                                </div>
                                ) : (
                                <button onClick={() => setIsAddingVariable(true)} className="w-full py-2 border-2 border-dashed border-slate-700 rounded-lg text-xs text-slate-500 hover:border-emerald-500/50 hover:text-emerald-500 hover:bg-emerald-500/5 transition-all">+ 新增本地变量</button>
                                )}
                            </>
                            )}
                        </div>
                    </div>
                    )}

                    {activeSidebarTab === 'nav' && (
                        <div className="h-full overflow-y-auto p-3 space-y-2">
                            {activeProjectTemplate.steps.map((step, idx) => (
                                <button key={step.id} onClick={() => {
                                    const el = document.getElementById(step.id);
                                    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                }} className="w-full flex items-center gap-4 p-3 hover:bg-slate-800 rounded-lg text-left transition-all group active:scale-[0.98]">
                                    <span className="w-6 h-6 flex items-center justify-center shrink-0 bg-slate-800 border border-slate-700 text-xs font-bold text-slate-500 group-hover:border-amber-500 group-hover:text-amber-500 rounded-md transition-all">{idx+1}</span>
                                    <span className="text-sm text-slate-300 truncate font-medium">{step.name}</span>
                                </button>
                            ))}
                        </div>
                    )}

                    {activeSidebarTab === 'build' && (
                        <div className="p-6 flex flex-col items-center justify-center text-center h-full">
                            <div className="w-16 h-16 bg-purple-900/30 text-purple-400 rounded-2xl flex items-center justify-center mb-4 shadow-xl shadow-purple-950/20">
                                <DownloadIcon className="w-8 h-8" />
                            </div>
                            <h4 className="text-sm font-bold text-white mb-2">提示词全量烘焙</h4>
                            <p className="text-xs text-slate-500 mb-6 px-4 leading-relaxed">将当前项目的所有步骤一键导出为格式化纯文本，方便直接粘贴使用。</p>
                            <Button variant="primary" size="md" onClick={() => handleBakeDownload(activeProject.id)} className="w-full bg-purple-600 hover:bg-purple-500 shadow-lg shadow-purple-600/30">导出 .txt 烘焙文件</Button>
                        </div>
                    )}
                </>
                )}
             </div>
          </div>
          {isSidebarOpen && <div className="absolute right-0 top-0 bottom-0 w-1.5 bg-transparent hover:bg-blue-500 cursor-col-resize z-40 transition-colors" onMouseDown={() => setIsResizingSidebar(true)} />}
        </div>

        {/* Main Content */}
        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden">
           {activeProject && activeProjectTemplate ? (
             <div className="w-full h-full flex flex-col">
                <div className="px-8 pt-6 shrink-0 flex items-center justify-between">
                    <input 
                      type="text" 
                      value={activeProject.name} 
                      onChange={(e) => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), name: e.target.value } : p))} 
                      className="text-2xl font-black bg-transparent text-white border-none focus:ring-0 w-full p-0 tracking-tight" 
                    />
                </div>
                <div className="flex-1 overflow-hidden">
                    <ProjectRunner project={activeProject} template={activeProjectTemplate} 
                        onUpdateProject={(id, u) => {
                            setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p));
                        }} 
                        onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} 
                        onRequestConfirm={openConfirm} 
                        rightPanelWidth={rightPanelWidth} 
                        onRightPanelWidthChange={setRightPanelWidth} 
                        isRightPanelOpen={isRightPanelOpen} 
                        onRightPanelOpenChange={setIsRightPanelOpen} 
                        fontSizeClass={fontSize}
                    />
                </div>
             </div>
           ) : (
             <div className="w-full h-full flex items-center justify-center flex-col text-slate-700">
               <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center mb-4 text-slate-800">
                 <ProjectEmptyIcon className="w-10 h-10" />
               </div>
               <p className="text-sm font-medium">当前未打开任何项目</p>
               <Button variant="ghost" onClick={() => setIsLibraryOpen(true)} className="mt-4 text-slate-400 hover:text-blue-400" size="md">打开项目库</Button>
             </div>
           )}

           {isLibraryOpen && <FileLibrary projects={sortedProjects} templates={templates} onOpenProject={openTab} onCreateProject={createProject} onCreateTemplate={createTemplate} onEditTemplate={(id) => { setEditingTemplateId(id); setIsLibraryOpen(false); }} onDuplicateTemplate={(id) => setTemplates([...templates, { ...JSON.parse(JSON.stringify(templates.find(t => t.id === id))), id: `tmpl_${Date.now()}_copy`, name: `副本` }])} onCreateTemplateFromProject={(id) => openConfirm("提取模版", "从该项目状态提取出新的模版结构？", () => handleCreateTemplateFromProject(id))} onDeleteProject={(id) => openConfirm("删除项目", "确定要彻底删除该项目吗？数据将无法挽回。", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} onDeleteTemplate={(id) => openConfirm("删除模版", "确定要删除此模版吗？基于此模版的项目可能会出现显示异常。", () => setTemplates(templates.filter(t => t.id !== id)))} onImportData={(p, t) => { setProjects([...p]); setTemplates([...t]); }} onOpenExport={() => setIsExportModalOpen(true)} onRequestAlert={openAlert} onClose={() => setIsLibraryOpen(false)} />}
           {editingTemplateId && <div className="absolute inset-0 bg-slate-950 z-50 p-8 overflow-hidden animate-in zoom-in-95 duration-200"><TemplateEditor template={templates.find(t => t.id === editingTemplateId)!} onSave={(updated) => { setTemplates(prev => prev.map(t => t.id === updated.id ? updated : t)); setEditingTemplateId(null); setIsLibraryOpen(true); }} onCancel={() => { setEditingTemplateId(null); setIsLibraryOpen(true); }} onRequestConfirm={openConfirm} /></div>}
        </div>
      </div>
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={handleDownloadBackup} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { CreateProjectModal } from './CreateProjectModal';
import { HighlightEffect } from './HighlightEffect';

interface FileLibraryProps {
  projects: Project[];
  templates: Template[];
  onOpenProject: (projectId: string) => void;
  onCreateProject: (templateId: string, name: string) => void;
  onCreateTemplate: () => void;
  onEditTemplate: (templateId: string) => void;
  onDuplicateTemplate: (templateId: string) => void;
  onCreateTemplateFromProject: (projectId: string) => void;
  onDeleteProject: (id: string) => void;
  onDeleteTemplate: (id: string) => void;
  onClose: () => void;
  onImportData: (projects: Project[], templates: Template[]) => void;
  onOpenExport: () => void;
  onRequestAlert: (title: string, message: string) => void;
}

const formatFullDate = (ts: number) => {
    const d = new Date(ts);
    return `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')} ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}:${d.getSeconds().toString().padStart(2,'0')}`;
};

type SortKey = 'lastModified' | 'createdAt' | 'name';

export const FileLibrary: React.FC<FileLibraryProps> = ({
  projects,
  templates,
  onOpenProject,
  onCreateProject,
  onCreateTemplate,
  onEditTemplate,
  onDuplicateTemplate,
  onCreateTemplateFromProject,
  onDeleteProject,
  onDeleteTemplate,
  onClose,
  onImportData,
  onOpenExport,
  onRequestAlert
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Library specific view settings
  const [sortBy, setSortBy] = useState<SortKey>('lastModified');
  const [cardScale, setCardScale] = useState<number>(300); // Min-width in pixels
  const [isGrouped, setIsGrouped] = useState<boolean>(false);

  // New project creation state
  const [createModalInfo, setCreateModalInfo] = useState<{ isOpen: boolean; templateId: string | null }>({
    isOpen: false,
    templateId: null
  });

  // Track the ID of the project created in THIS session for highlighting
  const [lastCreatedId, setLastCreatedId] = useState<string | null>(null);

  // Sorting logic
  const sortProjects = (projs: Project[]) => {
    return [...projs].sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'createdAt') return (b.createdAt || 0) - (a.createdAt || 0);
      return (b.lastModifiedAt || 0) - (a.lastModifiedAt || 0);
    });
  };

  // Logic to detect newly added project and trigger highlight
  useEffect(() => {
    if (projects.length > 0) {
      // If we just added a project, find the one with the latest createdAt timestamp
      const latest = [...projects].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
      // Only highlight if it was created within the last 5 seconds (to avoid highlighting old projects on library open)
      if (Date.now() - (latest.createdAt || 0) < 5000) {
        setLastCreatedId(latest.id);
      }
    }
  }, [projects.length]);

  // Grouping logic
  const groupedData = useMemo(() => {
    const sorted = sortProjects(projects);
    if (!isGrouped) return { 'all': sorted };

    const groups: Record<string, Project[]> = {};
    sorted.forEach(p => {
      const template = templates.find(t => t.id === p.templateId);
      const groupName = template?.name || '未分类项目';
      if (!groups[groupName]) groups[groupName] = [];
      groups[groupName].push(p);
    });
    return groups;
  }, [projects, sortBy, isGrouped, templates]);

  const handleCreateClick = (templateId: string) => {
    setCreateModalInfo({ isOpen: true, templateId });
  };

  const handleConfirmCreation = (name: string) => {
    if (createModalInfo.templateId) {
      onCreateProject(createModalInfo.templateId, name);
      setCreateModalInfo({ isOpen: false, templateId: null });
    }
  };

  const renderProjectCard = (p: Project) => {
    const template = templates.find(t => t.id === p.templateId);
    const cardContent = (
      <div key={p.id} onClick={() => onOpenProject(p.id)} className="group bg-slate-900 hover:bg-slate-800 border border-slate-800 hover:border-blue-500/50 rounded-xl p-4 cursor-pointer transition-all relative">
        <div className="mb-2">
            <h4 className="text-base font-bold text-slate-200 group-hover:text-white mb-1 truncate">{p.name}</h4>
            <div className="flex items-center gap-2">
                 <span className="text-[10px] bg-slate-950 text-slate-500 px-1.5 py-0.5 rounded border border-slate-800/50">模版: {template?.name || '已失效'}</span>
            </div>
        </div>
        <div className="flex flex-col gap-1 border-t border-slate-800/40 mt-3 pt-3">
            <div className="flex justify-between items-center text-[9px] font-mono text-slate-600">
                <span>创建: {formatFullDate(p.createdAt)}</span>
            </div>
            <div className="flex justify-between items-center text-[9px] font-mono text-blue-600/60">
                <span>最后修改: {formatFullDate(p.lastModifiedAt)}</span>
            </div>
        </div>
        <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={(e) => { e.stopPropagation(); onCreateTemplateFromProject(p.id); }} title="提取模版" className="text-slate-500 hover:text-blue-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M8 2a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 8 2ZM4.25 5a.75.75 0 0 1 .75-.75h1.5a.75.75 0 0 1 0 1.5H5v6.5h6v-6.5h-1.5a.75.75 0 0 1 0-1.5h1.5A1.5 1.5 0 0 1 12.5 5.75v6.5A1.5 1.5 0 0 1 11 13.75H5a1.5 1.5 0 0 1-1.5-1.5v-6.5A1.5 1.5 0 0 1 4.25 5Z" /></svg></button>
            <button onClick={(e) => { e.stopPropagation(); onDeleteProject(p.id); }} title="彻底删除" className="text-slate-500 hover:text-red-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
        </div>
      </div>
    );

    return (
      <HighlightEffect key={p.id} isActive={lastCreatedId === p.id}>
        {cardContent}
      </HighlightEffect>
    );
  };

  return (
    <div className="absolute inset-0 bg-slate-950 z-50 flex flex-col animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">文件库</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">本地项目管理器</span>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 mr-4">
            <input type="file" ref={fileInputRef} onChange={(e) => {
                const file = e.target.files?.[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = (event) => {
                  try {
                    const data = JSON.parse(event.target?.result as string);
                    if (data && Array.isArray(data.projects) && Array.isArray(data.templates)) onImportData(data.projects, data.templates);
                    else onRequestAlert('失败', '文件格式不匹配。');
                  } catch (err) { onRequestAlert('失败', '解析 JSON 失败。'); }
                };
                reader.readAsText(file);
                e.target.value = '';
            }} className="hidden" accept=".json" />
            <button onClick={() => fileInputRef.current?.click()} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">恢复数据</button>
