              ))}
            </div>
          </div>
        </div>
      </div>

      <CreateProjectModal 
        isOpen={createModalInfo.isOpen}
        onConfirm={handleConfirmCreation}
        onCancel={() => setCreateModalInfo({ isOpen: false, templateId: null })}
      />
    </div>
  );
};

/**
 * 集中化 I/O 服务
 * 后续接入 Tauri 2.0 时，只需修改此文件中的实现即可。
 * 例如：将 localStorage 替换为 @tauri-apps/plugin-store
 *      将 Blob 下载替换为 @tauri-apps/plugin-fs
 */

export const STORAGE_KEYS = {
  PROJECTS: 'prompt-splicer-projects-v2',
  TEMPLATES: 'prompt-splicer-templates-v2',
  SETTINGS: 'prompt-splicer-settings-v2',
};

export const ioService = {
  // --- 数据持久化 (可以替换为 Tauri Store) ---

  async saveToDisk(key: string, data: any): Promise<void> {
    localStorage.setItem(key, JSON.stringify(data));
  },

  async loadFromDisk<T>(key: string): Promise<T | null> {
    const data = localStorage.getItem(key);
    if (!data) return null;
    try {
      return JSON.parse(data) as T;
    } catch (e) {
      console.error(`Failed to parse data for key: ${key}`, e);
      return null;
    }
  },

  // --- 文件导出 (可以替换为 Tauri fs.writeTextFile) ---

  /**
   * 导出文本或 JSON 文件到用户本地
   */
  async exportFile(filename: string, content: string, mimeType: string = 'text/plain'): Promise<void> {
    // 浏览器环境下的下载实现
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    // Tauri 提示: 在 Tauri 中你可以使用 save() 对话框选择路径，然后使用 writeFile 写入。
  },

  // --- 文件导入 (可以替换为 Tauri dialog.open) ---

  /**
   * 处理文件上传读取
   */
  async readFileAsText(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => resolve(e.target?.result as string);
      reader.onerror = (e) => reject(e);
      reader.readAsText(file);
    });
  }
};

