  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化加载
  useEffect(() => {
    const init = async () => {
      // 1. 加载项目
      const loadedProjects = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (loadedProjects) {
        setProjects(loadedProjects.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      }

      // 2. 加载模版
      const loadedTemplates = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      if (loadedTemplates) {
        setTemplates(loadedTemplates);
      } else {
        setTemplates(DEFAULT_TEMPLATES);
      }

      // 3. 加载设置
      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
      }

      if (!activeTabId && !openTabIds.length) setIsLibraryOpen(true);
    };

    init();
  }, []);

  // 监听状态自动保存
  useEffect(() => { ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize]);

  useEffect(() => { if (isAddingVariable && newVarInputRef.current) newVarInputRef.current.focus(); }, [isAddingVariable]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const defaultInputs: Record<string, string> = {};
    template.inputs.forEach(inp => { if (inp.defaultValue) defaultInputs[inp.id] = inp.defaultValue; });
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: defaultInputs, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects([...projects, newProject]);
  };

  const updateProjectTimestamp = (projectId: string, isModification: boolean = true) => {
    const now = Date.now();
    setProjects(prev => prev.map(p => {
        if (p.id === projectId) {
            return { ...p, lastOpenedAt: now, ...(isModification ? { lastModifiedAt: now } : {}) };
        }
        return p;
    }));
  };

  const handleInputChange = (projectId: string, inputId: string, value: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const confirmAddLocalVariable = (projectId: string) => {
    const trimmed = newVarName.trim();
    if (!trimmed) { setIsAddingVariable(false); return; }
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    if (project.customInputs?.some(i => i.label === trimmed)) { openAlert("重名警告", "该变量名称已存在。"); return; }
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: trimmed };
    setProjects(prev => prev.map(p => {
      if (p.id === projectId) {
        return { 
          ...p, 
          lastModifiedAt: Date.now(), 
          customInputs: [...(p.customInputs || []), newInput] 
        };
      }
      return p;
    }));
    setNewVarName("");
    setIsAddingVariable(false);
  };

  const handleBakeDownload = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });

    ioService.exportFile(`${project.name}_烘焙结果.txt`, fullText);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '变量1' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '内容 <0>' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
    setIsLibraryOpen(false);
  };

  const handleDownloadBackup = () => {
    const data = { projects, templates };
    ioService.exportFile(`prompt_splicer_backup_${new Date().toISOString().split('T')[0]}.json`, JSON.stringify(data, null, 2), 'application/json');
  };

  const handleCreateTemplateFromProject = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const sourceTemplate = templates.find(t => t.id === project.templateId);
    if (!sourceTemplate) return;

    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `${project.name} (从项目提取)`,
      inputs: [
        ...sourceTemplate.inputs.map(i => ({ ...i, defaultValue: project.inputValues[i.id] || i.defaultValue })),
        ...(project.customInputs || []).map(i => ({ ...i, defaultValue: project.inputValues[i.id] }))
      ],
      steps: sourceTemplate.steps.map(s => {
        const override = project.stepOverrides[s.id];
        return {
          ...s,
          content: override?.content !== undefined ? override.content : (s.content || "")
        };
      })
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
    setIsLibraryOpen(false);
  };

  const openTab = (id: string) => { 
    if (!openTabIds.includes(id)) setOpenTabIds([...openTabIds, id]); 
    setActiveTabId(id); 
    setIsLibraryOpen(false); 
    updateProjectTimestamp(id, false);
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    const newTabs = openTabIds.filter(tid => tid !== id);
    setOpenTabIds(newTabs);
    if (activeTabId === id) {
      if (newTabs.length > 0) setActiveTabId(newTabs[newTabs.length - 1]);
      else { setActiveTabId(null); setIsLibraryOpen(true); }
    }
  };

  const sortedProjects = [...projects].sort((a, b) => (b.lastOpenedAt || 0) - (a.lastOpenedAt || 0));
  const activeProject = projects.find(p => p.id === activeTabId);
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      <div className="flex items-center bg-slate-900 h-14 border-b border-slate-800 shrink-0 pr-4 z-30 relative shadow-sm overflow-hidden">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className={`w-14 h-full flex items-center justify-center text-slate-400 hover:text-white border-r border-slate-800 hover:bg-slate-800 transition-colors shrink-0 ${isSidebarOpen ? 'bg-slate-800 text-white' : ''}`}>
             <MenuIcon className="w-5 h-5" />
           </button>
           <div className="px-5 font-bold text-slate-400 text-sm hidden sm:flex items-center gap-3 shrink-0">
              <span className="tracking-tight">提示词拼接器 Pro</span>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1.5 text-slate-600 hover:text-blue-400 transition-colors" title="应用设置"><SettingsIcon className="w-4 h-4" /></button>
           </div>
           <div className="flex-1 flex overflow-x-auto overflow-y-hidden no-scrollbar items-end h-full px-3 gap-0.5">
             {openTabIds.map(id => {
               const p = projects.find(proj => proj.id === id);
               if (!p) return null;
               const isActive = activeTabId === id;
               return (
                 <div key={id} onClick={() => openTab(id)} onDoubleClick={(e) => closeTab(id, e)} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[120px] max-w-[200px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${isActive ? 'bg-slate-950 border-slate-800 text-white z-10 border-b-slate-950' : 'bg-slate-900 border-transparent text-slate-500 border-b-slate-800'}`} style={{ marginBottom: '-1px' }} title="双击可关闭标签页">
                   <span className="truncate flex-1">{p.name}</span>
                   <button onClick={(e) => closeTab(id, e)} className="p-1 rounded-full hover:bg-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><CloseIcon className="w-3 h-3" /></button>
                 </div>
               );
             })}
           </div>
           <button onClick={() => setIsLibraryOpen(true)} className="flex items-center gap-1.5 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg text-sm font-bold shadow-lg shadow-blue-500/20 transition-all shrink-0">文件库</button>
      </div>

      <div className="flex-1 flex overflow-hidden relative">
        <div ref={sidebarRef} style={{ width: isSidebarOpen ? sidebarWidth : 0 }} className={`bg-slate-900 flex flex-shrink-0 z-20 transition-all duration-75 relative border-r border-slate-800 ${!isSidebarOpen && 'opacity-0 overflow-hidden'}`}>
          <div className="w-12 bg-slate-950 flex flex-col items-center py-6 border-r border-slate-800 gap-6 shrink-0">
             {activeProject && (
               <>
                 <button onClick={() => setActiveSidebarTab('vars')} title="变量配置" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'vars' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/30' : 'text-slate-600 hover:text-slate-300'}`}><VarsIcon className="w-5 h-5" /></button>
                 <button onClick={() => setActiveSidebarTab('nav')} title="步骤导航" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'nav' ? 'bg-amber-600 text-white shadow-lg shadow-amber-600/30' : 'text-slate-600 hover:text-slate-300'}`}><NavIcon className="w-5 h-5" /></button>
                 <button onClick={() => setActiveSidebarTab('build')} title="导出烘焙" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'build' ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/30' : 'text-slate-600 hover:text-slate-300'}`}><BuildIcon className="w-5 h-5" /></button>
               </>
             )}
          </div>
          <div className="flex-1 flex flex-col bg-slate-900 overflow-hidden relative">
             <div className="flex-1 overflow-hidden flex flex-col">
                {activeProject && activeProjectTemplate && (
                <>
                    {activeSidebarTab === 'vars' && (
                    <div className="flex flex-col h-full overflow-y-auto p-4 space-y-6">
                        <div className="space-y-3">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, global: !s.global}))}>
                                <span className="text-xs font-bold text-slate-500 uppercase tracking-wider group-hover:text-slate-300 transition-colors">全局变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-slate-600 transition-transform ${sidebarSections.global ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.global && activeProjectTemplate.inputs.map((input, idx) => (
                            <div key={input.id}>
                                <div className="flex items-center gap-2 mb-1.5">
                                    <span className="text-[11px] font-mono text-blue-400 font-bold">&lt;{idx}&gt;</span>
                                    <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                </div>
                                <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                            </div>
                            ))}
                        </div>
                        <div className="space-y-3 border-t border-slate-800 pt-4">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, local: !s.local}))}>
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-wider group-hover:text-emerald-400 transition-colors">本地变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-emerald-600/50 transition-transform ${sidebarSections.local ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.local && (
                            <>
                                {(activeProject.customInputs || []).map((input, idx) => (
                                <div key={input.id} className="group relative">
                                    <div className="flex items-center gap-2 mb-1.5">
                                        <span className="text-[11px] font-mono text-emerald-400 font-bold">&lt;l{idx+1}&gt;</span>
                                        <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                    </div>
                                    <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                                    <button onClick={() => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), customInputs: (p.customInputs || []).filter(i => i.id !== input.id) } : p))} className="absolute top-0 right-0 text-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1">×</button>
                                </div>
                                ))}
                                {isAddingVariable ? (
                                <div className="bg-slate-950 border border-emerald-900/50 rounded-lg p-3 animate-in slide-in-from-top-1 duration-150">
                                    <input ref={newVarInputRef} type="text" className="w-full bg-slate-900 border border-slate-700 rounded-md px-3 py-2 text-sm text-white focus:border-emerald-500 outline-none" placeholder="输入变量名称..." value={newVarName} onChange={(e) => setNewVarName(e.target.value)} onKeyDown={(e) => { if(e.key === 'Enter') confirmAddLocalVariable(activeProject.id); if(e.key === 'Escape') setIsAddingVariable(false); }} />
                                    <div className="flex justify-end gap-2 mt-3">
                                    <button onClick={() => setIsAddingVariable(false)} className="text-xs text-slate-500 px-2 py-1 hover:text-white">取消</button>
                                    <button onClick={() => confirmAddLocalVariable(activeProject.id)} className="text-xs bg-emerald-600 hover:bg-emerald-500 text-white px-3 py-1 rounded-md transition-colors">添加</button>
                                    </div>
                                </div>
                                ) : (
                                <button onClick={() => setIsAddingVariable(true)} className="w-full py-2 border-2 border-dashed border-slate-700 rounded-lg text-xs text-slate-500 hover:border-emerald-500/50 hover:text-emerald-500 hover:bg-emerald-500/5 transition-all">+ 新增本地变量</button>
                                )}
                            </>
                            )}
                        </div>
                    </div>
                    )}
                    {activeSidebarTab === 'nav' && (
                        <div className="h-full overflow-y-auto p-3 space-y-2">
                            {activeProjectTemplate.steps.map((step, idx) => (
                                <button key={step.id} onClick={() => {
                                    const el = document.getElementById(step.id);
                                    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                }} className="w-full flex items-center gap-4 p-3 hover:bg-slate-800 rounded-lg text-left transition-all group active:scale-[0.98]">
                                    <span className="w-6 h-6 flex items-center justify-center shrink-0 bg-slate-800 border border-slate-700 text-xs font-bold text-slate-500 group-hover:border-amber-500 group-hover:text-amber-500 rounded-md transition-all">{idx+1}</span>
                                    <span className="text-sm text-slate-300 truncate font-medium">{step.name}</span>
                                </button>
                            ))}
                        </div>
                    )}
                    {activeSidebarTab === 'build' && (
                        <div className="p-6 flex flex-col items-center justify-center text-center h-full">
                            <div className="w-16 h-16 bg-purple-900/30 text-purple-400 rounded-2xl flex items-center justify-center mb-4 shadow-xl shadow-purple-950/20"><DownloadIcon className="w-8 h-8" /></div>
                            <h4 className="text-sm font-bold text-white mb-2">提示词全量烘焙</h4>
                            <p className="text-xs text-slate-500 mb-6 px-4 leading-relaxed">将当前项目的所有步骤一键导出为格式化纯文本，方便直接粘贴使用。</p>
                            <Button variant="primary" size="md" onClick={() => handleBakeDownload(activeProject.id)} className="w-full bg-purple-600 hover:bg-purple-500 shadow-lg shadow-purple-600/30">导出 .txt 烘焙文件</Button>
                        </div>
                    )}
                </>
                )}
             </div>
          </div>
          {isSidebarOpen && <div className="absolute right-0 top-0 bottom-0 w-1.5 bg-transparent hover:bg-blue-500 cursor-col-resize z-40 transition-colors" onMouseDown={() => setIsResizingSidebar(true)} />}
        </div>

        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden">
           {activeProject && activeProjectTemplate ? (
             <div className="w-full h-full flex flex-col">
                <div className="px-8 pt-6 shrink-0 flex items-center justify-between">
                    <input type="text" value={activeProject.name} onChange={(e) => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), name: e.target.value } : p))} className="text-2xl font-black bg-transparent text-white border-none focus:ring-0 w-full p-0 tracking-tight" />
                </div>
                <div className="flex-1 overflow-hidden">
                    <ProjectRunner project={activeProject} template={activeProjectTemplate} onUpdateProject={(id, u) => { setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p)); }} onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} onRequestConfirm={openConfirm} rightPanelWidth={rightPanelWidth} onRightPanelWidthChange={setRightPanelWidth} isRightPanelOpen={isRightPanelOpen} onRightPanelOpenChange={setIsRightPanelOpen} fontSizeClass={fontSize} />
                </div>
             </div>
           ) : (
             <div className="w-full h-full flex items-center justify-center flex-col text-slate-700">
               <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center mb-4 text-slate-800"><ProjectEmptyIcon className="w-10 h-10" /></div>
               <p className="text-sm font-medium">当前未打开任何项目</p>
               <Button variant="ghost" onClick={() => setIsLibraryOpen(true)} className="mt-4 text-slate-400 hover:text-blue-400" size="md">打开项目库</Button>
             </div>
           )}

           {isLibraryOpen && <FileLibrary projects={sortedProjects} templates={templates} onOpenProject={openTab} onCreateProject={createProject} onCreateTemplate={createTemplate} onEditTemplate={(id) => { setEditingTemplateId(id); setIsLibraryOpen(false); }} onDuplicateTemplate={(id) => setTemplates([...templates, { ...JSON.parse(JSON.stringify(templates.find(t => t.id === id))), id: `tmpl_${Date.now()}_copy`, name: `副本` }])} onCreateTemplateFromProject={(id) => openConfirm("提取模版", "从该项目状态提取出新的模版结构？", () => handleCreateTemplateFromProject(id))} onDeleteProject={(id) => openConfirm("删除项目", "确定要彻底删除该项目吗？数据将无法挽回。", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} onDeleteTemplate={(id) => openConfirm("删除模版", "确定要删除此模版吗？基于此模版的项目可能会出现显示异常。", () => setTemplates(templates.filter(t => t.id !== id)))} onImportData={(p, t) => { setProjects([...p]); setTemplates([...t]); }} onOpenExport={() => setIsExportModalOpen(true)} onRequestAlert={openAlert} onClose={() => setIsLibraryOpen(false)} />}
           {editingTemplateId && <div className="absolute inset-0 bg-slate-950 z-50 p-8 overflow-hidden animate-in zoom-in-95 duration-200"><TemplateEditor template={templates.find(t => t.id === editingTemplateId)!} onSave={(updated) => { setTemplates(prev => prev.map(t => t.id === updated.id ? updated : t)); setEditingTemplateId(null); setIsLibraryOpen(true); }} onCancel={() => { setEditingTemplateId(null); setIsLibraryOpen(true); }} onRequestConfirm={openConfirm} /></div>}
        </div>
      </div>
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={handleDownloadBackup} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { CreateProjectModal } from './CreateProjectModal';
import { HighlightEffect } from './HighlightEffect';
import { ioService } from '../services/ioService';

interface FileLibraryProps {
  projects: Project[];
  templates: Template[];
  onOpenProject: (projectId: string) => void;
  onCreateProject: (templateId: string, name: string) => void;
  onCreateTemplate: () => void;
  onEditTemplate: (templateId: string) => void;
  onDuplicateTemplate: (templateId: string) => void;
  onCreateTemplateFromProject: (projectId: string) => void;
  onDeleteProject: (id: string) => void;
  onDeleteTemplate: (id: string) => void;
  onClose: () => void;
  onImportData: (projects: Project[], templates: Template[]) => void;
  onOpenExport: () => void;
  onRequestAlert: (title: string, message: string) => void;
}

const formatFullDate = (ts: number) => {
    const d = new Date(ts);
    return `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')} ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}:${d.getSeconds().toString().padStart(2,'0')}`;
};

type SortKey = 'lastModified' | 'createdAt' | 'name';

export const FileLibrary: React.FC<FileLibraryProps> = ({
  projects,
  templates,
  onOpenProject,
  onCreateProject,
  onCreateTemplate,
  onEditTemplate,
  onDuplicateTemplate,
  onCreateTemplateFromProject,
  onDeleteProject,
  onDeleteTemplate,
  onClose,
  onImportData,
  onOpenExport,
  onRequestAlert
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [sortBy, setSortBy] = useState<SortKey>('lastModified');
  const [cardScale, setCardScale] = useState<number>(300);
  const [isGrouped, setIsGrouped] = useState<boolean>(false);
  const [createModalInfo, setCreateModalInfo] = useState<{ isOpen: boolean; templateId: string | null }>({
    isOpen: false,
    templateId: null
  });
  const [lastCreatedId, setLastCreatedId] = useState<string | null>(null);

  const sortProjects = (projs: Project[]) => {
    return [...projs].sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'createdAt') return (b.createdAt || 0) - (a.createdAt || 0);
      return (b.lastModifiedAt || 0) - (a.lastModifiedAt || 0);
    });
  };

  useEffect(() => {
    if (projects.length > 0) {
      const latest = [...projects].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
      if (Date.now() - (latest.createdAt || 0) < 5000) {
        setLastCreatedId(latest.id);
      }
    }
  }, [projects.length]);

  const groupedData = useMemo(() => {
    const sorted = sortProjects(projects);
    if (!isGrouped) return { 'all': sorted };
    const groups: Record<string, Project[]> = {};
    sorted.forEach(p => {
      const template = templates.find(t => t.id === p.templateId);
      const groupName = template?.name || '未分类项目';
      if (!groups[groupName]) groups[groupName] = [];
      groups[groupName].push(p);
    });
    return groups;
  }, [projects, sortBy, isGrouped, templates]);

  const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const content = await ioService.readFileAsText(file);
      const data = JSON.parse(content);
      if (data && Array.isArray(data.projects) && Array.isArray(data.templates)) {
        onImportData(data.projects, data.templates);
      } else {
        onRequestAlert('失败', '文件格式不匹配。');
      }
    } catch (err) {
      onRequestAlert('失败', '文件读取或解析 JSON 失败。');
    }
    e.target.value = '';
  };

  const renderProjectCard = (p: Project) => {
    const template = templates.find(t => t.id === p.templateId);
    return (
      <HighlightEffect key={p.id} isActive={lastCreatedId === p.id}>
        <div onClick={() => onOpenProject(p.id)} className="group bg-slate-900 hover:bg-slate-800 border border-slate-800 hover:border-blue-500/50 rounded-xl p-4 cursor-pointer transition-all relative">
          <div className="mb-2">
              <h4 className="text-base font-bold text-slate-200 group-hover:text-white mb-1 truncate">{p.name}</h4>
              <div className="flex items-center gap-2"><span className="text-[10px] bg-slate-950 text-slate-500 px-1.5 py-0.5 rounded border border-slate-800/50">模版: {template?.name || '已失效'}</span></div>
          </div>
          <div className="flex flex-col gap-1 border-t border-slate-800/40 mt-3 pt-3">
              <div className="flex justify-between items-center text-[9px] font-mono text-slate-600"><span>创建: {formatFullDate(p.createdAt)}</span></div>
              <div className="flex justify-between items-center text-[9px] font-mono text-blue-600/60"><span>最后修改: {formatFullDate(p.lastModifiedAt)}</span></div>
          </div>
          <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              <button onClick={(e) => { e.stopPropagation(); onCreateTemplateFromProject(p.id); }} title="提取模版" className="text-slate-500 hover:text-blue-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M8 2a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 8 2ZM4.25 5a.75.75 0 0 1 .75-.75h1.5a.75.75 0 0 1 0 1.5H5v6.5h6v-6.5h-1.5a.75.75 0 0 1 0-1.5h1.5A1.5 1.5 0 0 1 12.5 5.75v6.5A1.5 1.5 0 0 1 11 13.75H5a1.5 1.5 0 0 1-1.5-1.5v-6.5A1.5 1.5 0 0 1 4.25 5Z" /></svg></button>
              <button onClick={(e) => { e.stopPropagation(); onDeleteProject(p.id); }} title="彻底删除" className="text-slate-500 hover:text-red-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
          </div>
        </div>
      </HighlightEffect>
    );
  };

  return (
    <div className="absolute inset-0 bg-slate-950 z-50 flex flex-col animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">文件库</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">本地项目管理器</span>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 mr-4">
            <input type="file" ref={fileInputRef} onChange={handleImportFile} className="hidden" accept=".json" />
            <button onClick={() => fileInputRef.current?.click()} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">恢复数据</button>
            <button onClick={onOpenExport} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">备份数据</button>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white p-2 rounded-full hover:bg-slate-800 transition-colors"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg></button>
        </div>
      </div>
      <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-950">
         <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8 flex flex-col">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-6 pb-2 border-b border-slate-800/50">
                <h3 className="text-sm font-bold text-blue-400 uppercase tracking-widest">我的游戏项目</h3>
                <div className="flex flex-wrap items-center gap-6">
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] text-slate-500 font-bold uppercase whitespace-nowrap">卡片缩放</span>
                    <input type="range" min="150" max="500" value={cardScale} onChange={(e) => setCardScale(parseInt(e.target.value))} className="w-32 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-600"/>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setIsGrouped(!isGrouped)} className={`flex items-center gap-2 px-3 py-1 text-[10px] font-bold rounded border transition-colors ${isGrouped ? 'bg-blue-600/20 border-blue-500/50 text-blue-400' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-slate-300'}`}><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M2 3.75A.75.75 0 0 1 2.75 3h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 3.75ZM2 8a.75.75 0 0 1 .75-.75h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 8Zm.75 3.5a.75.75 0 0 0 0 1.5h10.5a.75.75 0 0 0 0-1.5H2.75Z" /></svg>{isGrouped ? '已分类显示' : '平铺显示'}</button>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] text-slate-500 font-bold uppercase">排序</span>
                    <select value={sortBy} onChange={(e) => setSortBy(e.target.value as SortKey)} className="bg-slate-900 border border-slate-800 rounded px-2 py-1 text-[10px] text-slate-400 outline-none hover:border-slate-600 transition-colors"><option value="lastModified">最后修改时间</option><option value="createdAt">创建时间</option><option value="name">项目名称</option></select>
                  </div>
                </div>
            </div>
            <div className="space-y-10">
              {Object.entries(groupedData).map(([groupName, projs]) => (
                <div key={groupName} className="space-y-4">
                  {isGrouped && (<div className="flex items-center gap-3"><div className="h-4 w-1 bg-blue-500 rounded-full"></div><h4 className="text-xs font-black text-slate-500 uppercase tracking-tighter">{groupName} <span className="ml-2 text-[10px] font-normal text-slate-700">({(projs as Project[]).length} 个项目)</span></h4></div>)}
                  <div className="grid gap-4" style={{ gridTemplateColumns: `repeat(auto-fill, minmax(${cardScale}px, 1fr))` }}>{(projs as Project[]).map(p => renderProjectCard(p))}</div>
                </div>
              ))}
            </div>
          </div>
          <div className="lg:col-span-4">
             <div className="flex items-center justify-between mb-6 pb-2 border-b border-slate-800/50"><h3 className="text-sm font-bold text-emerald-400 uppercase tracking-widest">快速创建</h3><button onClick={onCreateTemplate} className="text-[10px] text-slate-500 hover:text-white transition-colors underline underline-offset-4">新建模版</button></div>
             <div className="grid grid-cols-1 gap-3">
              {templates.map(t => (
                <div key={t.id} className="bg-slate-900/50 border border-slate-800 rounded-lg p-4 transition-colors">
                  <h4 className="font-bold text-slate-200 text-sm mb-1">{t.name}</h4>
                  <div className="flex gap-2 text-[9px] text-slate-600 mb-4 font-mono"><span>{t.steps.length} STEPS</span><span>{t.inputs.length} VARS</span></div>
                  <div className="flex gap-2">
                      <Button onClick={() => setCreateModalInfo({ isOpen: true, templateId: t.id })} className="flex-1 h-8 text-[11px]" size="sm" variant="success">使用此模版</Button>
                      <button onClick={() => onEditTemplate(t.id)} className="px-3 bg-slate-950 border border-slate-800 text-[10px] text-slate-500 hover:text-white rounded" title="编辑模版结构">编辑</button>
                      <button onClick={() => onDeleteTemplate(t.id)} className="px-2 bg-slate-950 border border-slate-800 text-slate-500 hover:text-red-400 rounded transition-colors" title="删除模版"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
      <CreateProjectModal isOpen={createModalInfo.isOpen} onConfirm={(name) => { if (createModalInfo.templateId) { onCreateProject(createModalInfo.templateId, name); setCreateModalInfo({ isOpen: false, templateId: null }); } }} onCancel={() => setCreateModalInfo({ isOpen: false, templateId: null })} />
    </div>
  );
};

/**
 * 集中化 I/O 服务
 * 
 * --- Tauri 2.0 接入指南 ---
 * 1. 修改下方 IS_TAURI 为 true。
 * 2. 确保已安装插件: 
 *    npm add @tauri-apps/plugin-store @tauri-apps/plugin-fs @tauri-apps/plugin-dialog
 * 3. 在 src-tauri/capabilities/main.json 中添加权限:
 *    "permissions": [
 *      "store:allow-get", "store:allow-set", "store:allow-save",
 *      "fs:allow-write-text-file", "fs:allow-read-text-file",
 *      "dialog:allow-save", "dialog:allow-open"
 *    ]
 */

// --- 宏定义开关 ---
const IS_TAURI = false; 

// --- Tauri 模块导入 (使用时取消注释) ---
// import { load } from "@tauri-apps/plugin-store";
// import { save, open } from "@tauri-apps/plugin-dialog";
// import { writeTextFile, readTextFile } from "@tauri-apps/plugin-fs";

export const STORAGE_KEYS = {
  PROJECTS: 'prompt-splicer-projects-v2',
  TEMPLATES: 'prompt-splicer-templates-v2',
  SETTINGS: 'prompt-splicer-settings-v2',
};

export const ioService = {
  // --- 数据持久化 ---

  async saveToDisk(key: string, data: any): Promise<void> {
    if (IS_TAURI) {
      /**
       * [TAURI 实现]
       * const store = await load("app_data.json", { autoSave: true });
       * await store.set(key, data);
       * await store.save(); 
       */
      console.log('Tauri Save Triggered (Mock):', key);
    } else {
      localStorage.setItem(key, JSON.stringify(data));
    }
  },

  async loadFromDisk<T>(key: string): Promise<T | null> {
    if (IS_TAURI) {
      /**
       * [TAURI 实现]
       * const store = await load("app_data.json");
       * const val = await store.get<T>(key);
       * return val || null;
       */
      console.log('Tauri Load Triggered (Mock):', key);
      return null;
    } else {
      const data = localStorage.getItem(key);
      if (!data) return null;
      try {
        return JSON.parse(data) as T;
      } catch (e) {
        console.error(`Failed to parse data for key: ${key}`, e);
        return null;
      }
    }
  },

  // --- 文件导出 ---

  /**
   * 导出文本或 JSON 文件到用户本地
   */
  async exportFile(filename: string, content: string, mimeType: string = 'text/plain'): Promise<void> {
    if (IS_TAURI) {
      /**
       * [TAURI 实现]
       * // 弹出保存对话框
       * const path = await save({
       *   defaultPath: filename,
       *   filters: [{ name: 'Document', extensions: mimeType.includes('json') ? ['json'] : ['txt'] }]
       * });
       * // 如果用户选择了路径，则写入文件
       * if (path) {
       *   await writeTextFile(path, content);
       * }
       */
      console.log('Tauri Export File Triggered (Mock):', filename);
    } else {
      // 浏览器环境下的下载实现
      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }
  },

  // --- 文件导入 ---

  /**
   * 处理文件上传读取
   * 在 Tauri 模式下，这个函数可能直接由 UI 调用 dialog.open 触发，不需要 HTML Input 传入 File 对象
   */
  async readFileAsText(file?: File): Promise<string> {
    if (IS_TAURI) {
      /**
       * [TAURI 实现]
       * // 弹出打开对话框
       * const path = await open({
       *   multiple: false,
       *   filters: [{ name: 'JSON Data', extensions: ['json'] }]
       * });
       * // 如果选择了文件，读取其文本内容
       * if (path && typeof path === 'string') {
       *   return await readTextFile(path);
       * }
       * return "";
       */
      console.log('Tauri Read File Triggered (Mock)');
      return "";
    } else {
      if (!file) throw new Error("No file provided for browser upload");
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve(e.target?.result as string);
        reader.onerror = (e) => reject(e);
        reader.readAsText(file);
      });
    }
  }
};

import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { Button } from './components/Button';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { ioService, STORAGE_KEYS } from './services/ioService';
import { 
  MenuIcon, 
  SettingsIcon, 
  CloseIcon, 
  VarsIcon, 
  NavIcon, 
  BuildIcon, 
  ChevronDownIcon, 
  DownloadIcon, 
  ProjectEmptyIcon,
  ProjectEmptyIcon as LibraryIcon
} from './components/Icons';

type SidebarTab = 'vars' | 'nav' | 'build';
type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const AutoResizeSidebarTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = `${Math.max(32, el.scrollHeight)}px`;
    }
  };
  useLayoutEffect(() => {
    const timeout = setTimeout(adjustHeight, 0);
    return () => clearTimeout(timeout);
  }, [value]);
  return (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={`block w-full resize-none overflow-hidden bg-slate-950 border border-slate-700 rounded px-2 py-1.5 text-slate-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all ${className}`}
      rows={1}
      spellCheck={false}
    />
  );
};

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>('library');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(16);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const sidebarRef = useRef<HTMLDivElement>(null);
  const [activeSidebarTab, setActiveSidebarTab] = useState<SidebarTab>('vars');

  const [sidebarSections, setSidebarSections] = useState({ global: true, local: true });
  const [isAddingVariable, setIsAddingVariable] = useState(false);
  const [newVarName, setNewVarName] = useState("");
  const newVarInputRef = useRef<HTMLInputElement>(null);

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化加载
  useEffect(() => {
    const init = async () => {
      const loadedProjects = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (loadedProjects) {
        setProjects(loadedProjects.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      }

      const loadedTemplates = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      if (loadedTemplates) {
        setTemplates(loadedTemplates);
      } else {
        setTemplates(DEFAULT_TEMPLATES);
      }

      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
      }
    };

    init();
  }, []);

  // 监听状态自动保存
  useEffect(() => { ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize]);

  useEffect(() => { if (isAddingVariable && newVarInputRef.current) newVarInputRef.current.focus(); }, [isAddingVariable]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const defaultInputs: Record<string, string> = {};
    template.inputs.forEach(inp => { if (inp.defaultValue) defaultInputs[inp.id] = inp.defaultValue; });
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: defaultInputs, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects([...projects, newProject]);
    openTab(newProject.id);
  };

  const updateProjectTimestamp = (projectId: string, isModification: boolean = true) => {
    const now = Date.now();
    setProjects(prev => prev.map(p => {
        if (p.id === projectId) {
            return { ...p, lastOpenedAt: now, ...(isModification ? { lastModifiedAt: now } : {}) };
        }
        return p;
    }));
  };

  const handleInputChange = (projectId: string, inputId: string, value: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const confirmAddLocalVariable = (projectId: string) => {
    const trimmed = newVarName.trim();
    if (!trimmed) { setIsAddingVariable(false); return; }
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    if (project.customInputs?.some(i => i.label === trimmed)) { openAlert("重名警告", "该变量名称已存在。"); return; }
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: trimmed };
    setProjects(prev => prev.map(p => {
      if (p.id === projectId) {
        return { 
          ...p, 
          lastModifiedAt: Date.now(), 
          customInputs: [...(p.customInputs || []), newInput] 
        };
      }
      return p;
    }));
    setNewVarName("");
    setIsAddingVariable(false);
  };

  const handleBakeDownload = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });

    ioService.exportFile(`${project.name}_烘焙结果.txt`, fullText);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '变量1' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '内容 <0>' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
  };

  const handleDownloadBackup = () => {
    const data = { projects, templates };
    ioService.exportFile(`prompt_splicer_backup_${new Date().toISOString().split('T')[0]}.json`, JSON.stringify(data, null, 2), 'application/json');
  };

  const handleCreateTemplateFromProject = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const sourceTemplate = templates.find(t => t.id === project.templateId);
    if (!sourceTemplate) return;

    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `${project.name} (从项目提取)`,
      inputs: [
        ...sourceTemplate.inputs.map(i => ({ ...i, defaultValue: project.inputValues[i.id] || i.defaultValue })),
        ...(project.customInputs || []).map(i => ({ ...i, defaultValue: project.inputValues[i.id] }))
      ],
      steps: sourceTemplate.steps.map(s => {
        const override = project.stepOverrides[s.id];
        return {
          ...s,
          content: override?.content !== undefined ? override.content : (s.content || "")
        };
      })
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
  };

  const openTab = (id: string) => { 
    if (id === 'library') {
      setActiveTabId('library');
      return;
    }
    if (!openTabIds.includes(id)) setOpenTabIds([...openTabIds, id]); 
    setActiveTabId(id); 
    updateProjectTimestamp(id, false);
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    if (id === 'library') return;
    e?.stopPropagation();
    const newTabs = openTabIds.filter(tid => tid !== id);
    setOpenTabIds(newTabs);
    if (activeTabId === id) {
      if (newTabs.length > 0) setActiveTabId(newTabs[newTabs.length - 1]);
      else setActiveTabId('library');
    }
  };

  const sortedProjects = [...projects].sort((a, b) => (b.lastOpenedAt || 0) - (a.lastOpenedAt || 0));
  const activeProject = activeTabId !== 'library' ? projects.find(p => p.id === activeTabId) : null;
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      <div className="flex items-center bg-slate-900 h-14 border-b border-slate-800 shrink-0 pr-4 z-30 relative shadow-sm overflow-hidden">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className={`w-14 h-full flex items-center justify-center text-slate-400 hover:text-white border-r border-slate-800 hover:bg-slate-800 transition-colors shrink-0 ${isSidebarOpen ? 'bg-slate-800 text-white' : ''}`}>
             <MenuIcon className="w-5 h-5" />
           </button>
           <div className="px-5 font-bold text-slate-400 text-sm hidden sm:flex items-center gap-3 shrink-0">
              <span className="tracking-tight">提示词拼接器 Pro</span>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1.5 text-slate-600 hover:text-blue-400 transition-colors" title="应用设置"><SettingsIcon className="w-4 h-4" /></button>
           </div>
           <div className="flex-1 flex overflow-x-auto overflow-y-hidden no-scrollbar items-end h-full px-3 gap-0.5">
             {/* 永久的库标签 */}
             <div onClick={() => openTab('library')} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[100px] max-w-[150px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === 'library' ? 'bg-slate-950 border-slate-800 text-white z-10 border-b-slate-950' : 'bg-slate-900 border-transparent text-slate-500 border-b-slate-800'}`} style={{ marginBottom: '-1px' }}>
                <LibraryIcon className={`w-3.5 h-3.5 ${activeTabId === 'library' ? 'text-blue-400' : 'text-slate-600'}`} />
                <span className="truncate flex-1 font-bold">文件库</span>
             </div>

             {openTabIds.map(id => {
               const p = projects.find(proj => proj.id === id);
               if (!p) return null;
               const isActive = activeTabId === id;
               return (
                 <div key={id} onClick={() => openTab(id)} onDoubleClick={(e) => closeTab(id, e)} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[120px] max-w-[200px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${isActive ? 'bg-slate-950 border-slate-800 text-white z-10 border-b-slate-950' : 'bg-slate-900 border-transparent text-slate-500 border-b-slate-800'}`} style={{ marginBottom: '-1px' }} title="双击可关闭标签页">
                   <span className="truncate flex-1">{p.name}</span>
                   <button onClick={(e) => closeTab(id, e)} className="p-1 rounded-full hover:bg-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><CloseIcon className="w-3 h-3" /></button>
                 </div>
               );
             })}
           </div>
      </div>

      <div className="flex-1 flex overflow-hidden relative">
        <div ref={sidebarRef} style={{ width: isSidebarOpen ? sidebarWidth : 0 }} className={`bg-slate-900 flex flex-shrink-0 z-20 transition-all duration-75 relative border-r border-slate-800 ${!isSidebarOpen && 'opacity-0 overflow-hidden'}`}>
          <div className="w-12 bg-slate-950 flex flex-col items-center py-6 border-r border-slate-800 gap-6 shrink-0">
             {activeProject && (
               <>
                 <button onClick={() => setActiveSidebarTab('vars')} title="变量配置" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'vars' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/30' : 'text-slate-600 hover:text-slate-300'}`}><VarsIcon className="w-5 h-5" /></button>
                 <button onClick={() => setActiveSidebarTab('nav')} title="步骤导航" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'nav' ? 'bg-amber-600 text-white shadow-lg shadow-amber-600/30' : 'text-slate-600 hover:text-slate-300'}`}><NavIcon className="w-5 h-5" /></button>
                 <button onClick={() => setActiveSidebarTab('build')} title="导出烘焙" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'build' ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/30' : 'text-slate-600 hover:text-slate-300'}`}><BuildIcon className="w-5 h-5" /></button>
               </>
             )}
          </div>
          <div className="flex-1 flex flex-col bg-slate-900 overflow-hidden relative">
             <div className="flex-1 overflow-hidden flex flex-col">
                {activeProject && activeProjectTemplate ? (
                <>
                    {activeSidebarTab === 'vars' && (
                    <div className="flex flex-col h-full overflow-y-auto p-4 space-y-6">
                        <div className="space-y-3">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, global: !s.global}))}>
                                <span className="text-xs font-bold text-slate-500 uppercase tracking-wider group-hover:text-slate-300 transition-colors">全局变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-slate-600 transition-transform ${sidebarSections.global ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.global && activeProjectTemplate.inputs.map((input, idx) => (
                            <div key={input.id}>
                                <div className="flex items-center gap-2 mb-1.5">
                                    <span className="text-[11px] font-mono text-blue-400 font-bold">&lt;{idx}&gt;</span>
                                    <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                </div>
                                <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                            </div>
                            ))}
                        </div>
                        <div className="space-y-3 border-t border-slate-800 pt-4">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, local: !s.local}))}>
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-wider group-hover:text-emerald-400 transition-colors">本地变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-emerald-600/50 transition-transform ${sidebarSections.local ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.local && (
                            <>
                                {(activeProject.customInputs || []).map((input, idx) => (
                                <div key={input.id} className="group relative">
                                    <div className="flex items-center gap-2 mb-1.5">
                                        <span className="text-[11px] font-mono text-emerald-400 font-bold">&lt;l{idx+1}&gt;</span>
                                        <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                    </div>
                                    <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                                    <button onClick={() => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), customInputs: (p.customInputs || []).filter(i => i.id !== input.id) } : p))} className="absolute top-0 right-0 text-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1">×</button>
                                </div>
                                ))}
                                {isAddingVariable ? (
                                <div className="bg-slate-950 border border-emerald-900/50 rounded-lg p-3 animate-in slide-in-from-top-1 duration-150">
                                    <input ref={newVarInputRef} type="text" className="w-full bg-slate-900 border border-slate-700 rounded-md px-3 py-2 text-sm text-white focus:border-emerald-500 outline-none" placeholder="输入变量名称..." value={newVarName} onChange={(e) => setNewVarName(e.target.value)} onKeyDown={(e) => { if(e.key === 'Enter') confirmAddLocalVariable(activeProject.id); if(e.key === 'Escape') setIsAddingVariable(false); }} />
                                    <div className="flex justify-end gap-2 mt-3">
                                    <button onClick={() => setIsAddingVariable(false)} className="text-xs text-slate-500 px-2 py-1 hover:text-white">取消</button>
                                    <button onClick={() => confirmAddLocalVariable(activeProject.id)} className="text-xs bg-emerald-600 hover:bg-emerald-500 text-white px-3 py-1 rounded-md transition-colors">添加</button>
                                    </div>
                                </div>
                                ) : (
                                <button onClick={() => setIsAddingVariable(true)} className="w-full py-2 border-2 border-dashed border-slate-700 rounded-lg text-xs text-slate-500 hover:border-emerald-500/50 hover:text-emerald-500 hover:bg-emerald-500/5 transition-all">+ 新增本地变量</button>
                                )}
                            </>
                            )}
                        </div>
                    </div>
                    )}
                    {activeSidebarTab === 'nav' && (
                        <div className="h-full overflow-y-auto p-3 space-y-2">
                            {activeProjectTemplate.steps.map((step, idx) => (
                                <button key={step.id} onClick={() => {
                                    const el = document.getElementById(step.id);
                                    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                }} className="w-full flex items-center gap-4 p-3 hover:bg-slate-800 rounded-lg text-left transition-all group active:scale-[0.98]">
                                    <span className="w-6 h-6 flex items-center justify-center shrink-0 bg-slate-800 border border-slate-700 text-xs font-bold text-slate-500 group-hover:border-amber-500 group-hover:text-amber-500 rounded-md transition-all">{idx+1}</span>
                                    <span className="text-sm text-slate-300 truncate font-medium">{step.name}</span>
                                </button>
                            ))}
                        </div>
                    )}
                    {activeSidebarTab === 'build' && (
                        <div className="p-6 flex flex-col items-center justify-center text-center h-full">
                            <div className="w-16 h-16 bg-purple-900/30 text-purple-400 rounded-2xl flex items-center justify-center mb-4 shadow-xl shadow-purple-950/20"><DownloadIcon className="w-8 h-8" /></div>
                            <h4 className="text-sm font-bold text-white mb-2">提示词全量烘焙</h4>
                            <p className="text-xs text-slate-500 mb-6 px-4 leading-relaxed">将当前项目的所有步骤一键导出为格式化纯文本，方便直接粘贴使用。</p>
                            <Button variant="primary" size="md" onClick={() => handleBakeDownload(activeProject.id)} className="w-full bg-purple-600 hover:bg-purple-500 shadow-lg shadow-purple-600/30">导出 .txt 烘焙文件</Button>
                        </div>
                    )}
                </>
                ) : (
                  <div className="p-6 text-center text-slate-600 text-xs">
                     请先选择一个项目以查看变量与导航
                  </div>
                )}
             </div>
          </div>
          {isSidebarOpen && <div className="absolute right-0 top-0 bottom-0 w-1.5 bg-transparent hover:bg-blue-500 cursor-col-resize z-40 transition-colors" onMouseDown={() => setIsResizingSidebar(true)} />}
        </div>

        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {editingTemplateId && (
              <div className="absolute inset-0 bg-slate-950 z-50 p-8 overflow-hidden animate-in zoom-in-95 duration-200">
                <TemplateEditor template={templates.find(t => t.id === editingTemplateId)!} onSave={(updated) => { setTemplates(prev => prev.map(t => t.id === updated.id ? updated : t)); setEditingTemplateId(null); }} onCancel={() => setEditingTemplateId(null)} onRequestConfirm={openConfirm} />
              </div>
           )}

           {activeTabId === 'library' ? (
             <FileLibrary projects={sortedProjects} templates={templates} onOpenProject={openTab} onCreateProject={createProject} onCreateTemplate={createTemplate} onEditTemplate={setEditingTemplateId} onDuplicateTemplate={(id) => setTemplates([...templates, { ...JSON.parse(JSON.stringify(templates.find(t => t.id === id))), id: `tmpl_${Date.now()}_copy`, name: `副本` }])} onCreateTemplateFromProject={(id) => openConfirm("提取模版", "从该项目状态提取出新的模版结构？", () => handleCreateTemplateFromProject(id))} onDeleteProject={(id) => openConfirm("删除项目", "确定要彻底删除该项目吗？数据将无法挽回。", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} onDeleteTemplate={(id) => openConfirm("删除模版", "确定要删除此模版吗？基于此模版的项目可能会出现显示异常。", () => setTemplates(templates.filter(t => t.id !== id)))} onImportData={(p, t) => { setProjects([...p]); setTemplates([...t]); }} onOpenExport={() => setIsExportModalOpen(true)} onRequestAlert={openAlert} onClose={() => { if(openTabIds.length > 0) setActiveTabId(openTabIds[0]); }} />
           ) : activeProject && activeProjectTemplate ? (
             <div className="w-full h-full flex flex-col">
                <div className="px-8 pt-6 shrink-0 flex items-center justify-between">
                    <input type="text" value={activeProject.name} onChange={(e) => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), name: e.target.value } : p))} className="text-2xl font-black bg-transparent text-white border-none focus:ring-0 w-full p-0 tracking-tight" />
                </div>
                <div className="flex-1 overflow-hidden">
                    <ProjectRunner project={activeProject} template={activeProjectTemplate} onUpdateProject={(id, u) => { setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p)); }} onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} onRequestConfirm={openConfirm} rightPanelWidth={rightPanelWidth} onRightPanelWidthChange={setRightPanelWidth} isRightPanelOpen={isRightPanelOpen} onRightPanelOpenChange={setIsRightPanelOpen} fontSizeClass={fontSize} />
                </div>
             </div>
           ) : (
             <div className="w-full h-full flex items-center justify-center flex-col text-slate-700">
               <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center mb-4 text-slate-800"><ProjectEmptyIcon className="w-10 h-10" /></div>
               <p className="text-sm font-medium">当前未打开任何项目</p>
               <Button variant="ghost" onClick={() => setActiveTabId('library')} className="mt-4 text-slate-400 hover:text-blue-400" size="md">前往文件库</Button>
             </div>
           )}
        </div>
      </div>
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={handleDownloadBackup} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { Button } from './components/Button';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { ioService, STORAGE_KEYS } from './services/ioService';
import { 
  MenuIcon, 
  SettingsIcon, 
  CloseIcon, 
  VarsIcon, 
  NavIcon, 
  BuildIcon, 
  ChevronDownIcon, 
  DownloadIcon, 
  ProjectEmptyIcon,
  ProjectEmptyIcon as LibraryIcon
} from './components/Icons';

type SidebarTab = 'vars' | 'nav' | 'build';
type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const AutoResizeSidebarTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = `${Math.max(32, el.scrollHeight)}px`;
    }
  };
  useLayoutEffect(() => {
    const timeout = setTimeout(adjustHeight, 0);
    return () => clearTimeout(timeout);
  }, [value]);
  return (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={`block w-full resize-none overflow-hidden bg-slate-950 border border-slate-700 rounded px-2 py-1.5 text-slate-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all ${className}`}
      rows={1}
      spellCheck={false}
    />
  );
};

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>('library');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(16);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const sidebarRef = useRef<HTMLDivElement>(null);
  const [activeSidebarTab, setActiveSidebarTab] = useState<SidebarTab>('vars');

  const [sidebarSections, setSidebarSections] = useState({ global: true, local: true });
  const [isAddingVariable, setIsAddingVariable] = useState(false);
  const [newVarName, setNewVarName] = useState("");
  const newVarInputRef = useRef<HTMLInputElement>(null);

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化加载
  useEffect(() => {
    const init = async () => {
      const loadedProjects = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (loadedProjects) {
        setProjects(loadedProjects.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      }

      const loadedTemplates = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      if (loadedTemplates) {
        setTemplates(loadedTemplates);
      } else {
        setTemplates(DEFAULT_TEMPLATES);
      }

      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
      }
    };

    init();
  }, []);

  // 监听状态自动保存
  useEffect(() => { ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize]);

  useEffect(() => { if (isAddingVariable && newVarInputRef.current) newVarInputRef.current.focus(); }, [isAddingVariable]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const defaultInputs: Record<string, string> = {};
    template.inputs.forEach(inp => { if (inp.defaultValue) defaultInputs[inp.id] = inp.defaultValue; });
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: defaultInputs, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects([...projects, newProject]);
    openTab(newProject.id);
  };

  const updateProjectTimestamp = (projectId: string, isModification: boolean = true) => {
    const now = Date.now();
    setProjects(prev => prev.map(p => {
        if (p.id === projectId) {
            return { ...p, lastOpenedAt: now, ...(isModification ? { lastModifiedAt: now } : {}) };
        }
        return p;
    }));
  };

  const handleInputChange = (projectId: string, inputId: string, value: string) => {
    setProjects(prev => prev.map(p => p.id === projectId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const confirmAddLocalVariable = (projectId: string) => {
    const trimmed = newVarName.trim();
    if (!trimmed) { setIsAddingVariable(false); return; }
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    if (project.customInputs?.some(i => i.label === trimmed)) { openAlert("重名警告", "该变量名称已存在。"); return; }
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: trimmed };
    setProjects(prev => prev.map(p => {
      if (p.id === projectId) {
        return { 
          ...p, 
          lastModifiedAt: Date.now(), 
          customInputs: [...(p.customInputs || []), newInput] 
        };
      }
      return p;
    }));
    setNewVarName("");
    setIsAddingVariable(false);
  };

  const handleBakeDownload = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });

    ioService.exportFile(`${project.name}_烘焙结果.txt`, fullText);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '变量1' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '内容 <0>' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
  };

  const handleDownloadBackup = () => {
    const data = { projects, templates };
    ioService.exportFile(`prompt_splicer_backup_${new Date().toISOString().split('T')[0]}.json`, JSON.stringify(data, null, 2), 'application/json');
  };

  const handleCreateTemplateFromProject = (projectId: string) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;
    const sourceTemplate = templates.find(t => t.id === project.templateId);
    if (!sourceTemplate) return;

    const now = Date.now();
    const newTemplate: Template = {
      id: `tmpl_${now}`,
      name: `${project.name} (从项目提取)`,
      inputs: [
        ...sourceTemplate.inputs.map(i => ({ ...i, defaultValue: project.inputValues[i.id] || i.defaultValue })),
        ...(project.customInputs || []).map(i => ({ ...i, defaultValue: project.inputValues[i.id] }))
      ],
      steps: sourceTemplate.steps.map(s => {
        const override = project.stepOverrides[s.id];
        return {
          ...s,
          content: override?.content !== undefined ? override.content : (s.content || "")
        };
      })
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newTemplate.id);
  };

  const openTab = (id: string) => { 
    if (id === 'library') {
      setActiveTabId('library');
      return;
    }
    if (!openTabIds.includes(id)) setOpenTabIds([...openTabIds, id]); 
    setActiveTabId(id); 
    updateProjectTimestamp(id, false);
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    if (id === 'library') return;
    e?.stopPropagation();
    const newTabs = openTabIds.filter(tid => tid !== id);
    setOpenTabIds(newTabs);
    if (activeTabId === id) {
      if (newTabs.length > 0) setActiveTabId(newTabs[newTabs.length - 1]);
      else setActiveTabId('library');
    }
  };

  const handleDeleteProjects = (ids: string[]) => {
    setProjects(prev => prev.filter(p => !ids.includes(p.id)));
    setOpenTabIds(prev => {
        const nextTabs = prev.filter(id => !ids.includes(id));
        if (activeTabId && ids.includes(activeTabId)) {
            if (nextTabs.length > 0) setActiveTabId(nextTabs[nextTabs.length - 1]);
            else setActiveTabId('library');
        }
        return nextTabs;
    });
  };

  const sortedProjects = [...projects].sort((a, b) => (b.lastOpenedAt || 0) - (a.lastOpenedAt || 0));
  const activeProject = activeTabId !== 'library' ? projects.find(p => p.id === activeTabId) : null;
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      <div className="flex items-center bg-slate-900 h-14 border-b border-slate-800 shrink-0 pr-4 z-30 relative shadow-sm overflow-hidden">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className={`w-14 h-full flex items-center justify-center text-slate-400 hover:text-white border-r border-slate-800 hover:bg-slate-800 transition-colors shrink-0 ${isSidebarOpen ? 'bg-slate-800 text-white' : ''}`}>
             <MenuIcon className="w-5 h-5" />
           </button>
           <div className="px-5 font-bold text-slate-400 text-sm hidden sm:flex items-center gap-3 shrink-0">
              <span className="tracking-tight">提示词拼接器 Pro</span>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1.5 text-slate-600 hover:text-blue-400 transition-colors" title="应用设置"><SettingsIcon className="w-4 h-4" /></button>
           </div>
           <div className="flex-1 flex overflow-x-auto overflow-y-hidden no-scrollbar items-end h-full px-3 gap-0.5">
             <div onClick={() => openTab('library')} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[100px] max-w-[150px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === 'library' ? 'bg-slate-950 border-slate-800 text-white z-10 border-b-slate-950' : 'bg-slate-900 border-transparent text-slate-500 border-b-slate-800'}`} style={{ marginBottom: '-1px' }}>
                <LibraryIcon className={`w-3.5 h-3.5 ${activeTabId === 'library' ? 'text-blue-400' : 'text-slate-600'}`} />
                <span className="truncate flex-1 font-bold">文件库</span>
             </div>

             {openTabIds.map(id => {
               const p = projects.find(proj => proj.id === id);
               if (!p) return null;
               const isActive = activeTabId === id;
               return (
                 <div key={id} onClick={() => openTab(id)} onDoubleClick={(e) => closeTab(id, e)} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[120px] max-w-[200px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${isActive ? 'bg-slate-950 border-slate-800 text-white z-10 border-b-slate-950' : 'bg-slate-900 border-transparent text-slate-500 border-b-slate-800'}`} style={{ marginBottom: '-1px' }} title="双击可关闭标签页">
                   <span className="truncate flex-1">{p.name}</span>
                   <button onClick={(e) => closeTab(id, e)} className="p-1 rounded-full hover:bg-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><CloseIcon className="w-3 h-3" /></button>
                 </div>
               );
             })}
           </div>
      </div>

      <div className="flex-1 flex overflow-hidden relative">
        <div ref={sidebarRef} style={{ width: isSidebarOpen ? sidebarWidth : 0 }} className={`bg-slate-900 flex flex-shrink-0 z-20 transition-all duration-75 relative border-r border-slate-800 ${!isSidebarOpen && 'opacity-0 overflow-hidden'}`}>
          <div className="w-12 bg-slate-950 flex flex-col items-center py-6 border-r border-slate-800 gap-6 shrink-0">
             {activeProject && (
               <>
                 <button onClick={() => setActiveSidebarTab('vars')} title="变量配置" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'vars' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/30' : 'text-slate-600 hover:text-slate-300'}`}><VarsIcon className="w-5 h-5" /></button>
                 <button onClick={() => setActiveSidebarTab('nav')} title="步骤导航" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'nav' ? 'bg-amber-600 text-white shadow-lg shadow-amber-600/30' : 'text-slate-600 hover:text-slate-300'}`}><NavIcon className="w-5 h-5" /></button>
                 <button onClick={() => setActiveSidebarTab('build')} title="导出烘焙" className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'build' ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/30' : 'text-slate-600 hover:text-slate-300'}`}><BuildIcon className="w-5 h-5" /></button>
               </>
             )}
          </div>
          <div className="flex-1 flex-col bg-slate-900 overflow-hidden relative flex">
             <div className="flex-1 overflow-hidden flex flex-col">
                {activeProject && activeProjectTemplate ? (
                <>
                    {activeSidebarTab === 'vars' && (
                    <div className="flex flex-col h-full overflow-y-auto p-4 space-y-6">
                        <div className="space-y-3">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, global: !s.global}))}>
                                <span className="text-xs font-bold text-slate-500 uppercase tracking-wider group-hover:text-slate-300 transition-colors">全局变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-slate-600 transition-transform ${sidebarSections.global ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.global && activeProjectTemplate.inputs.map((input, idx) => (
                            <div key={input.id}>
                                <div className="flex items-center gap-2 mb-1.5">
                                    <span className="text-[11px] font-mono text-blue-400 font-bold">&lt;{idx}&gt;</span>
                                    <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                </div>
                                <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                            </div>
                            ))}
                        </div>
                        <div className="space-y-3 border-t border-slate-800 pt-4">
                            <div className="flex items-center justify-between cursor-pointer group" onClick={() => setSidebarSections(s => ({...s, local: !s.local}))}>
                                <span className="text-xs font-bold text-emerald-600 uppercase tracking-wider group-hover:text-emerald-400 transition-colors">本地变量</span>
                                <ChevronDownIcon className={`w-4 h-4 text-emerald-600/50 transition-transform ${sidebarSections.local ? 'rotate-180' : ''}`} />
                            </div>
                            {sidebarSections.local && (
                            <>
                                {(activeProject.customInputs || []).map((input, idx) => (
                                <div key={input.id} className="group relative">
                                    <div className="flex items-center gap-2 mb-1.5">
                                        <span className="text-[11px] font-mono text-emerald-400 font-bold">&lt;l{idx+1}&gt;</span>
                                        <label className="text-[11px] text-slate-500 block truncate font-medium">{input.label}</label>
                                    </div>
                                    <AutoResizeSidebarTextarea value={activeProject.inputValues[input.id] || ''} onChange={(val) => handleInputChange(activeProject.id, input.id, val)} placeholder="..." />
                                    <button onClick={() => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), customInputs: (p.customInputs || []).filter(i => i.id !== input.id) } : p))} className="absolute top-0 right-0 text-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1">×</button>
                                </div>
                                ))}
                                {isAddingVariable ? (
                                <div className="bg-slate-950 border border-emerald-900/50 rounded-lg p-3 animate-in slide-in-from-top-1 duration-150">
                                    <input ref={newVarInputRef} type="text" className="w-full bg-slate-900 border border-slate-700 rounded-md px-3 py-2 text-sm text-white focus:border-emerald-500 outline-none" placeholder="输入变量名称..." value={newVarName} onChange={(e) => setNewVarName(e.target.value)} onKeyDown={(e) => { if(e.key === 'Enter') confirmAddLocalVariable(activeProject.id); if(e.key === 'Escape') setIsAddingVariable(false); }} />
                                    <div className="flex justify-end gap-2 mt-3">
                                    <button onClick={() => setIsAddingVariable(false)} className="text-xs text-slate-500 px-2 py-1 hover:text-white">取消</button>
                                    <button onClick={() => confirmAddLocalVariable(activeProject.id)} className="text-xs bg-emerald-600 hover:bg-emerald-500 text-white px-3 py-1 rounded-md transition-colors">添加</button>
                                    </div>
                                </div>
                                ) : (
                                <button onClick={() => setIsAddingVariable(true)} className="w-full py-2 border-2 border-dashed border-slate-700 rounded-lg text-xs text-slate-500 hover:border-emerald-500/50 hover:text-emerald-500 hover:bg-emerald-500/5 transition-all">+ 新增本地变量</button>
                                )}
                            </>
                            )}
                        </div>
                    </div>
                    )}
                    {activeSidebarTab === 'nav' && (
                        <div className="h-full overflow-y-auto p-3 space-y-2">
                            {activeProjectTemplate.steps.map((step, idx) => (
                                <button key={step.id} onClick={() => {
                                    const el = document.getElementById(step.id);
                                    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                                }} className="w-full flex items-center gap-4 p-3 hover:bg-slate-800 rounded-lg text-left transition-all group active:scale-[0.98]">
                                    <span className="w-6 h-6 flex items-center justify-center shrink-0 bg-slate-800 border border-slate-700 text-xs font-bold text-slate-500 group-hover:border-amber-500 group-hover:text-amber-500 rounded-md transition-all">{idx+1}</span>
                                    <span className="text-sm text-slate-300 truncate font-medium">{step.name}</span>
                                </button>
                            ))}
                        </div>
                    )}
                    {activeSidebarTab === 'build' && (
                        <div className="p-6 flex flex-col items-center justify-center text-center h-full">
                            <div className="w-16 h-16 bg-purple-900/30 text-purple-400 rounded-2xl flex items-center justify-center mb-4 shadow-xl shadow-purple-950/20"><DownloadIcon className="w-8 h-8" /></div>
                            <h4 className="text-sm font-bold text-white mb-2">提示词全量烘焙</h4>
                            <p className="text-xs text-slate-500 mb-6 px-4 leading-relaxed">将当前项目的所有步骤一键导出为格式化纯文本，方便直接粘贴使用。</p>
                            <Button variant="primary" size="md" onClick={() => handleBakeDownload(activeProject.id)} className="w-full bg-purple-600 hover:bg-purple-500 shadow-lg shadow-purple-600/30">导出 .txt 烘焙文件</Button>
                        </div>
                    )}
                </>
                ) : (
                  <div className="p-6 text-center text-slate-600 text-xs">
                     请先选择一个项目以查看变量与导航
                  </div>
                )}
             </div>
          </div>
          {isSidebarOpen && <div className="absolute right-0 top-0 bottom-0 w-1.5 bg-transparent hover:bg-blue-500 cursor-col-resize z-40 transition-colors" onMouseDown={() => setIsResizingSidebar(true)} />}
        </div>

        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {editingTemplateId && (
              <div className="absolute inset-0 bg-slate-950 z-50 p-8 overflow-hidden animate-in zoom-in-95 duration-200">
                <TemplateEditor template={templates.find(t => t.id === editingTemplateId)!} onSave={(updated) => { setTemplates(prev => prev.map(t => t.id === updated.id ? updated : t)); setEditingTemplateId(null); }} onCancel={() => setEditingTemplateId(null)} onRequestConfirm={openConfirm} />
              </div>
           )}

           {activeTabId === 'library' ? (
             <FileLibrary 
                projects={sortedProjects} 
                templates={templates} 
                onOpenProject={openTab} 
                onCreateProject={createProject} 
                onCreateTemplate={createTemplate} 
                onEditTemplate={setEditingTemplateId} 
                onDuplicateTemplate={(id) => setTemplates([...templates, { ...JSON.parse(JSON.stringify(templates.find(t => t.id === id))), id: `tmpl_${Date.now()}_copy`, name: `副本` }])} 
                onCreateTemplateFromProject={(id) => openConfirm("提取模版", "从该项目状态提取出新的模版结构？", () => handleCreateTemplateFromProject(id))} 
                onDeleteProject={(id) => openConfirm("删除项目", "确定要彻底删除该项目吗？数据将无法挽回。", () => { handleDeleteProjects([id]); closeTab(id); })} 
                onDeleteProjects={(ids) => openConfirm("批量删除项目", `确定要彻底删除选中的 ${ids.length} 个项目吗？此操作无法撤销。`, () => { handleDeleteProjects(ids); })}
                onDeleteTemplate={(id) => openConfirm("删除模版", "确定要删除此模版吗？基于此模版的项目可能会出现显示异常。", () => setTemplates(templates.filter(t => t.id !== id)))} 
                onImportData={(p, t) => { setProjects([...p]); setTemplates([...t]); }} 
                onOpenExport={() => setIsExportModalOpen(true)} 
                onRequestAlert={openAlert} 
                onClose={() => { if(openTabIds.length > 0) setActiveTabId(openTabIds[0]); }} 
             />
           ) : activeProject && activeProjectTemplate ? (
             <div className="w-full h-full flex flex-col">
                <div className="px-8 pt-6 shrink-0 flex items-center justify-between">
                    <input type="text" value={activeProject.name} onChange={(e) => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, lastModifiedAt: Date.now(), name: e.target.value } : p))} className="text-2xl font-black bg-transparent text-white border-none focus:ring-0 w-full p-0 tracking-tight" />
                </div>
                <div className="flex-1 overflow-hidden">
                    <ProjectRunner project={activeProject} template={activeProjectTemplate} onUpdateProject={(id, u) => { setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p)); }} onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} onRequestConfirm={openConfirm} rightPanelWidth={rightPanelWidth} onRightPanelWidthChange={setRightPanelWidth} isRightPanelOpen={isRightPanelOpen} onRightPanelOpenChange={setIsRightPanelOpen} fontSizeClass={fontSize} />
                </div>
             </div>
           ) : (
             <div className="w-full h-full flex items-center justify-center flex-col text-slate-700">
               <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center mb-4 text-slate-800"><ProjectEmptyIcon className="w-10 h-10" /></div>
               <p className="text-sm font-medium">当前未打开任何项目</p>
               <Button variant="ghost" onClick={() => setActiveTabId('library')} className="mt-4 text-slate-400 hover:text-blue-400" size="md">前往文件库</Button>
             </div>
           )}
        </div>
      </div>
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={handleDownloadBackup} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { CreateProjectModal } from './CreateProjectModal';
import { HighlightEffect } from './HighlightEffect';
import { ioService } from '../services/ioService';

interface FileLibraryProps {
  projects: Project[];
  templates: Template[];
  onOpenProject: (projectId: string) => void;
  onCreateProject: (templateId: string, name: string) => void;
  onCreateTemplate: () => void;
  onEditTemplate: (templateId: string) => void;
  onDuplicateTemplate: (templateId: string) => void;
  onCreateTemplateFromProject: (projectId: string) => void;
  onDeleteProject: (id: string) => void;
  onDeleteProjects: (ids: string[]) => void;
  onDeleteTemplate: (id: string) => void;
  onClose: () => void;
  onImportData: (projects: Project[], templates: Template[]) => void;
  onOpenExport: () => void;
  onRequestAlert: (title: string, message: string) => void;
}

const formatFullDate = (ts: number) => {
    const d = new Date(ts);
    return `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')} ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}:${d.getSeconds().toString().padStart(2,'0')}`;
};

type SortKey = 'lastModified' | 'createdAt' | 'name';

export const FileLibrary: React.FC<FileLibraryProps> = ({
  projects,
  templates,
  onOpenProject,
  onCreateProject,
  onCreateTemplate,
  onEditTemplate,
  onDuplicateTemplate,
  onCreateTemplateFromProject,
  onDeleteProject,
  onDeleteProjects,
  onDeleteTemplate,
  onClose,
  onImportData,
  onOpenExport,
  onRequestAlert
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [sortBy, setSortBy] = useState<SortKey>('lastModified');
  const [cardScale, setCardScale] = useState<number>(300);
  const [isGrouped, setIsGrouped] = useState<boolean>(false);
  const [createModalInfo, setCreateModalInfo] = useState<{ isOpen: boolean; templateId: string | null }>({
    isOpen: false,
    templateId: null
  });
  const [lastCreatedId, setLastCreatedId] = useState<string | null>(null);

  // 批量模式状态
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const sortProjects = (projs: Project[]) => {
    return [...projs].sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'createdAt') return (b.createdAt || 0) - (a.createdAt || 0);
      return (b.lastModifiedAt || 0) - (a.lastModifiedAt || 0);
    });
  };

  useEffect(() => {
    if (projects.length > 0) {
      const latest = [...projects].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
      if (Date.now() - (latest.createdAt || 0) < 5000) {
        setLastCreatedId(latest.id);
      }
    }
  }, [projects.length]);

  const groupedData = useMemo(() => {
    const sorted = sortProjects(projects);
    if (!isGrouped) return { 'all': sorted };
    const groups: Record<string, Project[]> = {};
    sorted.forEach(p => {
      const template = templates.find(t => t.id === p.templateId);
      const groupName = template?.name || '未分类项目';
      if (!groups[groupName]) groups[groupName] = [];
      groups[groupName].push(p);
    });
    return groups;
  }, [projects, sortBy, isGrouped, templates]);

  const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const content = await ioService.readFileAsText(file);
      const data = JSON.parse(content);
      if (data && Array.isArray(data.projects) && Array.isArray(data.templates)) {
        onImportData(data.projects, data.templates);
      } else {
        onRequestAlert('失败', '文件格式不匹配。');
      }
    } catch (err) {
      onRequestAlert('失败', '文件读取或解析 JSON 失败。');
    }
    e.target.value = '';
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const selectAll = () => {
    if (selectedIds.size === projects.length) setSelectedIds(new Set());
    else setSelectedIds(new Set(projects.map(p => p.id)));
  };

  const handleBatchDelete = () => {
    if (selectedIds.size === 0) return;
    onDeleteProjects(Array.from(selectedIds));
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const renderProjectCard = (p: Project) => {
    const template = templates.find(t => t.id === p.templateId);
    const isSelected = selectedIds.has(p.id);

    return (
      <HighlightEffect key={p.id} isActive={lastCreatedId === p.id}>
        <div 
          onClick={() => isSelectionMode ? toggleSelection(p.id) : onOpenProject(p.id)} 
          className={`group bg-slate-900 hover:bg-slate-800 border transition-all relative rounded-xl p-4 cursor-pointer ${
            isSelected ? 'border-blue-500 ring-2 ring-blue-500/20 bg-slate-800' : 'border-slate-800 hover:border-blue-500/50'
          }`}
        >
          {isSelectionMode && (
            <div className={`absolute top-3 left-3 w-5 h-5 rounded border flex items-center justify-center transition-colors z-20 ${
              isSelected ? 'bg-blue-600 border-blue-500' : 'bg-slate-950 border-slate-700'
            }`}>
              {isSelected && (
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5 text-white">
                  <path fillRule="evenodd" d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" clipRule="evenodd" />
                </svg>
              )}
            </div>
          )}

          <div className={`${isSelectionMode ? 'pl-7' : ''} mb-2`}>
              <h4 className="text-base font-bold text-slate-200 group-hover:text-white mb-1 truncate">{p.name}</h4>
              <div className="flex items-center gap-2">
                <span className="text-[10px] bg-slate-950 text-slate-500 px-1.5 py-0.5 rounded border border-slate-800/50">
