      {/* 顶部导航 */}
      <div className="flex items-center bg-slate-900 h-14 border-b border-slate-800 shrink-0 pr-4 z-30 relative shadow-sm">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="w-14 h-full flex items-center justify-center text-slate-400 hover:text-white border-r border-slate-800 hover:bg-slate-800 transition-colors shrink-0">
             <MenuIcon className="w-5 h-5" />
