           <div className="px-5 font-bold text-slate-400 text-sm flex items-center gap-3 shrink-0">
              <span className="tracking-tight">提示词拼接器 Pro</span>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1.5 text-slate-600 hover:text-blue-400 transition-colors"><SettingsIcon className="w-4 h-4" /></button>
           </div>
           <div className="flex-1 flex overflow-x-auto no-scrollbar items-end h-full px-3 gap-0.5">
             <div onClick={() => openTab('library')} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[100px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === 'library' ? 'bg-slate-950 border-slate-800 text-white z-10' : 'bg-slate-900 border-transparent text-slate-500'}`}>
                <LibraryIcon className="w-3.5 h-3.5" />
                <span className="truncate flex-1 font-bold">文件库</span>
             </div>
             {openTabIds.map(id => (
               <div key={id} onClick={() => openTab(id)} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[120px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === id ? 'bg-slate-950 border-slate-800 text-white z-10' : 'bg-slate-900 border-transparent text-slate-500'}`}>
                 <span className="truncate flex-1">{projects.find(p => p.id === id)?.name || '未命名项目'}</span>
                 <button onClick={(e) => closeTab(id, e)} className="p-1 rounded-full hover:bg-slate-700 opacity-0 group-hover:opacity-100 transition-opacity"><CloseIcon className="w-3 h-3" /></button>
               </div>
             ))}
           </div>
      </div>

      <div className="flex-1 flex overflow-hidden relative">
        {/* 侧边栏 */}
        {isSidebarOpen && (
          <div ref={sidebarRef} style={{ width: sidebarWidth }} className="bg-slate-900 flex flex-shrink-0 z-20 relative border-r border-slate-800">
             <div className="w-12 bg-slate-950 flex flex-col items-center py-6 border-r border-slate-800 gap-6 shrink-0">
               {activeProject && (
                 <>
                   <button onClick={() => setActiveSidebarTab('vars')} className={`p-2 rounded-lg ${activeSidebarTab === 'vars' ? 'bg-blue-600 text-white' : 'text-slate-600'}`}><VarsIcon className="w-5 h-5" /></button>
                   <button onClick={() => setActiveSidebarTab('nav')} className={`p-2 rounded-lg ${activeSidebarTab === 'nav' ? 'bg-amber-600 text-white' : 'text-slate-600'}`}><NavIcon className="w-5 h-5" /></button>
                   <button onClick={() => setActiveSidebarTab('build')} className={`p-2 rounded-lg ${activeSidebarTab === 'build' ? 'bg-purple-600 text-white' : 'text-slate-600'}`}><BuildIcon className="w-5 h-5" /></button>
                 </>
               )}
             </div>
             <div className="flex-1 overflow-y-auto p-4">
                {activeProject && activeProjectTemplate ? (
                  <div className="space-y-4">
                     {activeSidebarTab === 'vars' && activeProjectTemplate.inputs.map(input => (
                       <div key={input.id}>
                         <label className="text-[10px] text-slate-500 mb-1 block uppercase font-bold">{input.label}</label>
                         <AutoResizeSidebarTextarea 
                           value={activeProject.inputValues[input.id] || ''} 
                           onChange={(v) => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, inputValues: { ...p.inputValues, [input.id]: v } } : p))} 
                         />
                       </div>
                     ))}
                  </div>
                ) : <div className="text-center text-slate-600 text-[10px] mt-10">未选中任何项目</div>}
             </div>
          </div>
        )}

        {/* 主内容区域 */}
        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {activeTabId === 'library' ? (
             <FileLibrary 
                projects={sortedProjects} 
                templates={templates} 
                onOpenProject={openTab} 
                onCreateProject={createProject} 
                onCreateTemplate={createTemplate} 
                onEditTemplate={setEditingTemplateId} 
                onDuplicateTemplate={(id) => { const t = templates.find(x => x.id === id); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: t.name+' (副本)'}]); setEditingTemplateId(nid); } }} 
                onCreateTemplateFromProject={(id) => { const p = projects.find(x => x.id === id); const t = templates.find(x => x.id === p?.templateId); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: p?.name+' 提取'}]); setEditingTemplateId(nid); } }} 
                onDeleteProject={(id) => openConfirm("删除项目", "确定删除？", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} 
                onDeleteProjects={(ids) => openConfirm("批量删除", "确定删除？", () => { setProjects(projects.filter(p => !ids.includes(p.id))); ids.forEach(id => closeTab(id)); })}
                onDeleteTemplate={(id) => openConfirm("删除模版", "确定删除？", () => setTemplates(templates.filter(t => t.id !== id)))} 
                onImportData={(p, t) => { setProjects(p); setTemplates(t); }} 
                onOpenExport={() => setIsExportModalOpen(true)} 
                onRequestAlert={openAlert} 
                onClose={() => { if(openTabIds.length > 0) setActiveTabId(openTabIds[0]); }} 
             />
           ) : activeProject && activeProjectTemplate ? (
             <ProjectRunner 
                project={activeProject} 
                template={activeProjectTemplate} 
                onUpdateProject={(id, u) => setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p))} 
                onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} 
                onRequestConfirm={openConfirm} 
                rightPanelWidth={rightPanelWidth} 
                onRightPanelWidthChange={setRightPanelWidth} 
                isRightPanelOpen={isRightPanelOpen} 
                onRightPanelOpenChange={setIsRightPanelOpen} 
             />
           ) : <div className="flex items-center justify-center h-full text-slate-700">请从文件库打开项目</div>}
        </div>
      </div>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={() => {}} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

