import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { Button } from './components/Button';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { ioService, STORAGE_KEYS } from './services/ioService';
import { 
  MenuIcon, 
  SettingsIcon, 
  CloseIcon, 
  VarsIcon, 
  NavIcon, 
  BuildIcon, 
  ChevronDownIcon, 
  DownloadIcon, 
  ProjectEmptyIcon,
  ProjectEmptyIcon as LibraryIcon
} from './components/Icons';

type SidebarTab = 'vars' | 'nav' | 'build';
type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const AutoResizeSidebarTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = `${Math.max(32, el.scrollHeight)}px`;
    }
  };
  useLayoutEffect(() => {
    const timeout = setTimeout(adjustHeight, 0);
    return () => clearTimeout(timeout);
  }, [value]);
  return (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={`block w-full resize-none overflow-hidden bg-slate-950 border border-slate-700 rounded px-2 py-1.5 text-slate-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all ${className}`}
      rows={1}
      spellCheck={false}
    />
  );
};

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>('library');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(16);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const sidebarRef = useRef<HTMLDivElement>(null);
  const [activeSidebarTab, setActiveSidebarTab] = useState<SidebarTab>('vars');

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化
  useEffect(() => {
    const init = async () => {
      const lp = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (lp) setProjects(lp.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      const lt = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      setTemplates(lt || DEFAULT_TEMPLATES);
      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
      }
    };
    init();
  }, []);

  // 持久化
  useEffect(() => { if(templates.length > 0) ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { if(projects.length > 0) ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: {}, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects(prev => [...prev, newProject]);
    openTab(newProject.id);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newId = `tmpl_${now}`;
    const newTemplate: Template = {
      id: newId,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '核心变量' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '在此处输入模板内容...' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newId);
  };

  const openTab = (id: string) => { 
    if (id === 'library') { setActiveTabId('library'); return; }
    setOpenTabIds(prev => prev.includes(id) ? prev : [...prev, id]); 
    setActiveTabId(id); 
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setOpenTabIds(prev => {
        const next = prev.filter(tid => tid !== id);
        if (activeTabId === id) setActiveTabId(next.length > 0 ? next[next.length - 1] : 'library');
        return next;
    });
  };

  const editingTemplate = templates.find(t => t.id === editingTemplateId);
  const activeProject = activeTabId !== 'library' ? projects.find(p => p.id === activeTabId) : null;
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      {/* 全屏模板编辑器覆盖层 */}
      {editingTemplateId && editingTemplate && (
        <div className="fixed inset-0 bg-slate-950 z-[100] animate-in fade-in zoom-in-95 duration-200">
           <TemplateEditor 
              template={editingTemplate} 
              onSave={(u) => { setTemplates(prev => prev.map(t => t.id === u.id ? u : t)); setEditingTemplateId(null); }} 
              onCancel={() => setEditingTemplateId(null)} 
              onRequestConfirm={openConfirm} 
           />
        </div>
      )}

      {/* 顶部导航 */}
      <div className="flex items-center bg-slate-900 h-14 border-b border-slate-800 shrink-0 pr-4 z-30 relative shadow-sm">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="w-14 h-full flex items-center justify-center text-slate-400 hover:text-white border-r border-slate-800 hover:bg-slate-800 transition-colors shrink-0">
             <MenuIcon className="w-5 h-5" />
           </button>
           <div className="px-5 font-bold text-slate-400 text-sm flex items-center gap-3 shrink-0">
              <span className="tracking-tight">提示词拼接器 Pro</span>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1.5 text-slate-600 hover:text-blue-400 transition-colors"><SettingsIcon className="w-4 h-4" /></button>
           </div>
           <div className="flex-1 flex overflow-x-auto no-scrollbar items-end h-full px-3 gap-0.5">
             <div onClick={() => openTab('library')} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[100px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === 'library' ? 'bg-slate-950 border-slate-800 text-white z-10' : 'bg-slate-900 border-transparent text-slate-500'}`}>
                <LibraryIcon className="w-3.5 h-3.5" />
                <span className="truncate flex-1 font-bold">文件库</span>
             </div>
             {openTabIds.map(id => (
               <div key={id} onClick={() => openTab(id)} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[120px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === id ? 'bg-slate-950 border-slate-800 text-white z-10' : 'bg-slate-900 border-transparent text-slate-500'}`}>
                 <span className="truncate flex-1">{projects.find(p => p.id === id)?.name || '未命名项目'}</span>
                 <button onClick={(e) => closeTab(id, e)} className="p-1 rounded-full hover:bg-slate-700 opacity-0 group-hover:opacity-100 transition-opacity"><CloseIcon className="w-3 h-3" /></button>
               </div>
             ))}
           </div>
      </div>

      <div className="flex-1 flex overflow-hidden relative">
        {/* 侧边栏 */}
        {isSidebarOpen && (
          <div ref={sidebarRef} style={{ width: sidebarWidth }} className="bg-slate-900 flex flex-shrink-0 z-20 relative border-r border-slate-800">
             <div className="w-12 bg-slate-950 flex flex-col items-center py-6 border-r border-slate-800 gap-6 shrink-0">
               {activeProject && (
                 <>
                   <button onClick={() => setActiveSidebarTab('vars')} className={`p-2 rounded-lg ${activeSidebarTab === 'vars' ? 'bg-blue-600 text-white' : 'text-slate-600'}`}><VarsIcon className="w-5 h-5" /></button>
                   <button onClick={() => setActiveSidebarTab('nav')} className={`p-2 rounded-lg ${activeSidebarTab === 'nav' ? 'bg-amber-600 text-white' : 'text-slate-600'}`}><NavIcon className="w-5 h-5" /></button>
                   <button onClick={() => setActiveSidebarTab('build')} className={`p-2 rounded-lg ${activeSidebarTab === 'build' ? 'bg-purple-600 text-white' : 'text-slate-600'}`}><BuildIcon className="w-5 h-5" /></button>
                 </>
               )}
             </div>
             <div className="flex-1 overflow-y-auto p-4">
                {activeProject && activeProjectTemplate ? (
                  <div className="space-y-4">
                     {activeSidebarTab === 'vars' && activeProjectTemplate.inputs.map(input => (
                       <div key={input.id}>
                         <label className="text-[10px] text-slate-500 mb-1 block uppercase font-bold">{input.label}</label>
                         <AutoResizeSidebarTextarea 
                           value={activeProject.inputValues[input.id] || ''} 
                           onChange={(v) => setProjects(prev => prev.map(p => p.id === activeProject.id ? { ...p, inputValues: { ...p.inputValues, [input.id]: v } } : p))} 
                         />
                       </div>
                     ))}
                  </div>
                ) : <div className="text-center text-slate-600 text-[10px] mt-10">未选中任何项目</div>}
             </div>
          </div>
        )}

        {/* 主内容区域 */}
        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {activeTabId === 'library' ? (
             <FileLibrary 
                // Fix: projects={sortedProjects} -> projects={projects}
                projects={projects} 
                templates={templates} 
                onOpenProject={openTab} 
                onCreateProject={createProject} 
                onCreateTemplate={createTemplate} 
                onEditTemplate={setEditingTemplateId} 
                onDuplicateTemplate={(id) => { const t = templates.find(x => x.id === id); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: t.name+' (副本)'}]); setEditingTemplateId(nid); } }} 
                onCreateTemplateFromProject={(id) => { const p = projects.find(x => x.id === id); const t = templates.find(x => x.id === p?.templateId); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: p?.name+' 提取'}]); setEditingTemplateId(nid); } }} 
                onDeleteProject={(id) => openConfirm("删除项目", "确定删除？", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} 
                onDeleteProjects={(ids) => openConfirm("批量删除", "确定删除？", () => { setProjects(projects.filter(p => !ids.includes(p.id))); ids.forEach(id => closeTab(id)); })}
                onDeleteTemplate={(id) => openConfirm("删除模版", "确定删除？", () => setTemplates(templates.filter(t => t.id !== id)))} 
                onImportData={(p, t) => { setProjects(p); setTemplates(t); }} 
                onOpenExport={() => setIsExportModalOpen(true)} 
                onRequestAlert={openAlert} 
                onClose={() => { if(openTabIds.length > 0) setActiveTabId(openTabIds[0]); }} 
             />
           ) : activeProject && activeProjectTemplate ? (
             <ProjectRunner 
                project={activeProject} 
                template={activeProjectTemplate} 
                onUpdateProject={(id, u) => setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p))} 
                onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} 
                onRequestConfirm={openConfirm} 
                rightPanelWidth={rightPanelWidth} 
                onRightPanelWidthChange={setRightPanelWidth} 
                isRightPanelOpen={isRightPanelOpen} 
                onRightPanelOpenChange={setIsRightPanelOpen} 
             />
           ) : <div className="flex items-center justify-center h-full text-slate-700">请从文件库打开项目</div>}
        </div>
      </div>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={() => {}} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useLayoutEffect } from 'react';
import { Project, Template, TemplateInput } from '../types';
import { 
  VarsIcon, 
  NavIcon, 
  BuildIcon, 
  ChevronDownIcon, 
  DownloadIcon 
} from './Icons';
import { Button } from './Button';

type SidebarTab = 'vars' | 'nav' | 'build';

interface SidebarProps {
  isOpen: boolean;
  width: number;
  onWidthChange: (width: number) => void;
  isResizing: boolean;
  onResizingChange: (resizing: boolean) => void;
  activeProject: Project | null;
  activeProjectTemplate: Template | null;
  onInputChange: (inputId: string, value: string) => void;
  onAddLocalVariable: (name: string) => void;
  onDeleteLocalVariable: (varId: string) => void;
  onBakeDownload: () => void;
  onRequestAlert: (title: string, message: string) => void;
}

const AutoResizeSidebarTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = `${Math.max(32, el.scrollHeight)}px`;
    }
  };
  useLayoutEffect(() => {
    const timeout = setTimeout(adjustHeight, 0);
    return () => clearTimeout(timeout);
  }, [value]);
  return (
    <textarea
      ref={textareaRef}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={`block w-full resize-none overflow-hidden bg-slate-950 border border-slate-700 rounded px-2 py-1.5 text-slate-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-all ${className}`}
      rows={1}
      spellCheck={false}
    />
  );
};

export const Sidebar: React.FC<SidebarProps> = ({
  isOpen,
  width,
  onWidthChange,
  isResizing,
  onResizingChange,
  activeProject,
  activeProjectTemplate,
  onInputChange,
  onAddLocalVariable,
  onDeleteLocalVariable,
  onBakeDownload,
  onRequestAlert
}) => {
  const [activeTab, setActiveTab] = useState<SidebarTab>('vars');
  const [sections, setSections] = useState({ global: true, local: true });
  const [isAddingVariable, setIsAddingVariable] = useState(false);
  const [newVarName, setNewVarName] = useState("");
  const newVarInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isAddingVariable && newVarInputRef.current) {
      newVarInputRef.current.focus();
    }
  }, [isAddingVariable]);

  const handleAddVariable = () => {
    const trimmed = newVarName.trim();
    if (!trimmed) {
      setIsAddingVariable(false);
      return;
    }
    // 重名检查交由父组件或在此处预检查
    if (activeProject?.customInputs?.some(i => i.label === trimmed)) {
      onRequestAlert("重名警告", "该变量名称已存在。");
      return;
    }
    onAddLocalVariable(trimmed);
    setNewVarName("");
    setIsAddingVariable(false);
  };

  if (!isOpen) return null;

  return (
    <div 
      style={{ width }} 
      className="bg-slate-900 flex flex-shrink-0 z-20 transition-all duration-75 relative border-r border-slate-800 animate-in slide-in-from-left-2"
    >
      {/* 左侧窄条图标导航 */}
      <div className="w-12 bg-slate-950 flex flex-col items-center py-6 border-r border-slate-800 gap-6 shrink-0">
        {activeProject && (
          <>
            <button 
              onClick={() => setActiveTab('vars')} 
              title="变量配置" 
              className={`p-2 rounded-lg transition-colors ${activeTab === 'vars' ? 'bg-blue-600 text-white shadow-lg shadow-blue-600/30' : 'text-slate-600 hover:text-slate-300'}`}
            >
              <VarsIcon className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setActiveTab('nav')} 
              title="步骤导航" 
              className={`p-2 rounded-lg transition-colors ${activeTab === 'nav' ? 'bg-amber-600 text-white shadow-lg shadow-amber-600/30' : 'text-slate-600 hover:text-slate-300'}`}
            >
              <NavIcon className="w-5 h-5" />
            </button>
            <button 
              onClick={() => setActiveTab('build')} 
              title="导出烘焙" 
              className={`p-2 rounded-lg transition-colors ${activeTab === 'build' ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/30' : 'text-slate-600 hover:text-slate-300'}`}
            >
              <BuildIcon className="w-5 h-5" />
            </button>
          </>
        )}
      </div>

      {/* 右侧内容区 */}
      <div className="flex-1 flex flex-col bg-slate-900 overflow-hidden">
        <div className="flex-1 overflow-hidden flex flex-col">
          {activeProject && activeProjectTemplate ? (
            <>
              {activeTab === 'vars' && (
                <div className="flex flex-col h-full overflow-y-auto p-4 space-y-6 no-scrollbar">
                  {/* 全局变量 */}
                  <div className="space-y-3">
                    <div 
                      className="flex items-center justify-between cursor-pointer group" 
                      onClick={() => setSections(s => ({ ...s, global: !s.global }))}
                    >
                      <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider group-hover:text-slate-300 transition-colors">全局变量</span>
                      <ChevronDownIcon className={`w-3.5 h-3.5 text-slate-600 transition-transform ${sections.global ? 'rotate-180' : ''}`} />
                    </div>
                    {sections.global && activeProjectTemplate.inputs.map((input, idx) => (
                      <div key={input.id}>
                        <div className="flex items-center gap-2 mb-1.5">
                          <span className="text-[10px] font-mono text-blue-400 font-bold">&lt;{idx}&gt;</span>
                          <label className="text-[10px] text-slate-500 block truncate font-medium">{input.label}</label>
                        </div>
                        <AutoResizeSidebarTextarea 
                          value={activeProject.inputValues[input.id] || ''} 
                          onChange={(val) => onInputChange(input.id, val)} 
                          placeholder="..." 
                        />
                      </div>
                    ))}
                  </div>

                  {/* 本地变量 */}
                  <div className="space-y-3 border-t border-slate-800 pt-4">
                    <div 
                      className="flex items-center justify-between cursor-pointer group" 
                      onClick={() => setSections(s => ({ ...s, local: !s.local }))}
                    >
                      <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-wider group-hover:text-emerald-400 transition-colors">本地变量</span>
                      <ChevronDownIcon className={`w-3.5 h-3.5 text-emerald-600/50 transition-transform ${sections.local ? 'rotate-180' : ''}`} />
                    </div>
                    {sections.local && (
                      <>
                        {(activeProject.customInputs || []).map((input, idx) => (
                          <div key={input.id} className="group relative">
                            <div className="flex items-center gap-2 mb-1.5">
                              <span className="text-[10px] font-mono text-emerald-400 font-bold">&lt;l{idx + 1}&gt;</span>
                              <label className="text-[10px] text-slate-500 block truncate font-medium">{input.label}</label>
                            </div>
                            <AutoResizeSidebarTextarea 
                              value={activeProject.inputValues[input.id] || ''} 
                              onChange={(val) => onInputChange(input.id, val)} 
                              placeholder="..." 
                            />
                            <button 
                              onClick={() => onDeleteLocalVariable(input.id)} 
                              className="absolute top-0 right-0 text-slate-700 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1"
                            >
                              ×
                            </button>
                          </div>
                        ))}
                        {isAddingVariable ? (
                          <div className="bg-slate-950 border border-emerald-900/50 rounded-lg p-3 animate-in slide-in-from-top-1 duration-150">
                            <input 
                              ref={newVarInputRef} 
                              type="text" 
                              className="w-full bg-slate-900 border border-slate-700 rounded-md px-3 py-1.5 text-xs text-white focus:border-emerald-500 outline-none" 
                              placeholder="名称..." 
                              value={newVarName} 
                              onChange={(e) => setNewVarName(e.target.value)} 
                              onKeyDown={(e) => { 
                                if (e.key === 'Enter') handleAddVariable(); 
                                if (e.key === 'Escape') setIsAddingVariable(false); 
                              }} 
                            />
                            <div className="flex justify-end gap-2 mt-3">
                              <button onClick={() => setIsAddingVariable(false)} className="text-[10px] text-slate-500 px-2 py-1 hover:text-white">取消</button>
                              <button onClick={handleAddVariable} className="text-[10px] bg-emerald-600 hover:bg-emerald-500 text-white px-3 py-1 rounded-md transition-colors">添加</button>
                            </div>
                          </div>
                        ) : (
                          <button 
                            onClick={() => setIsAddingVariable(true)} 
                            className="w-full py-2 border border-dashed border-slate-800 rounded-lg text-[10px] text-slate-500 hover:border-emerald-500/50 hover:text-emerald-500 transition-all"
                          >
                            + 新增本地变量
                          </button>
                        )}
                      </>
                    )}
                  </div>
                </div>
              )}

              {activeTab === 'nav' && (
                <div className="h-full overflow-y-auto p-3 space-y-2 no-scrollbar">
                  {activeProjectTemplate.steps.map((step, idx) => (
                    <button 
                      key={step.id} 
                      onClick={() => {
                        const el = document.getElementById(step.id);
                        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                      }} 
                      className="w-full flex items-center gap-3 p-2.5 hover:bg-slate-800 rounded-lg text-left transition-all group"
                    >
                      <span className="w-5 h-5 flex items-center justify-center shrink-0 bg-slate-800 border border-slate-700 text-[10px] font-bold text-slate-500 group-hover:border-amber-500 group-hover:text-amber-500 rounded transition-all">{idx + 1}</span>
                      <span className="text-xs text-slate-300 truncate font-medium">{step.name}</span>
                    </button>
                  ))}
                </div>
              )}

              {activeTab === 'build' && (
                <div className="p-6 flex flex-col items-center justify-center text-center h-full">
                  <div className="w-14 h-14 bg-purple-900/30 text-purple-400 rounded-2xl flex items-center justify-center mb-4 shadow-xl shadow-purple-950/20">
                    <DownloadIcon className="w-7 h-7" />
                  </div>
                  <h4 className="text-xs font-bold text-white mb-2 uppercase tracking-wider">提示词全量烘焙</h4>
                  <p className="text-[10px] text-slate-500 mb-6 px-4 leading-relaxed">一键合并所有步骤内容导出为 .txt 纯文本</p>
                  <Button 
                    variant="primary" 
                    size="sm" 
                    onClick={onBakeDownload} 
                    className="w-full bg-purple-600 hover:bg-purple-500 shadow-lg shadow-purple-600/30 font-bold"
                  >
                    开始导出
                  </Button>
                </div>
              )}
            </>
          ) : (
            <div className="p-10 text-center text-slate-600 text-[10px] flex flex-col items-center gap-3">
              <div className="w-8 h-8 border border-slate-800 rounded-full flex items-center justify-center opacity-40">!</div>
              请先从库中打开项目
            </div>
          )}
        </div>
      </div>

      {/* 调整宽度的拖拽条 */}
      <div 
        className="absolute right-0 top-0 bottom-0 w-1.5 bg-transparent hover:bg-blue-500/30 cursor-col-resize z-40 transition-colors" 
        onMouseDown={(e) => {
          e.preventDefault();
          onResizingChange(true);
        }} 
      />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { Button } from './components/Button';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { Sidebar } from './components/Sidebar';
import { ioService, STORAGE_KEYS } from './services/ioService';
import { 
  MenuIcon, 
  SettingsIcon, 
  CloseIcon, 
  ProjectEmptyIcon,
  ProjectEmptyIcon as LibraryIcon
} from './components/Icons';

type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>('library');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(16);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化加载
  useEffect(() => {
    const init = async () => {
      const lp = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (lp) setProjects(lp.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      const lt = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      setTemplates(lt || DEFAULT_TEMPLATES);
      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
      }
    };
    init();
  }, []);

  // 持久化保存
  useEffect(() => { if(templates.length > 0) ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { if(projects.length > 0) ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize]);

  // 侧边栏宽度调整监听
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: {}, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects(prev => [...prev, newProject]);
    openTab(newProject.id);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newId = `tmpl_${now}`;
    const newTemplate: Template = {
      id: newId,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '核心变量' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '在此处输入模板内容...' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newId);
  };

  const openTab = (id: string) => { 
    if (id === 'library') { setActiveTabId('library'); return; }
    setOpenTabIds(prev => prev.includes(id) ? prev : [...prev, id]); 
    setActiveTabId(id); 
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setOpenTabIds(prev => {
        const next = prev.filter(tid => tid !== id);
        if (activeTabId === id) setActiveTabId(next.length > 0 ? next[next.length - 1] : 'library');
        return next;
    });
  };

  const handleInputChange = (inputId: string, value: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const handleAddLocalVariable = (name: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: name };
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: [...(p.customInputs || []), newInput] 
    } : p));
  };

  const handleDeleteLocalVariable = (varId: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: (p.customInputs || []).filter(i => i.id !== varId) 
    } : p));
  };

  const handleBakeDownload = () => {
    const project = projects.find(p => p.id === activeTabId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });
    ioService.exportFile(`${project.name}_烘焙结果.txt`, fullText);
  };

  const editingTemplate = templates.find(t => t.id === editingTemplateId);
  const activeProject = activeTabId !== 'library' ? projects.find(p => p.id === activeTabId) : null;
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      {/* 全屏模板编辑器覆盖层 */}
      {editingTemplateId && editingTemplate && (
        <div className="fixed inset-0 bg-slate-950 z-[100] animate-in fade-in zoom-in-95 duration-200">
           <TemplateEditor 
              template={editingTemplate} 
              onSave={(u) => { setTemplates(prev => prev.map(t => t.id === u.id ? u : t)); setEditingTemplateId(null); }} 
              onCancel={() => setEditingTemplateId(null)} 
              onRequestConfirm={openConfirm} 
           />
        </div>
      )}

      {/* 顶部导航 */}
      <div className="flex items-center bg-slate-900 h-14 border-b border-slate-800 shrink-0 pr-4 z-30 relative shadow-sm">
           <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="w-14 h-full flex items-center justify-center text-slate-400 hover:text-white border-r border-slate-800 hover:bg-slate-800 transition-colors shrink-0">
             <MenuIcon className="w-5 h-5" />
           </button>
           <div className="px-5 font-bold text-slate-400 text-sm flex items-center gap-3 shrink-0">
              <span className="tracking-tight">提示词拼接器 Pro</span>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1.5 text-slate-600 hover:text-blue-400 transition-colors"><SettingsIcon className="w-4 h-4" /></button>
           </div>
           <div className="flex-1 flex overflow-x-auto no-scrollbar items-end h-full px-3 gap-0.5">
             <div onClick={() => openTab('library')} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[100px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === 'library' ? 'bg-slate-950 border-slate-800 text-white z-10' : 'bg-slate-900 border-transparent text-slate-500'}`}>
                <LibraryIcon className="w-3.5 h-3.5" />
                <span className="truncate flex-1 font-bold">文件库</span>
             </div>
             {openTabIds.map(id => (
               <div key={id} onClick={() => openTab(id)} className={`group relative flex items-center gap-2 px-4 py-2 min-w-[120px] cursor-pointer border-t border-r border-l rounded-t text-sm transition-colors h-[85%] ${activeTabId === id ? 'bg-slate-950 border-slate-800 text-white z-10' : 'bg-slate-900 border-transparent text-slate-500'}`}>
                 <span className="truncate flex-1">{projects.find(p => p.id === id)?.name || '未命名项目'}</span>
                 <button onClick={(e) => closeTab(id, e)} className="p-1 rounded-full hover:bg-slate-700 opacity-0 group-hover:opacity-100 transition-opacity"><CloseIcon className="w-3 h-3" /></button>
               </div>
             ))}
           </div>
      </div>

      <div className="flex-1 flex overflow-hidden relative">
        {/* 重构后的侧边栏组件 */}
        <Sidebar 
          isOpen={isSidebarOpen}
          width={sidebarWidth}
          onWidthChange={setSidebarWidth}
          isResizing={isResizingSidebar}
          onResizingChange={setIsResizingSidebar}
          activeProject={activeProject || null}
          activeProjectTemplate={activeProjectTemplate || null}
          onInputChange={handleInputChange}
          onAddLocalVariable={handleAddLocalVariable}
          onDeleteLocalVariable={handleDeleteLocalVariable}
          onBakeDownload={handleBakeDownload}
          onRequestAlert={openAlert}
        />

        {/* 主内容区域 */}
        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {activeTabId === 'library' ? (
             <FileLibrary 
                projects={projects} 
                templates={templates} 
                onOpenProject={openTab} 
                onCreateProject={createProject} 
                onCreateTemplate={createTemplate} 
                onEditTemplate={setEditingTemplateId} 
                onDuplicateTemplate={(id) => { const t = templates.find(x => x.id === id); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: t.name+' (副本)'}]); setEditingTemplateId(nid); } }} 
                onCreateTemplateFromProject={(id) => { const p = projects.find(x => x.id === id); const t = templates.find(x => x.id === p?.templateId); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: p?.name+' 提取'}]); setEditingTemplateId(nid); } }} 
                onDeleteProject={(id) => openConfirm("删除项目", "确定删除？", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} 
                onDeleteProjects={(ids) => openConfirm("批量删除", "确定删除？", () => { setProjects(projects.filter(p => !ids.includes(p.id))); ids.forEach(id => closeTab(id)); })}
                onDeleteTemplate={(id) => openConfirm("删除模版", "确定删除？", () => setTemplates(templates.filter(t => t.id !== id)))} 
                onImportData={(p, t) => { setProjects(p); setTemplates(t); }} 
                onOpenExport={() => setIsExportModalOpen(true)} 
                onRequestAlert={openAlert} 
                onClose={() => { if(openTabIds.length > 0) setActiveTabId(openTabIds[0]); }} 
             />
           ) : activeProject && activeProjectTemplate ? (
             <ProjectRunner 
                project={activeProject} 
                template={activeProjectTemplate} 
                onUpdateProject={(id, u) => setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p))} 
                onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} 
                onRequestConfirm={openConfirm} 
                rightPanelWidth={rightPanelWidth} 
                onRightPanelWidthChange={setRightPanelWidth} 
                isRightPanelOpen={isRightPanelOpen} 
                onRightPanelOpenChange={setIsRightPanelOpen} 
             />
           ) : <div className="flex items-center justify-center h-full text-slate-700">请从文件库打开项目</div>}
        </div>
      </div>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={() => {}} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

