import React, { useState, useLayoutEffect, useRef, useEffect } from 'react';
import { Project, Template, TemplateStep } from '../types';
import { PromptEditor } from './PromptEditor';
import { Button } from './Button';
import { FloatingToast, useToast } from './FloatingToast';

interface ProjectRunnerProps {
  project: Project;
  template: Template;
  onUpdateProject: (projectId: string, updates: Partial<Project>) => void;
  onUpdateTemplate: (templateId: string, updates: Partial<Template>) => void;
  onRequestConfirm: (title: string, message: string, onConfirm: () => void) => void;
  fontSizeClass?: string;
  rightPanelWidth: number;
  onRightPanelWidthChange: (width: number) => void;
  isRightPanelOpen: boolean;
  onRightPanelOpenChange: (isOpen: boolean) => void;
}

const AutoResizeTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  className?: string;
}> = ({ value, onChange, placeholder, className }) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const el = textareaRef.current;
    if (el) { el.style.height = '0px'; el.style.height = `${el.scrollHeight}px`; }
  };
  useLayoutEffect(() => { adjustHeight(); }, [value]);
  return (
    <textarea ref={textareaRef} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} className={`block w-full resize-none overflow-hidden bg-transparent outline-none focus:ring-0 p-0 m-0 ${className}`} rows={1} spellCheck={false} />
  );
};

export const ProjectRunner: React.FC<ProjectRunnerProps> = ({
  project, template, onUpdateProject, onUpdateTemplate, onRequestConfirm, fontSizeClass = 'text-sm', rightPanelWidth, onRightPanelWidthChange, isRightPanelOpen, onRightPanelOpenChange
}) => {
  const [collapsedSteps, setCollapsedSteps] = useState<Record<string, boolean>>({});
  const [isResizingRight, setIsResizingRight] = useState(false);
  const { toasts, showToast, removeToast } = useToast();

  const interpolate = (templateStr: string): string => {
    if (!templateStr) return "";
    let result = templateStr;

    // 1. Global Inputs <0>, <1>... or <Name>
    template.inputs.forEach((input, index) => {
      const val = project.inputValues[input.id] || "";
      result = result.split(`<${index}>`).join(val);
      result = result.split(`<${input.label}>`).join(val);
    });

    // 2. Local Custom Variables <l1>, <l2>... or <Name>
    (project.customInputs || []).forEach((input, index) => {
       const val = project.inputValues[input.id] || "";
       result = result.split(`<l${index + 1}>`).join(val);
       result = result.split(`<${input.label}>`).join(val);
    });

    // 3. Step Output Referencing [[1]], [[2]]... or [[Step Name]]
    template.steps.forEach((step, index) => {
      const output = project.stepOutputs[step.id] || "";
      result = result.split(`[[${index + 1}]]`).join(output);
      result = result.split(`[[${step.name}]]`).join(output);
    });

    return result;
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingRight) return;
      const newWidth = window.innerWidth - e.clientX;
      if (newWidth > 250 && newWidth < 1000) onRightPanelWidthChange(newWidth);
    };
    const handleMouseUp = () => { setIsResizingRight(false); document.body.style.cursor = 'default'; };
    if (isResizingRight) { window.addEventListener('mousemove', handleMouseMove); window.addEventListener('mouseup', handleMouseUp); document.body.style.cursor = 'col-resize'; }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingRight, onRightPanelWidthChange]);

  const handleDoubleClickCopy = (content: string, e: React.MouseEvent) => {
    navigator.clipboard.writeText(content);
    showToast('复制成功', e.clientX, e.clientY);
  };

  return (
    <div className={`flex h-full w-full ${fontSizeClass}`}>
      <div className="flex-1 flex flex-col min-w-0">
         <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 pb-40 no-scrollbar">
            <div className="w-full space-y-8">
                {template.steps.map((step, index) => {
                const override = project.stepOverrides[step.id];
                const rawContent = override?.content !== undefined ? override.content : (step.content || "");
                const interpolated = interpolate(rawContent);
                const isCollapsed = collapsedSteps[step.id];

                return (
                    <div key={step.id} id={step.id} className={`border border-slate-800 rounded-2xl bg-slate-900/40 shadow-sm scroll-mt-8 overflow-hidden transition-all duration-300`}>
                    <div className="flex items-center justify-between px-6 py-4 bg-slate-900 border-b border-slate-800 cursor-pointer hover:bg-slate-800/80 transition-colors" onClick={() => setCollapsedSteps(p => ({...p, [step.id]: !isCollapsed}))}>
                        <div className="flex items-center space-x-4">
                            <span className="text-xs font-mono font-bold text-slate-500 bg-slate-800 px-2 py-0.5 rounded-md">{index + 1}</span>
                            <h3 className="font-black text-slate-200 text-sm tracking-tight">{step.name}</h3>
                        </div>
                        <div className="flex items-center gap-4">
                           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className={`w-5 h-5 text-slate-600 transition-transform ${isCollapsed ? '' : 'rotate-180'}`}><path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z" /></svg>
                        </div>
                    </div>

                    {!isCollapsed && (
                        <div className="p-6 bg-slate-900/20">
                            <PromptEditor label="提示词实时预览" templateContent={rawContent} interpolatedContent={interpolated} originalTemplateContent={step.content || ""} onUpdateOverride={(c) => onUpdateProject(project.id, { stepOverrides: { ...project.stepOverrides, [step.id]: { content: c } } })} onRevert={() => { const o = {...project.stepOverrides}; delete o[step.id]; onUpdateProject(project.id, { stepOverrides: o }); }} onSaveToTemplate={(c) => onRequestConfirm("保存到全局", "确定要将此步骤的局部修改保存回全局模版结构中吗？这会影响该模版下的所有项目。", () => { onUpdateTemplate(template.id, { steps: template.steps.map(s => s.id === step.id ? { ...s, content: c } : s) }); const o = {...project.stepOverrides}; delete o[step.id]; onUpdateProject(project.id, { stepOverrides: o }); })} />
                            <div className="mt-6 border-t border-slate-800/50 pt-6">
                                <div className="flex justify-between items-center mb-3">
                                  <label className="text-[10px] font-bold text-slate-600 uppercase tracking-widest block">步骤输出 / 个人备注 (支持 [[序号]] 引用)</label>
                                  <button onClick={() => onUpdateProject(project.id, { stepOutputs: { ...project.stepOutputs, [step.id]: '' } })} className="text-[10px] text-slate-700 hover:text-red-400 uppercase tracking-tighter font-bold transition-colors">清除内容</button>
                                </div>
                                <div className={`bg-slate-950/50 border border-slate-800/60 rounded-xl px-4 py-3 transition-colors hover:border-slate-700`}>
                                  <AutoResizeTextarea 
                                    className="text-sm text-slate-400 leading-relaxed font-sans min-h-[60px]" 
                                    value={project.stepOutputs[step.id] || ''} 
                                    onChange={(val) => onUpdateProject(project.id, { stepOutputs: { ...project.stepOutputs, [step.id]: val } })} 
                                    placeholder="输入此步骤的生成结果、草稿或用于下一步骤引用的关键信息..." 
                                  />
                                </div>
                            </div>
                        </div>
                    )}
                    </div>
                );
                })}
            </div>
         </div>
      </div>

      {isRightPanelOpen && <div className="w-1.5 bg-slate-800 hover:bg-blue-600 cursor-col-resize z-30 flex-shrink-0 transition-colors" onMouseDown={(e) => { e.preventDefault(); setIsResizingRight(true); }} />}

      <div style={{ width: isRightPanelOpen ? rightPanelWidth : '40px' }} className="bg-slate-900 border-l border-slate-800 flex flex-col flex-shrink-0 transition-all duration-75 relative">
         <div className="flex items-center justify-between p-3 border-b border-slate-800 bg-slate-900 h-12 shrink-0">
             {isRightPanelOpen && <span className="font-bold text-[10px] text-slate-500 uppercase tracking-widest pl-3 truncate">拼接结果实时全览</span>}
             <button onClick={() => onRightPanelOpenChange(!isRightPanelOpen)} className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-500 hover:text-white transition-colors">{isRightPanelOpen ? "»" : "«"}</button>
         </div>
         {isRightPanelOpen && (
           <div className="flex-1 overflow-y-auto p-6 bg-slate-950/30 space-y-8 no-scrollbar">
             {template.steps.map((step, idx) => {
                const override = project.stepOverrides[step.id];
                const content = interpolate(override?.content !== undefined ? override.content : (step.content || ""));
                return (
                  <div key={step.id} className="relative group">
                    <div className="flex items-center gap-3 mb-3">
                      <span className="text-[11px] font-mono text-slate-600 font-bold">&lt;{idx+1}&gt;</span>
                      <span className="text-xs font-black text-slate-500 uppercase truncate tracking-tight">{step.name}</span>
                    </div>
                    <div 
                      onDoubleClick={(e) => handleDoubleClickCopy(content, e)}
                      className="text-slate-300 font-mono text-sm leading-relaxed whitespace-pre-wrap break-words pl-4 py-2 border-l-2 border-slate-800 group-hover:border-blue-500/30 transition-colors relative cursor-copy select-none active:bg-blue-500/5"
                      title="双击复制内容"
                    >
                        {content}
                    </div>
                  </div>
                );
             })}
           </div>
         )}
      </div>

      <FloatingToast toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

/**
 * 集中化 I/O 服务
 * 
 * --- Tauri 2.0 接入指南 ---
 * 1. 确保已安装插件: 
 *    npm add @tauri-apps/plugin-store @tauri-apps/plugin-fs @tauri-apps/plugin-dialog
 *    npm run tauri add dialog
 *    npm run tauri add fs
 *    npm run tauri add store
 * 2. 在 src-tauri/capabilities/main.json 中添加权限:
 *    "permissions": [
 *      "store:allow-get", "store:allow-set", "store:allow-save",
 *      "fs:allow-write-text-file", "fs:allow-read-text-file",
 *      "dialog:allow-save", "dialog:allow-open"
 *    ]
 */
import { load } from "@tauri-apps/plugin-store";
import { save, open } from "@tauri-apps/plugin-dialog";
import { writeTextFile, readTextFile } from "@tauri-apps/plugin-fs";

// --- 动态检测是否在 Tauri 环境中 ---
const IS_TAURI = typeof window !== 'undefined' && (window as any).__TAURI_INTERNALS__ !== undefined;

export const STORAGE_KEYS = {
  PROJECTS: 'prompt-splicer-projects-v2',
  TEMPLATES: 'prompt-splicer-templates-v2',
  SETTINGS: 'prompt-splicer-settings-v2',
};

export const ioService = {
  // --- 数据持久化 ---

  async saveToDisk(key: string, data: any): Promise<void> {
    if (IS_TAURI) {
      try {
        const store = await load("app_data.json");
        await store.set(key, data);
        await store.save();
        console.log('Tauri Save Triggered:', key);
      } catch (e) {
        console.error('Tauri Save Error:', e);
      }
    } else {
      try {
        localStorage.setItem(key, JSON.stringify(data));
      } catch (e) {
        console.error(`Failed to save data for key: ${key}`, e);
      }
    }
  },

  async loadFromDisk<T>(key: string): Promise<T | null> {
    if (IS_TAURI) {
      try {
        const store = await load("app_data.json");
        const val = await store.get<T>(key);
        console.log('Tauri Load Triggered:', key);
        return val || null;
      } catch (e) {
        console.error('Tauri Load Error:', e);
        return null;
      }
    } else {
      const data = localStorage.getItem(key);
      if (data === null || data === "" || data === "undefined") return null;
      try {
        return JSON.parse(data) as T;
      } catch (e) {
        console.error(`Failed to parse data for key: ${key}. Raw data:`, data, e);
        return null;
      }
    }
  },

  // --- 文件导出 ---

  /**
   * 导出文本或 JSON 文件到用户本地
   */
  async exportFile(filename: string, content: string, mimeType: string = 'text/plain'): Promise<void> {
    if (IS_TAURI) {
      try {
        // 弹出保存对话框
        const path = await save({
          defaultPath: filename,
          filters: [{ name: 'Document', extensions: mimeType.includes('json') ? ['json'] : ['txt'] }]
        });
        // 如果用户选择了路径，则写入文件
        if (path) {
          await writeTextFile(path, content);
        }
        console.log('Tauri Export File Triggered:', filename);
      } catch (e) {
        console.error('Tauri Export Error:', e);
      }
    } else {
      // 浏览器环境下的下载实现
      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }
  },

  // --- 文件导入 ---

  /**
   * 处理文件上传读取
   */
  async readFileAsText(file?: File): Promise<string> {
    if (IS_TAURI) {
      try {
        // 弹出打开对话框
        const path = await open({
          multiple: false,
          filters: [{ name: 'JSON Data', extensions: ['json'] }]
        });
        // 如果选择了文件，读取其文本内容
        if (path && typeof path === 'string') {
          return await readTextFile(path);
        }
        console.log('Tauri Read File Triggered');
        return "";
      } catch (e) {
        console.error('Tauri Read Error:', e);
        return "";
      }
    } else {
      if (!file) throw new Error("No file provided for browser upload");
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => resolve(e.target?.result as string || "");
        reader.onerror = (e) => reject(e);
        reader.readAsText(file);
      });
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { Sidebar } from './components/Sidebar';
import { TopNav } from './components/TopNav';
import { ioService, STORAGE_KEYS } from './services/ioService';

type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>('library');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(16);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [cardScale, setCardScale] = useState<number>(300);

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化加载
  useEffect(() => {
    const init = async () => {
      const lp = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (lp) setProjects(lp.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      const lt = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      setTemplates(lt || DEFAULT_TEMPLATES);
      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
        if (settings.cardScale) setCardScale(settings.cardScale);
      }
    };
    init();
  }, []);

  // 持久化保存
  useEffect(() => { if(templates.length > 0) ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { if(projects.length > 0) ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize, cardScale });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize, cardScale]);

  // 侧边栏宽度调整监听
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: {}, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects(prev => [...prev, newProject]);
    openTab(newProject.id);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newId = `tmpl_${now}`;
    const newTemplate: Template = {
      id: newId,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '核心变量' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '在此处输入模板内容...' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newId);
  };

  const openTab = (id: string) => { 
    if (id === 'library') { setActiveTabId('library'); return; }
    setOpenTabIds(prev => prev.includes(id) ? prev : [...prev, id]); 
    setActiveTabId(id); 
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setOpenTabIds(prev => {
        const next = prev.filter(tid => tid !== id);
        if (activeTabId === id) setActiveTabId(next.length > 0 ? next[next.length - 1] : 'library');
        return next;
    });
  };

  const handleInputChange = (inputId: string, value: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const handleAddLocalVariable = (name: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: name };
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: [...(p.customInputs || []), newInput] 
    } : p));
  };

  const handleDeleteLocalVariable = (varId: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: (p.customInputs || []).filter(i => i.id !== varId) 
    } : p));
  };

  const handleBakeDownload = () => {
    const project = projects.find(p => p.id === activeTabId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });
    ioService.exportFile(`${project.name}_烘焙结果.txt`, fullText);
  };

  const editingTemplate = templates.find(t => t.id === editingTemplateId);
  const activeProject = activeTabId !== 'library' ? projects.find(p => p.id === activeTabId) : null;
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      {/* 全屏模板编辑器覆盖层 */}
      {editingTemplateId && editingTemplate && (
        <div className="fixed inset-0 bg-slate-950 z-[100] animate-in fade-in zoom-in-95 duration-200">
           <TemplateEditor 
              template={editingTemplate} 
              onSave={(u) => { setTemplates(prev => prev.map(t => t.id === u.id ? u : t)); setEditingTemplateId(null); }} 
              onCancel={() => setEditingTemplateId(null)} 
              onRequestConfirm={openConfirm} 
           />
        </div>
      )}

      {/* 顶部导航组件 */}
      <TopNav 
        isSidebarOpen={isSidebarOpen}
        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        onOpenSettings={() => setIsSettingsOpen(true)}
        activeTabId={activeTabId}
        openTabIds={openTabIds}
        projects={projects}
        onOpenTab={openTab}
        onCloseTab={closeTab}
      />

      <div className="flex-1 flex overflow-hidden relative">
        {/* 侧边栏组件 */}
        <Sidebar 
          isOpen={isSidebarOpen}
          width={sidebarWidth}
          onWidthChange={setSidebarWidth}
          isResizing={isResizingSidebar}
          onResizingChange={setIsResizingSidebar}
          activeProject={activeProject || null}
          activeProjectTemplate={activeProjectTemplate || null}
          onInputChange={handleInputChange}
          onAddLocalVariable={handleAddLocalVariable}
          onDeleteLocalVariable={handleDeleteLocalVariable}
          onBakeDownload={handleBakeDownload}
          onRequestAlert={openAlert}
        />

        {/* 主内容区域 */}
        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {activeTabId === 'library' ? (
             <FileLibrary 
                projects={projects} 
                templates={templates} 
                onOpenProject={openTab} 
                onCreateProject={createProject} 
                onCreateTemplate={createTemplate} 
                onEditTemplate={setEditingTemplateId} 
                onDuplicateTemplate={(id) => { const t = templates.find(x => x.id === id); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: t.name+' (副本)'}]); setEditingTemplateId(nid); } }} 
                onCreateTemplateFromProject={(id) => { const p = projects.find(x => x.id === id); const t = templates.find(x => x.id === p?.templateId); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: p?.name+' 提取'}]); setEditingTemplateId(nid); } }} 
                onDeleteProject={(id) => openConfirm("删除项目", "确定删除？", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} 
                onDeleteProjects={(ids) => openConfirm("批量删除", "确定删除？", () => { setProjects(projects.filter(p => !ids.includes(p.id))); ids.forEach(id => closeTab(id)); })}
                onDeleteTemplate={(id) => openConfirm("删除模版", "确定删除？", () => setTemplates(templates.filter(t => t.id !== id)))} 
                onImportData={(p, t) => { setProjects(p); setTemplates(t); }} 
                onOpenExport={() => setIsExportModalOpen(true)} 
                onRequestAlert={openAlert} 
                cardScale={cardScale}
                onCardScaleChange={setCardScale}
             />
           ) : activeProject && activeProjectTemplate ? (
             <ProjectRunner 
                project={activeProject} 
                template={activeProjectTemplate} 
                onUpdateProject={(id, u) => setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p))} 
                onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} 
                onRequestConfirm={openConfirm} 
                rightPanelWidth={rightPanelWidth} 
                onRightPanelWidthChange={setRightPanelWidth} 
                isRightPanelOpen={isRightPanelOpen} 
                onRightPanelOpenChange={setIsRightPanelOpen} 
             />
           ) : <div className="flex items-center justify-center h-full text-slate-700">请从文件库打开项目</div>}
        </div>
      </div>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={() => {}} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { CreateProjectModal } from './CreateProjectModal';
import { HighlightEffect } from './HighlightEffect';
import { ioService } from '../services/ioService';

interface FileLibraryProps {
  projects: Project[];
  templates: Template[];
  onOpenProject: (projectId: string) => void;
  onCreateProject: (templateId: string, name: string) => void;
  onCreateTemplate: () => void;
  onEditTemplate: (templateId: string) => void;
  onDuplicateTemplate: (templateId: string) => void;
  onCreateTemplateFromProject: (projectId: string) => void;
  onDeleteProject: (id: string) => void;
  onDeleteProjects: (ids: string[]) => void;
  onDeleteTemplate: (id: string) => void;
  onImportData: (projects: Project[], templates: Template[]) => void;
  onOpenExport: () => void;
  onRequestAlert: (title: string, message: string) => void;
  cardScale: number;
  onCardScaleChange: (scale: number) => void;
}

const formatFullDate = (ts: number) => {
    const d = new Date(ts);
    return `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')} ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}:${d.getSeconds().toString().padStart(2,'0')}`;
};

type SortKey = 'lastModified' | 'createdAt' | 'name';

export const FileLibrary: React.FC<FileLibraryProps> = ({
  projects,
  templates,
  onOpenProject,
  onCreateProject,
  onCreateTemplate,
  onEditTemplate,
  onDuplicateTemplate,
  onCreateTemplateFromProject,
  onDeleteProject,
  onDeleteProjects,
  onDeleteTemplate,
  onImportData,
  onOpenExport,
  onRequestAlert,
  cardScale,
  onCardScaleChange
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [sortBy, setSortBy] = useState<SortKey>('lastModified');
  const [isGrouped, setIsGrouped] = useState<boolean>(false);
  const [createModalInfo, setCreateModalInfo] = useState<{ isOpen: boolean; templateId: string | null }>({
    isOpen: false,
    templateId: null
  });
  const [lastCreatedId, setLastCreatedId] = useState<string | null>(null);

  // 批量模式状态
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const sortProjects = (projs: Project[]) => {
    return [...projs].sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'createdAt') return (b.createdAt || 0) - (a.createdAt || 0);
      return (b.lastModifiedAt || 0) - (a.lastModifiedAt || 0);
    });
  };

  useEffect(() => {
    if (projects.length > 0) {
      const latest = [...projects].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
      if (Date.now() - (latest.createdAt || 0) < 5000) {
        setLastCreatedId(latest.id);
      }
    }
  }, [projects.length]);

  const groupedData = useMemo(() => {
    const sorted = sortProjects(projects);
    if (!isGrouped) return { 'all': sorted };
    const groups: Record<string, Project[]> = {};
    sorted.forEach(p => {
      const template = templates.find(t => t.id === p.templateId);
      const groupName = template?.name || '未分类项目';
      if (!groups[groupName]) groups[groupName] = [];
      groups[groupName].push(p);
    });
    return groups;
  }, [projects, sortBy, isGrouped, templates]);

  const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const content = await ioService.readFileAsText(file);
      if (!content || content.trim() === "") {
        onRequestAlert('失败', '所选文件为空。');
        return;
      }
      const data = JSON.parse(content);
      if (data && Array.isArray(data.projects) && Array.isArray(data.templates)) {
        onImportData(data.projects, data.templates);
      } else {
        onRequestAlert('失败', '文件格式不匹配。');
      }
    } catch (err) {
      onRequestAlert('失败', '文件读取或解析 JSON 失败。');
    }
    e.target.value = '';
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const selectAll = () => {
    if (selectedIds.size === projects.length) setSelectedIds(new Set());
    else setSelectedIds(new Set(projects.map(p => p.id)));
  };

  const handleBatchDelete = () => {
    if (selectedIds.size === 0) return;
    onDeleteProjects(Array.from(selectedIds));
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const renderProjectCard = (p: Project) => {
    const template = templates.find(t => t.id === p.templateId);
    const isSelected = selectedIds.has(p.id);

    return (
      <HighlightEffect key={p.id} isActive={lastCreatedId === p.id}>
        <div 
          onClick={() => isSelectionMode ? toggleSelection(p.id) : onOpenProject(p.id)} 
          className={`group bg-slate-900 hover:bg-slate-800 border transition-all relative rounded-xl p-4 cursor-pointer ${
            isSelected ? 'border-blue-500 ring-2 ring-blue-500/20 bg-slate-800' : 'border-slate-800 hover:border-blue-500/50'
          }`}
        >
          {isSelectionMode && (
            <div className={`absolute top-3 left-3 w-5 h-5 rounded border flex items-center justify-center transition-colors z-20 ${
              isSelected ? 'bg-blue-600 border-blue-500' : 'bg-slate-950 border-slate-700'
            }`}>
              {isSelected && (
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5 text-white">
                  <path fillRule="evenodd" d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" clipRule="evenodd" />
                </svg>
              )}
            </div>
          )}

          <div className={`${isSelectionMode ? 'pl-7' : ''} mb-2`}>
              <h4 className="text-base font-bold text-slate-200 group-hover:text-white mb-1 truncate">{p.name}</h4>
              <div className="flex items-center gap-2">
                <span className="text-[10px] bg-slate-950 text-slate-500 px-1.5 py-0.5 rounded border border-slate-800/50">
                  模版: {template?.name || '已失效'}
                </span>
              </div>
          </div>
          <div className="flex flex-col gap-1 border-t border-slate-800/40 mt-3 pt-3">
              <div className="flex justify-between items-center text-[9px] font-mono text-slate-600"><span>创建: {formatFullDate(p.createdAt)}</span></div>
              <div className="flex justify-between items-center text-[9px] font-mono text-blue-600/60"><span>最后修改: {formatFullDate(p.lastModifiedAt)}</span></div>
          </div>

          {!isSelectionMode && (
            <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={(e) => { e.stopPropagation(); onCreateTemplateFromProject(p.id); }} title="提取模版" className="text-slate-500 hover:text-blue-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M8 2a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 8 2ZM4.25 5a.75.75 0 0 1 .75-.75h1.5a.75.75 0 0 1 0 1.5H5v6.5h6v-6.5h-1.5a.75.75 0 0 1 0-1.5h1.5A1.5 1.5 0 0 1 12.5 5.75v6.5A1.5 1.5 0 0 1 11 13.75H5a1.5 1.5 0 0 1-1.5-1.5v-6.5A1.5 1.5 0 0 1 4.25 5Z" /></svg></button>
                <button onClick={(e) => { e.stopPropagation(); onDeleteProject(p.id); }} title="彻底删除" className="text-slate-500 hover:text-red-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
            </div>
          )}
        </div>
      </HighlightEffect>
    );
  };

  return (
    <div className="absolute inset-0 bg-slate-950 z-50 flex flex-col animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">文件库</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">本地项目管理器</span>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 mr-4">
            <input type="file" ref={fileInputRef} onChange={handleImportFile} className="hidden" accept=".json" />
            <button onClick={() => fileInputRef.current?.click()} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">恢复数据</button>
            <button onClick={onOpenExport} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">备份数据</button>
          </div>

        </div>
      </div>
      <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-950 relative pb-24">
         <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8 flex flex-col">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-6 pb-2 border-b border-slate-800/50">
                <h3 className="text-sm font-bold text-blue-400 uppercase tracking-widest">我的项目资产</h3>
                <div className="flex flex-wrap items-center gap-4 md:gap-6">
                  {/* 批量选择开关 */}
                  <button 
                    onClick={() => { setIsSelectionMode(!isSelectionMode); setSelectedIds(new Set()); }}
                    className={`flex items-center gap-2 px-3 py-1.5 text-[10px] font-bold rounded-lg border transition-all ${
                      isSelectionMode ? 'bg-blue-600 border-blue-400 text-white shadow-lg shadow-blue-600/30' : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-600'
                    }`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5"><path d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" /></svg>
                    {isSelectionMode ? '退出管理' : '批量管理'}
                  </button>

                  <div className="flex items-center gap-3">
                    <span className="text-[10px] text-slate-500 font-bold uppercase whitespace-nowrap">缩放</span>
                    <input type="range" min="150" max="500" value={cardScale} onChange={(e) => onCardScaleChange(parseInt(e.target.value))} className="w-24 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-600"/>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setIsGrouped(!isGrouped)} className={`flex items-center gap-2 px-3 py-1 text-[10px] font-bold rounded border transition-colors ${isGrouped ? 'bg-blue-600/20 border-blue-500/50 text-blue-400' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-slate-300'}`}><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M2 3.75A.75.75 0 0 1 2.75 3h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 3.75ZM2 8a.75.75 0 0 1 .75-.75h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 8Zm.75 3.5a.75.75 0 0 0 0 1.5h10.5a.75.75 0 0 0 0-1.5H2.75Z" /></svg>{isGrouped ? '已分组' : '平铺'}</button>
                  </div>
                  <div className="flex items-center gap-2">
                    <select value={sortBy} onChange={(e) => setSortBy(e.target.value as SortKey)} className="bg-slate-900 border border-slate-800 rounded px-2 py-1 text-[10px] text-slate-400 outline-none hover:border-slate-600 transition-colors"><option value="lastModified">修改时间</option><option value="createdAt">创建时间</option><option value="name">名称</option></select>
                  </div>
                </div>
            </div>
            <div className="space-y-10">
              {Object.entries(groupedData).map(([groupName, projs]) => (
                <div key={groupName} className="space-y-4">
                  {isGrouped && (<div className="flex items-center gap-3"><div className="h-4 w-1 bg-blue-500 rounded-full"></div><h4 className="text-xs font-black text-slate-500 uppercase tracking-tighter">{groupName} <span className="ml-2 text-[10px] font-normal text-slate-700">({(projs as Project[]).length} 个项目)</span></h4></div>)}
                  <div className="grid gap-4" style={{ gridTemplateColumns: `repeat(auto-fill, minmax(${cardScale}px, 1fr))` }}>{(projs as Project[]).map(p => renderProjectCard(p))}</div>
                </div>
              ))}
            </div>
          </div>
          <div className="lg:col-span-4">
             <div className="flex items-center justify-between mb-6 pb-2 border-b border-slate-800/50"><h3 className="text-sm font-bold text-emerald-400 uppercase tracking-widest">快速创建</h3><button onClick={onCreateTemplate} className="text-[10px] text-slate-500 hover:text-white transition-colors underline underline-offset-4">新建模版</button></div>
             <div className="grid grid-cols-1 gap-3">
              {templates.map(t => (
                <div key={t.id} className="bg-slate-900/50 border border-slate-800 rounded-lg p-4 transition-colors">
                  <h4 className="font-bold text-slate-200 text-sm mb-1">{t.name}</h4>
                  <div className="flex gap-2 text-[9px] text-slate-600 mb-4 font-mono"><span>{t.steps.length} STEPS</span><span>{t.inputs.length} VARS</span></div>
                  <div className="flex gap-2">
                      <Button onClick={() => setCreateModalInfo({ isOpen: true, templateId: t.id })} className="flex-1 h-8 text-[11px]" size="sm" variant="success">使用模版</Button>
                      <button onClick={() => onEditTemplate(t.id)} className="px-3 bg-slate-950 border border-slate-800 text-[10px] text-slate-500 hover:text-white rounded" title="编辑模版结构">编辑</button>
                      <button onClick={() => onDeleteTemplate(t.id)} className="px-2 bg-slate-950 border border-slate-800 text-slate-500 hover:text-red-400 rounded transition-colors" title="删除模版"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* 批量操作工具栏 */}
        {isSelectionMode && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/80 backdrop-blur-xl border border-slate-700 rounded-2xl px-6 py-4 flex items-center gap-6 shadow-2xl z-[60] animate-in slide-in-from-bottom-4 duration-300 ring-1 ring-white/5">
              <div className="flex flex-col pr-6 border-r border-slate-800">
                <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">已选择</span>
                <span className="text-xl font-black text-blue-400">{selectedIds.size}</span>
              </div>
              <div className="flex gap-3">
                <Button variant="ghost" size="sm" onClick={selectAll} className="text-slate-300 hover:bg-slate-800">
                  {selectedIds.size === projects.length ? '取消全选' : '全选所有'}
                </Button>
                <Button variant="danger" size="sm" onClick={handleBatchDelete} disabled={selectedIds.size === 0} className="shadow-lg shadow-red-500/20 px-6 font-bold">
                  批量删除
                </Button>
                <button onClick={() => setIsSelectionMode(false)} className="text-[11px] text-slate-500 hover:text-white px-2">取消</button>
              </div>
          </div>
        )}
      </div>
      <CreateProjectModal isOpen={createModalInfo.isOpen} onConfirm={(name) => { if (createModalInfo.templateId) { onCreateProject(createModalInfo.templateId, name); setCreateModalInfo({ isOpen: false, templateId: null }); } }} onCancel={() => setCreateModalInfo({ isOpen: false, templateId: null })} />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { Sidebar } from './components/Sidebar';
import { TopNav } from './components/TopNav';
import { ioService, STORAGE_KEYS } from './services/ioService';

type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>('library');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(16);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [cardScale, setCardScale] = useState<number>(300);

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化加载
  useEffect(() => {
    const init = async () => {
      const lp = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (lp) setProjects(lp.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      const lt = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      setTemplates(lt || DEFAULT_TEMPLATES);
      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
        if (settings.cardScale) setCardScale(settings.cardScale);
      }
    };
    init();
  }, []);

  // 持久化保存
  useEffect(() => { if(templates.length > 0) ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { if(projects.length > 0) ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize, cardScale });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize, cardScale]);

  // 侧边栏宽度调整监听
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: {}, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects(prev => [...prev, newProject]);
    openTab(newProject.id);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newId = `tmpl_${now}`;
    const newTemplate: Template = {
      id: newId,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '核心变量' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '在此处输入模板内容...' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newId);
  };

  const openTab = (id: string) => { 
    if (id === 'library') { setActiveTabId('library'); return; }
    setOpenTabIds(prev => prev.includes(id) ? prev : [...prev, id]); 
    setActiveTabId(id); 
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setOpenTabIds(prev => {
        const next = prev.filter(tid => tid !== id);
        if (activeTabId === id) setActiveTabId(next.length > 0 ? next[next.length - 1] : 'library');
        return next;
    });
  };

  const handleInputChange = (inputId: string, value: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const handleAddLocalVariable = (name: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: name };
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: [...(p.customInputs || []), newInput] 
    } : p));
  };

  const handleDeleteLocalVariable = (varId: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: (p.customInputs || []).filter(i => i.id !== varId) 
    } : p));
  };

  const handleBakeDownload = () => {
    const project = projects.find(p => p.id === activeTabId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });
    ioService.exportFile(`${project.name}_烘焙结果.txt`, fullText);
  };

  const handleDownloadAllData = () => {
    const backupData = {
      projects,
      templates,
      exportDate: new Date().toISOString(),
      version: "2.0"
    };
    const jsonString = JSON.stringify(backupData, null, 2);
    const dateStr = new Date().toISOString().split('T')[0];
    ioService.exportFile(`prompt_splicer_backup_${dateStr}.json`, jsonString, 'application/json');
  };

  const editingTemplate = templates.find(t => t.id === editingTemplateId);
  const activeProject = activeTabId !== 'library' ? projects.find(p => p.id === activeTabId) : null;
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      {/* 全屏模板编辑器覆盖层 */}
      {editingTemplateId && editingTemplate && (
        <div className="fixed inset-0 bg-slate-950 z-[100] animate-in fade-in zoom-in-95 duration-200">
           <TemplateEditor 
              template={editingTemplate} 
              onSave={(u) => { setTemplates(prev => prev.map(t => t.id === u.id ? u : t)); setEditingTemplateId(null); }} 
              onCancel={() => setEditingTemplateId(null)} 
              onRequestConfirm={openConfirm} 
           />
        </div>
      )}

      {/* 顶部导航组件 */}
      <TopNav 
        isSidebarOpen={isSidebarOpen}
        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        onOpenSettings={() => setIsSettingsOpen(true)}
        activeTabId={activeTabId}
        openTabIds={openTabIds}
        projects={projects}
        onOpenTab={openTab}
        onCloseTab={closeTab}
      />

      <div className="flex-1 flex overflow-hidden relative">
        {/* 侧边栏组件 */}
        <Sidebar 
          isOpen={isSidebarOpen}
          width={sidebarWidth}
          onWidthChange={setSidebarWidth}
          isResizing={isResizingSidebar}
          onResizingChange={setIsResizingSidebar}
          activeProject={activeProject || null}
          activeProjectTemplate={activeProjectTemplate || null}
          onInputChange={handleInputChange}
          onAddLocalVariable={handleAddLocalVariable}
          onDeleteLocalVariable={handleDeleteLocalVariable}
          onBakeDownload={handleBakeDownload}
          onRequestAlert={openAlert}
        />

        {/* 主内容区域 */}
        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {activeTabId === 'library' ? (
             <FileLibrary 
                projects={projects} 
                templates={templates} 
                onOpenProject={openTab} 
                onCreateProject={createProject} 
                onCreateTemplate={createTemplate} 
                onEditTemplate={setEditingTemplateId} 
                onDuplicateTemplate={(id) => { const t = templates.find(x => x.id === id); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: t.name+' (副本)'}]); setEditingTemplateId(nid); } }} 
                onCreateTemplateFromProject={(id) => { const p = projects.find(x => x.id === id); const t = templates.find(x => x.id === p?.templateId); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: p?.name+' 提取'}]); setEditingTemplateId(nid); } }} 
                onDeleteProject={(id) => openConfirm("删除项目", "确定删除？", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} 
                onDeleteProjects={(ids) => openConfirm("批量删除", "确定删除？", () => { setProjects(projects.filter(p => !ids.includes(p.id))); ids.forEach(id => closeTab(id)); })}
                onDeleteTemplate={(id) => openConfirm("删除模版", "确定删除？", () => setTemplates(templates.filter(t => t.id !== id)))} 
                onImportData={(p, t) => { setProjects(p); setTemplates(t); }} 
                onOpenExport={() => setIsExportModalOpen(true)} 
                onRequestAlert={openAlert} 
                cardScale={cardScale}
                onCardScaleChange={setCardScale}
             />
           ) : activeProject && activeProjectTemplate ? (
             <ProjectRunner 
                project={activeProject} 
                template={activeProjectTemplate} 
                onUpdateProject={(id, u) => setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p))} 
                onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} 
                onRequestConfirm={openConfirm} 
                rightPanelWidth={rightPanelWidth} 
                onRightPanelWidthChange={setRightPanelWidth} 
                isRightPanelOpen={isRightPanelOpen} 
                onRightPanelOpenChange={setIsRightPanelOpen} 
             />
           ) : <div className="flex items-center justify-center h-full text-slate-700">请从文件库打开项目</div>}
        </div>
      </div>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={handleDownloadAllData} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { CreateProjectModal } from './CreateProjectModal';
import { HighlightEffect } from './HighlightEffect';
import { ioService } from '../services/ioService';

interface FileLibraryProps {
  projects: Project[];
  templates: Template[];
  onOpenProject: (projectId: string) => void;
  onCreateProject: (templateId: string, name: string) => void;
  onCreateTemplate: () => void;
  onEditTemplate: (templateId: string) => void;
  onDuplicateTemplate: (templateId: string) => void;
  onCreateTemplateFromProject: (projectId: string) => void;
  onDeleteProject: (id: string) => void;
  onDeleteProjects: (ids: string[]) => void;
  onDeleteTemplate: (id: string) => void;
  onImportData: (projects: Project[], templates: Template[]) => void;
  onOpenExport: () => void;
  onRequestAlert: (title: string, message: string) => void;
  cardScale: number;
  onCardScaleChange: (scale: number) => void;
}

const formatFullDate = (ts: number) => {
    const d = new Date(ts);
    return `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')} ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}:${d.getSeconds().toString().padStart(2,'0')}`;
};

type SortKey = 'lastModified' | 'createdAt' | 'name';

export const FileLibrary: React.FC<FileLibraryProps> = ({
  projects,
  templates,
  onOpenProject,
  onCreateProject,
  onCreateTemplate,
  onEditTemplate,
  onDuplicateTemplate,
  onCreateTemplateFromProject,
  onDeleteProject,
  onDeleteProjects,
  onDeleteTemplate,
  onImportData,
  onOpenExport,
  onRequestAlert,
  cardScale,
  onCardScaleChange
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [sortBy, setSortBy] = useState<SortKey>('lastModified');
  const [isGrouped, setIsGrouped] = useState<boolean>(false);
  const [createModalInfo, setCreateModalInfo] = useState<{ isOpen: boolean; templateId: string | null }>({
    isOpen: false,
    templateId: null
  });
  const [lastCreatedId, setLastCreatedId] = useState<string | null>(null);

  // 批量模式状态
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const sortProjects = (projs: Project[]) => {
    return [...projs].sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'createdAt') return (b.createdAt || 0) - (a.createdAt || 0);
      return (b.lastModifiedAt || 0) - (a.lastModifiedAt || 0);
    });
  };

  useEffect(() => {
    if (projects.length > 0) {
      const latest = [...projects].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
      if (Date.now() - (latest.createdAt || 0) < 5000) {
        setLastCreatedId(latest.id);
      }
    }
  }, [projects.length]);

  const groupedData = useMemo(() => {
    const sorted = sortProjects(projects);
    if (!isGrouped) return { 'all': sorted };
    const groups: Record<string, Project[]> = {};
    sorted.forEach(p => {
      const template = templates.find(t => t.id === p.templateId);
      const groupName = template?.name || '未分类项目';
      if (!groups[groupName]) groups[groupName] = [];
      groups[groupName].push(p);
    });
    return groups;
  }, [projects, sortBy, isGrouped, templates]);

  const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const content = await ioService.readFileAsText(file);
      if (!content || content.trim() === "") {
        onRequestAlert('失败', '所选文件为空。');
        return;
      }
      const data = JSON.parse(content);
      if (data && Array.isArray(data.projects) && Array.isArray(data.templates)) {
        onImportData(data.projects, data.templates);
      } else {
        onRequestAlert('失败', '文件格式不匹配。');
      }
    } catch (err) {
      onRequestAlert('失败', '文件读取或解析 JSON 失败。');
    }
    e.target.value = '';
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const selectAll = () => {
    if (selectedIds.size === projects.length) setSelectedIds(new Set());
    else setSelectedIds(new Set(projects.map(p => p.id)));
  };

  const handleBatchDelete = () => {
    if (selectedIds.size === 0) return;
    onDeleteProjects(Array.from(selectedIds));
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const renderProjectCard = (p: Project) => {
    const template = templates.find(t => t.id === p.templateId);
    const isSelected = selectedIds.has(p.id);

    return (
      <HighlightEffect key={p.id} isActive={lastCreatedId === p.id}>
        <div 
          onClick={() => isSelectionMode ? toggleSelection(p.id) : onOpenProject(p.id)} 
          className={`group bg-slate-900 hover:bg-slate-800 border transition-all relative rounded-xl p-4 cursor-pointer ${
            isSelected ? 'border-blue-500 ring-2 ring-blue-500/20 bg-slate-800' : 'border-slate-800 hover:border-blue-500/50'
          }`}
        >
          {isSelectionMode && (
            <div className={`absolute top-3 left-3 w-5 h-5 rounded border flex items-center justify-center transition-colors z-20 ${
              isSelected ? 'bg-blue-600 border-blue-500' : 'bg-slate-950 border-slate-700'
            }`}>
              {isSelected && (
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5 text-white">
                  <path fillRule="evenodd" d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" clipRule="evenodd" />
                </svg>
              )}
            </div>
          )}

          <div className={`${isSelectionMode ? 'pl-7' : ''} mb-2`}>
              <h4 className="text-base font-bold text-slate-200 group-hover:text-white mb-1 truncate">{p.name}</h4>
              <div className="flex items-center gap-2">
                <span className="text-[10px] bg-slate-950 text-slate-500 px-1.5 py-0.5 rounded border border-slate-800/50">
                  模版: {template?.name || '已失效'}
                </span>
              </div>
          </div>
          <div className="flex flex-col gap-1 border-t border-slate-800/40 mt-3 pt-3">
              <div className="flex justify-between items-center text-[9px] font-mono text-slate-600"><span>创建: {formatFullDate(p.createdAt)}</span></div>
              <div className="flex justify-between items-center text-[9px] font-mono text-blue-600/60"><span>最后修改: {formatFullDate(p.lastModifiedAt)}</span></div>
          </div>

          {!isSelectionMode && (
            <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={(e) => { e.stopPropagation(); onCreateTemplateFromProject(p.id); }} title="提取模版" className="text-slate-500 hover:text-blue-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M8 2a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 8 2ZM4.25 5a.75.75 0 0 1 .75-.75h1.5a.75.75 0 0 1 0 1.5H5v6.5h6v-6.5h-1.5a.75.75 0 0 1 0-1.5h1.5A1.5 1.5 0 0 1 12.5 5.75v6.5A1.5 1.5 0 0 1 11 13.75H5a1.5 1.5 0 0 1-1.5-1.5v-6.5A1.5 1.5 0 0 1 4.25 5Z" /></svg></button>
                <button onClick={(e) => { e.stopPropagation(); onDeleteProject(p.id); }} title="彻底删除" className="text-slate-500 hover:text-red-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
            </div>
          )}
        </div>
      </HighlightEffect>
    );
  };

  return (
    <div className="absolute inset-0 bg-slate-950 z-50 flex flex-col animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">文件库</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">本地项目管理器</span>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 mr-4">
            <input type="file" ref={fileInputRef} onChange={handleImportFile} className="hidden" accept=".json" />
            <button onClick={() => fileInputRef.current?.click()} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">恢复数据</button>
            <button onClick={onOpenExport} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">备份数据</button>
          </div>

        </div>
      </div>
      <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-950 relative pb-24">
         <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8 flex flex-col">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-6 pb-2 border-b border-slate-800/50">
                <h3 className="text-sm font-bold text-blue-400 uppercase tracking-widest">我的项目资产</h3>
                <div className="flex flex-wrap items-center gap-4 md:gap-6">
                  {/* 批量选择开关 */}
                  <button 
                    onClick={() => { setIsSelectionMode(!isSelectionMode); setSelectedIds(new Set()); }}
                    className={`flex items-center gap-2 px-3 py-1.5 text-[10px] font-bold rounded-lg border transition-all ${
                      isSelectionMode ? 'bg-blue-600 border-blue-400 text-white shadow-lg shadow-blue-600/30' : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-600'
                    }`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5"><path d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" /></svg>
                    {isSelectionMode ? '退出管理' : '批量管理'}
                  </button>

                  <div className="flex items-center gap-3">
                    <span className="text-[10px] text-slate-500 font-bold uppercase whitespace-nowrap">缩放</span>
                    <input type="range" min="150" max="500" value={cardScale} onChange={(e) => onCardScaleChange(parseInt(e.target.value))} className="w-24 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-600"/>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setIsGrouped(!isGrouped)} className={`flex items-center gap-2 px-3 py-1 text-[10px] font-bold rounded border transition-colors ${isGrouped ? 'bg-blue-600/20 border-blue-500/50 text-blue-400' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-slate-300'}`}><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M2 3.75A.75.75 0 0 1 2.75 3h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 3.75ZM2 8a.75.75 0 0 1 .75-.75h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 8Zm.75 3.5a.75.75 0 0 0 0 1.5h10.5a.75.75 0 0 0 0-1.5H2.75Z" /></svg>{isGrouped ? '已分组' : '平铺'}</button>
                  </div>
                  <div className="flex items-center gap-2">
                    <select value={sortBy} onChange={(e) => setSortBy(e.target.value as SortKey)} className="bg-slate-900 border border-slate-800 rounded px-2 py-1 text-[10px] text-slate-400 outline-none hover:border-slate-600 transition-colors"><option value="lastModified">修改时间</option><option value="createdAt">创建时间</option><option value="name">名称</option></select>
                  </div>
                </div>
            </div>
            <div className="space-y-10">
              {Object.entries(groupedData).map(([groupName, projs]) => (
                <div key={groupName} className="space-y-4">
                  {isGrouped && (<div className="flex items-center gap-3"><div className="h-4 w-1 bg-blue-500 rounded-full"></div><h4 className="text-xs font-black text-slate-500 uppercase tracking-tighter">{groupName} <span className="ml-2 text-[10px] font-normal text-slate-700">({(projs as Project[]).length} 个项目)</span></h4></div>)}
                  <div className="grid gap-4" style={{ gridTemplateColumns: `repeat(auto-fill, minmax(${cardScale}px, 1fr))` }}>{(projs as Project[]).map(p => renderProjectCard(p))}</div>
                </div>
              ))}
            </div>
          </div>
          <div className="lg:col-span-4">
             <div className="flex items-center justify-between mb-6 pb-2 border-b border-slate-800/50"><h3 className="text-sm font-bold text-emerald-400 uppercase tracking-widest">快速创建</h3><button onClick={onCreateTemplate} className="text-[10px] text-slate-500 hover:text-white transition-colors underline underline-offset-4">新建模版</button></div>
             <div className="grid grid-cols-1 gap-3">
              {templates.map(t => (
                <div key={t.id} className="bg-slate-900/50 border border-slate-800 rounded-lg p-4 transition-colors">
                  <h4 className="font-bold text-slate-200 text-sm mb-1">{t.name}</h4>
                  <div className="flex gap-2 text-[9px] text-slate-600 mb-4 font-mono"><span>{t.steps.length} STEPS</span><span>{t.inputs.length} VARS</span></div>
                  <div className="flex gap-2">
                      <Button onClick={() => setCreateModalInfo({ isOpen: true, templateId: t.id })} className="flex-1 h-8 text-[11px]" size="sm" variant="success">使用模版</Button>
                      <button onClick={() => onDuplicateTemplate(t.id)} className="px-2.5 bg-slate-950 border border-slate-800 text-slate-500 hover:text-blue-400 rounded transition-colors" title="复制模版">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5">
                          <path d="M4 4c0-1.1.9-2 2-2h4.688c.265 0 .52.105.707.293l2.312 2.312c.188.188.293.442.293.707V12c0 1.1-.9 2-2 2H6c-1.1 0-2-.9-2-2V4Z" />
                          <path d="M2.5 6A1.5 1.5 0 0 0 1 7.5v6A1.5 1.5 0 0 0 2.5 15h6A1.5 1.5 0 0 0 10 13.5V13H2.5V6Z" />
                        </svg>
                      </button>
                      <button onClick={() => onEditTemplate(t.id)} className="px-3 bg-slate-950 border border-slate-800 text-[10px] text-slate-500 hover:text-white rounded" title="编辑模版结构">编辑</button>
                      <button onClick={() => onDeleteTemplate(t.id)} className="px-2 bg-slate-950 border border-slate-800 text-slate-500 hover:text-red-400 rounded transition-colors" title="删除模版"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* 批量操作工具栏 */}
        {isSelectionMode && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/80 backdrop-blur-xl border border-slate-700 rounded-2xl px-6 py-4 flex items-center gap-6 shadow-2xl z-[60] animate-in slide-in-from-bottom-4 duration-300 ring-1 ring-white/5">
              <div className="flex flex-col pr-6 border-r border-slate-800">
                <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">已选择</span>
                <span className="text-xl font-black text-blue-400">{selectedIds.size}</span>
              </div>
              <div className="flex gap-3">
                <Button variant="ghost" size="sm" onClick={selectAll} className="text-slate-300 hover:bg-slate-800">
                  {selectedIds.size === projects.length ? '取消全选' : '全选所有'}
                </Button>
                <Button variant="danger" size="sm" onClick={handleBatchDelete} disabled={selectedIds.size === 0} className="shadow-lg shadow-red-500/20 px-6 font-bold">
                  批量删除
                </Button>
                <button onClick={() => setIsSelectionMode(false)} className="text-[11px] text-slate-500 hover:text-white px-2">取消</button>
              </div>
          </div>
        )}
      </div>
      <CreateProjectModal isOpen={createModalInfo.isOpen} onConfirm={(name) => { if (createModalInfo.templateId) { onCreateProject(createModalInfo.templateId, name); setCreateModalInfo({ isOpen: false, templateId: null }); } }} onCancel={() => setCreateModalInfo({ isOpen: false, templateId: null })} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { ioService } from '../services/ioService';

interface MergeModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentProjects: Project[];
  currentTemplates: Template[];
  onConfirmMerge: (projects: Project[], templates: Template[]) => void;
  onRequestAlert: (title: string, message: string) => void;
}

interface MergeItem<T> {
  data: T;
  status: 'new' | 'conflict' | 'identical';
  action: 'import' | 'skip' | 'overwrite';
  newName: string;
}

export const MergeModal: React.FC<MergeModalProps> = ({
  isOpen,
  onClose,
  currentProjects,
  currentTemplates,
  onConfirmMerge,
  onRequestAlert
}) => {
  const [importedData, setImportedData] = useState<{ projects: Project[]; templates: Template[] } | null>(null);
  const [projectQueue, setProjectQueue] = useState<MergeItem<Project>[]>([]);
  const [templateQueue, setTemplateQueue] = useState<MergeItem<Template>[]>([]);

  if (!isOpen) return null;

  const handleFileSelect = async () => {
    try {
      const content = await ioService.readFileAsText();
      if (!content) return;
      const data = JSON.parse(content);
      if (!data.projects || !data.templates) {
        onRequestAlert('格式错误', '该文件不是有效的备份文件。');
        return;
      }
      analyzeData(data.projects, data.templates);
      setImportedData(data);
    } catch (e) {
      onRequestAlert('解析失败', '无法读取或解析该 JSON 文件。');
    }
  };

  const analyzeData = (newProjs: Project[], newTmpls: Template[]) => {
    // 分析模板
    const tQueue: MergeItem<Template>[] = newTmpls.map(nt => {
      const existing = currentTemplates.find(t => t.name === nt.name);
      if (!existing) return { data: nt, status: 'new', action: 'import', newName: nt.name };
      // 简单判断是否完全一致 (忽略ID)
      const isIdentical = JSON.stringify({ ...nt, id: '' }) === JSON.stringify({ ...existing, id: '' });
      return { 
        data: nt, 
        status: isIdentical ? 'identical' : 'conflict', 
        action: isIdentical ? 'skip' : 'skip', 
        newName: nt.name + '_copy' 
      };
    });

    // 分析项目
    const pQueue: MergeItem<Project>[] = newProjs.map(np => {
      const existing = currentProjects.find(p => p.name === np.name);
      if (!existing) return { data: np, status: 'new', action: 'import', newName: np.name };
      const isIdentical = JSON.stringify({ ...np, id: '', lastModifiedAt: 0 }) === JSON.stringify({ ...existing, id: '', lastModifiedAt: 0 });
      return { 
        data: np, 
        status: isIdentical ? 'identical' : 'conflict', 
        action: isIdentical ? 'skip' : 'skip', 
        newName: np.name + '_copy' 
      };
    });

    setTemplateQueue(tQueue);
    setProjectQueue(pQueue);
  };

  const handleConfirm = () => {
    const finalTemplates = templateQueue
      .filter(item => item.action !== 'skip')
      .map(item => {
        if (item.action === 'overwrite') {
          const existing = currentTemplates.find(t => t.name === item.data.name);
          return { ...item.data, id: existing?.id || item.data.id };
        }
        return { ...item.data, name: item.newName, id: `tmpl_merge_${Date.now()}_${Math.random()}` };
      });

    const finalProjects = projectQueue
      .filter(item => item.action !== 'skip')
      .map(item => {
        if (item.action === 'overwrite') {
          const existing = currentProjects.find(p => p.name === item.data.name);
          return { ...item.data, id: existing?.id || item.data.id };
        }
        return { ...item.data, name: item.newName, id: `proj_merge_${Date.now()}_${Math.random()}` };
      });

    onConfirmMerge(finalProjects, finalTemplates);
    onClose();
  };

  const renderList = (title: string, items: MergeItem<any>[], setItems: React.Dispatch<React.SetStateAction<MergeItem<any>[]>>) => (
    <div className="flex-1 flex flex-col min-w-0">
      <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4 px-2">{title} ({items.length})</h4>
      <div className="flex-1 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
        {items.map((item, idx) => (
          <div key={idx} className={`p-3 rounded-lg border transition-all ${
            item.status === 'conflict' ? 'bg-amber-500/5 border-amber-500/20' : 
            item.status === 'identical' ? 'bg-slate-900/50 border-slate-800' : 
            'bg-emerald-500/5 border-emerald-500/20'
          }`}>
            <div className="flex justify-between items-start gap-3">
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold uppercase ${
                    item.status === 'conflict' ? 'bg-amber-500/20 text-amber-500' : 
                    item.status === 'identical' ? 'bg-slate-800 text-slate-500' : 
                    'bg-emerald-500/20 text-emerald-500'
                  }`}>
                    {item.status === 'conflict' ? '冲突' : item.status === 'identical' ? '存在' : '新增'}
                  </span>
                  <span className="text-xs font-bold text-slate-200 truncate">{item.data.name}</span>
                </div>
                {item.action === 'import' && item.status === 'conflict' && (
                  <input 
                    className="w-full bg-slate-950 border border-slate-800 rounded px-2 py-1 text-[11px] text-blue-400 mt-1 outline-none focus:border-blue-500"
                    value={item.newName}
                    onChange={(e) => {
                      const next = [...items];
                      next[idx].newName = e.target.value;
                      setItems(next);
                    }}
                    placeholder="新名称..."
                  />
                )}
              </div>
              <div className="flex flex-col gap-1 shrink-0">
                <select 
                  className="bg-slate-950 border border-slate-800 text-[10px] rounded px-1.5 py-1 text-slate-400 outline-none"
                  value={item.action}
                  onChange={(e) => {
                    const next = [...items];
                    next[idx].action = e.target.value as any;
                    setItems(next);
                  }}
                >
                  <option value="skip">跳过</option>
                  <option value="import">{item.status === 'conflict' ? '作为新项导入' : '导入'}</option>
                  {item.status === 'conflict' && <option value="overwrite">覆盖现有</option>}
                </select>
              </div>
            </div>
          </div>
        ))}
        {items.length === 0 && <div className="text-center py-10 text-slate-700 text-xs italic">无数据</div>}
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[110] flex flex-col bg-slate-950 animate-in fade-in duration-200">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">数据合并面板</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">对比并增量导入项目和模版</span>
        </div>
        <div className="flex items-center gap-3">
          {!importedData ? (
            <Button variant="primary" onClick={handleFileSelect} size="sm">选择备份文件 (.json)</Button>
          ) : (
            <>
              <Button variant="ghost" onClick={() => setImportedData(null)} size="sm">重新选择</Button>
              <Button variant="success" onClick={handleConfirm} size="sm" className="px-8 font-black">确认合并执行</Button>
            </>
          )}
          <button onClick={onClose} className="text-slate-400 hover:text-white p-2 rounded-full hover:bg-slate-800 transition-colors ml-4">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-hidden p-8 flex flex-col">
        {!importedData ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6">
            <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center border border-slate-800 shadow-2xl">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-10 h-10 text-blue-500"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg>
            </div>
            <div className="max-w-md">
              <h3 className="text-lg font-bold text-white mb-2">准备合并数据</h3>
              <p className="text-sm text-slate-500 leading-relaxed">点击上方按钮选择一个备份 JSON 文件。我们将自动检测名称冲突，您可以手动决定是覆盖、并存还是忽略。</p>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex gap-8 min-h-0">
            {renderList("待处理模版", templateQueue as any, setTemplateQueue as any)}
            <div className="w-[1px] bg-slate-800 shrink-0 self-stretch my-10"></div>
            {renderList("待处理项目", projectQueue as any, setProjectQueue as any)}
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-900/50 border-t border-slate-800 flex justify-center gap-10">
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">新增项</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-amber-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">名称冲突</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-slate-700"></div><span className="text-[10px] text-slate-500 font-bold uppercase">完全相同</span></div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { CreateProjectModal } from './CreateProjectModal';
import { HighlightEffect } from './HighlightEffect';
import { MergeModal } from './MergeModal';
import { ioService } from '../services/ioService';

interface FileLibraryProps {
  projects: Project[];
  templates: Template[];
  onOpenProject: (projectId: string) => void;
  onCreateProject: (templateId: string, name: string) => void;
  onCreateTemplate: () => void;
  onEditTemplate: (templateId: string) => void;
  onDuplicateTemplate: (templateId: string) => void;
  onCreateTemplateFromProject: (projectId: string) => void;
  onDeleteProject: (id: string) => void;
  onDeleteProjects: (ids: string[]) => void;
  onDeleteTemplate: (id: string) => void;
  onImportData: (projects: Project[], templates: Template[]) => void;
  onMergeData: (projects: Project[], templates: Template[]) => void;
  onOpenExport: () => void;
  onRequestAlert: (title: string, message: string) => void;
  cardScale: number;
  onCardScaleChange: (scale: number) => void;
}

const formatFullDate = (ts: number) => {
    const d = new Date(ts);
    return `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')} ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}:${d.getSeconds().toString().padStart(2,'0')}`;
};

type SortKey = 'lastModified' | 'createdAt' | 'name';

export const FileLibrary: React.FC<FileLibraryProps> = ({
  projects,
  templates,
  onOpenProject,
  onCreateProject,
  onCreateTemplate,
  onEditTemplate,
  onDuplicateTemplate,
  onCreateTemplateFromProject,
  onDeleteProject,
  onDeleteProjects,
  onDeleteTemplate,
  onImportData,
  onMergeData,
  onOpenExport,
  onRequestAlert,
  cardScale,
  onCardScaleChange
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [sortBy, setSortBy] = useState<SortKey>('lastModified');
  const [isGrouped, setIsGrouped] = useState<boolean>(false);
  const [isMergeModalOpen, setIsMergeModalOpen] = useState(false);
  const [createModalInfo, setCreateModalInfo] = useState<{ isOpen: boolean; templateId: string | null }>({
    isOpen: false,
    templateId: null
  });
  const [lastCreatedId, setLastCreatedId] = useState<string | null>(null);

  // 批量模式状态
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const sortProjects = (projs: Project[]) => {
    return [...projs].sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'createdAt') return (b.createdAt || 0) - (a.createdAt || 0);
      return (b.lastModifiedAt || 0) - (a.lastModifiedAt || 0);
    });
  };

  useEffect(() => {
    if (projects.length > 0) {
      const latest = [...projects].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
      if (Date.now() - (latest.createdAt || 0) < 5000) {
        setLastCreatedId(latest.id);
      }
    }
  }, [projects.length]);

  const groupedData = useMemo(() => {
    const sorted = sortProjects(projects);
    if (!isGrouped) return { 'all': sorted };
    const groups: Record<string, Project[]> = {};
    sorted.forEach(p => {
      const template = templates.find(t => t.id === p.templateId);
      const groupName = template?.name || '未分类项目';
      if (!groups[groupName]) groups[groupName] = [];
      groups[groupName].push(p);
    });
    return groups;
  }, [projects, sortBy, isGrouped, templates]);

  const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const content = await ioService.readFileAsText(file);
      if (!content || content.trim() === "") {
        onRequestAlert('失败', '所选文件为空。');
        return;
      }
      const data = JSON.parse(content);
      if (data && Array.isArray(data.projects) && Array.isArray(data.templates)) {
        onImportData(data.projects, data.templates);
      } else {
        onRequestAlert('失败', '文件格式不匹配。');
      }
    } catch (err) {
      onRequestAlert('失败', '文件读取或解析 JSON 失败。');
    }
    e.target.value = '';
  };

  const toggleSelection = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const selectAll = () => {
    if (selectedIds.size === projects.length) setSelectedIds(new Set());
    else setSelectedIds(new Set(projects.map(p => p.id)));
  };

  const handleBatchDelete = () => {
    if (selectedIds.size === 0) return;
    onDeleteProjects(Array.from(selectedIds));
    setIsSelectionMode(false);
    setSelectedIds(new Set());
  };

  const renderProjectCard = (p: Project) => {
    const template = templates.find(t => t.id === p.templateId);
    const isSelected = selectedIds.has(p.id);

    return (
      <HighlightEffect key={p.id} isActive={lastCreatedId === p.id}>
        <div 
          onClick={() => isSelectionMode ? toggleSelection(p.id) : onOpenProject(p.id)} 
          className={`group bg-slate-900 hover:bg-slate-800 border transition-all relative rounded-xl p-4 cursor-pointer ${
            isSelected ? 'border-blue-500 ring-2 ring-blue-500/20 bg-slate-800' : 'border-slate-800 hover:border-blue-500/50'
          }`}
        >
          {isSelectionMode && (
            <div className={`absolute top-3 left-3 w-5 h-5 rounded border flex items-center justify-center transition-colors z-20 ${
              isSelected ? 'bg-blue-600 border-blue-500' : 'bg-slate-950 border-slate-700'
            }`}>
              {isSelected && (
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5 text-white">
                  <path fillRule="evenodd" d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" clipRule="evenodd" />
                </svg>
              )}
            </div>
          )}

          <div className={`${isSelectionMode ? 'pl-7' : ''} mb-2`}>
              <h4 className="text-base font-bold text-slate-200 group-hover:text-white mb-1 truncate">{p.name}</h4>
              <div className="flex items-center gap-2">
                <span className="text-[10px] bg-slate-950 text-slate-500 px-1.5 py-0.5 rounded border border-slate-800/50">
                  模版: {template?.name || '已失效'}
                </span>
              </div>
          </div>
          <div className="flex flex-col gap-1 border-t border-slate-800/40 mt-3 pt-3">
              <div className="flex justify-between items-center text-[9px] font-mono text-slate-600"><span>创建: {formatFullDate(p.createdAt)}</span></div>
              <div className="flex justify-between items-center text-[9px] font-mono text-blue-600/60"><span>最后修改: {formatFullDate(p.lastModifiedAt)}</span></div>
          </div>

          {!isSelectionMode && (
            <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={(e) => { e.stopPropagation(); onCreateTemplateFromProject(p.id); }} title="提取模版" className="text-slate-500 hover:text-blue-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M8 2a.75.75 0 0 1 .75.75v4.5a.75.75 0 0 1-1.5 0v-4.5A.75.75 0 0 1 8 2ZM4.25 5a.75.75 0 0 1 .75-.75h1.5a.75.75 0 0 1 0 1.5H5v6.5h6v-6.5h-1.5a.75.75 0 0 1 0-1.5h1.5A1.5 1.5 0 0 1 12.5 5.75v6.5A1.5 1.5 0 0 1 11 13.75H5a1.5 1.5 0 0 1-1.5-1.5v-6.5A1.5 1.5 0 0 1 4.25 5Z" /></svg></button>
                <button onClick={(e) => { e.stopPropagation(); onDeleteProject(p.id); }} title="彻底删除" className="text-slate-500 hover:text-red-400"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
            </div>
          )}
        </div>
      </HighlightEffect>
    );
  };

  return (
    <div className="absolute inset-0 bg-slate-950 z-50 flex flex-col animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">文件库</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">本地项目管理器</span>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 mr-4">
            <input type="file" ref={fileInputRef} onChange={handleImportFile} className="hidden" accept=".json" />
            <button onClick={() => fileInputRef.current?.click()} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">全量恢复</button>
            <button onClick={onOpenExport} className="text-[11px] text-slate-400 hover:text-white border border-slate-700 hover:border-slate-500 px-3 py-1.5 rounded">备份数据</button>
            <button onClick={() => setIsMergeModalOpen(true)} className="text-[11px] bg-blue-600/10 text-blue-400 hover:bg-blue-600 hover:text-white border border-blue-500/30 px-3 py-1.5 rounded transition-all">合并数据</button>
          </div>

        </div>
      </div>
      <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-950 relative pb-24">
         <div className="w-full grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8 flex flex-col">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-6 pb-2 border-b border-slate-800/50">
                <h3 className="text-sm font-bold text-blue-400 uppercase tracking-widest">我的项目资产</h3>
                <div className="flex flex-wrap items-center gap-4 md:gap-6">
                  {/* 批量选择开关 */}
                  <button 
                    onClick={() => { setIsSelectionMode(!isSelectionMode); setSelectedIds(new Set()); }}
                    className={`flex items-center gap-2 px-3 py-1.5 text-[10px] font-bold rounded-lg border transition-all ${
                      isSelectionMode ? 'bg-blue-600 border-blue-400 text-white shadow-lg shadow-blue-600/30' : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-600'
                    }`}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5"><path d="M12.416 3.376a.75.75 0 0 1 .208 1.04l-5 7.5a.75.75 0 0 1-1.154.114l-3-3a.75.75 0 0 1 1.06-1.06l2.353 2.353 4.493-6.74a.75.75 0 0 1 1.04-.207Z" /></svg>
                    {isSelectionMode ? '退出管理' : '批量管理'}
                  </button>

                  <div className="flex items-center gap-3">
                    <span className="text-[10px] text-slate-500 font-bold uppercase whitespace-nowrap">缩放</span>
                    <input type="range" min="150" max="500" value={cardScale} onChange={(e) => onCardScaleChange(parseInt(e.target.value))} className="w-24 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-600"/>
                  </div>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setIsGrouped(!isGrouped)} className={`flex items-center gap-2 px-3 py-1 text-[10px] font-bold rounded border transition-colors ${isGrouped ? 'bg-blue-600/20 border-blue-500/50 text-blue-400' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-slate-300'}`}><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3 h-3"><path d="M2 3.75A.75.75 0 0 1 2.75 3h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 3.75ZM2 8a.75.75 0 0 1 .75-.75h10.5a.75.75 0 0 1 0 1.5H2.75A.75.75 0 0 1 2 8Zm.75 3.5a.75.75 0 0 0 0 1.5h10.5a.75.75 0 0 0 0-1.5H2.75Z" /></svg>{isGrouped ? '已分组' : '平铺'}</button>
                  </div>
                  <div className="flex items-center gap-2">
                    <select value={sortBy} onChange={(e) => setSortBy(e.target.value as SortKey)} className="bg-slate-900 border border-slate-800 rounded px-2 py-1 text-[10px] text-slate-400 outline-none hover:border-slate-600 transition-colors"><option value="lastModified">修改时间</option><option value="createdAt">创建时间</option><option value="name">名称</option></select>
                  </div>
                </div>
            </div>
            <div className="space-y-10">
              {Object.entries(groupedData).map(([groupName, projs]) => (
                <div key={groupName} className="space-y-4">
                  {isGrouped && (<div className="flex items-center gap-3"><div className="h-4 w-1 bg-blue-500 rounded-full"></div><h4 className="text-xs font-black text-slate-500 uppercase tracking-tighter">{groupName} <span className="ml-2 text-[10px] font-normal text-slate-700">({(projs as Project[]).length} 个项目)</span></h4></div>)}
                  <div className="grid gap-4" style={{ gridTemplateColumns: `repeat(auto-fill, minmax(${cardScale}px, 1fr))` }}>{(projs as Project[]).map(p => renderProjectCard(p))}</div>
                </div>
              ))}
            </div>
          </div>
          <div className="lg:col-span-4">
             <div className="flex items-center justify-between mb-6 pb-2 border-b border-slate-800/50"><h3 className="text-sm font-bold text-emerald-400 uppercase tracking-widest">快速创建</h3><button onClick={onCreateTemplate} className="text-[10px] text-slate-500 hover:text-white transition-colors underline underline-offset-4">新建模版</button></div>
             <div className="grid grid-cols-1 gap-3">
              {templates.map(t => (
                <div key={t.id} className="bg-slate-900/50 border border-slate-800 rounded-lg p-4 transition-colors">
                  <h4 className="font-bold text-slate-200 text-sm mb-1">{t.name}</h4>
                  <div className="flex gap-2 text-[9px] text-slate-600 mb-4 font-mono"><span>{t.steps.length} STEPS</span><span>{t.inputs.length} VARS</span></div>
                  <div className="flex gap-2">
                      <Button onClick={() => setCreateModalInfo({ isOpen: true, templateId: t.id })} className="flex-1 h-8 text-[11px]" size="sm" variant="success">使用模版</Button>
                      <button onClick={() => onDuplicateTemplate(t.id)} className="px-2.5 bg-slate-950 border border-slate-800 text-slate-500 hover:text-blue-400 rounded transition-colors" title="复制模版">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5">
                          <path d="M4 4c0-1.1.9-2 2-2h4.688c.265 0 .52.105.707.293l2.312 2.312c.188.188.293.442.293.707V12c0 1.1-.9 2-2 2H6c-1.1 0-2-.9-2-2V4Z" />
                          <path d="M2.5 6A1.5 1.5 0 0 0 1 7.5v6A1.5 1.5 0 0 0 2.5 15h6A1.5 1.5 0 0 0 10 13.5V13H2.5V6Z" />
                        </svg>
                      </button>
                      <button onClick={() => onEditTemplate(t.id)} className="px-3 bg-slate-950 border border-slate-800 text-[10px] text-slate-500 hover:text-white rounded" title="编辑模版结构">编辑</button>
                      <button onClick={() => onDeleteTemplate(t.id)} className="px-2 bg-slate-950 border border-slate-800 text-slate-500 hover:text-red-400 rounded transition-colors" title="删除模版"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-3.5 h-3.5"><path fillRule="evenodd" d="M5 3.25V4H2.75a.75.75 0 0 0 0 1.5h.3l.815 8.15A1.5 1.5 0 0 0 5.357 15h5.285a1.5 1.5 0 0 0 1.493-1.35l.815-8.15h.3a.75.75 0 0 0 0-1.5H11v-.75A2.25 2.25 0 0 0 8.75 1h-1.5A2.25 2.25 0 0 0 5 3.25Zm2.25-.75a.75.75 0 0 0-.75.75V4h3v-.75a.75.75 0 0 0-.75-.75h-1.5Z" clipRule="evenodd" /></svg></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* 批量操作工具栏 */}
        {isSelectionMode && (
          <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900/80 backdrop-blur-xl border border-slate-700 rounded-2xl px-6 py-4 flex items-center gap-6 shadow-2xl z-[60] animate-in slide-in-from-bottom-4 duration-300 ring-1 ring-white/5">
              <div className="flex flex-col pr-6 border-r border-slate-800">
                <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest">已选择</span>
                <span className="text-xl font-black text-blue-400">{selectedIds.size}</span>
              </div>
              <div className="flex gap-3">
                <Button variant="ghost" size="sm" onClick={selectAll} className="text-slate-300 hover:bg-slate-800">
                  {selectedIds.size === projects.length ? '取消全选' : '全选所有'}
                </Button>
                <Button variant="danger" size="sm" onClick={handleBatchDelete} disabled={selectedIds.size === 0} className="shadow-lg shadow-red-500/20 px-6 font-bold">
                  批量删除
                </Button>
                <button onClick={() => setIsSelectionMode(false)} className="text-[11px] text-slate-500 hover:text-white px-2">取消</button>
              </div>
          </div>
        )}
      </div>
      <CreateProjectModal isOpen={createModalInfo.isOpen} onConfirm={(name) => { if (createModalInfo.templateId) { onCreateProject(createModalInfo.templateId, name); setCreateModalInfo({ isOpen: false, templateId: null }); } }} onCancel={() => setCreateModalInfo({ isOpen: false, templateId: null })} />
      <MergeModal 
        isOpen={isMergeModalOpen} 
        onClose={() => setIsMergeModalOpen(false)} 
        currentProjects={projects} 
        currentTemplates={templates} 
        onConfirmMerge={onMergeData}
        onRequestAlert={onRequestAlert}
      />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Project, Template, TemplateInput } from './types';
import { DEFAULT_TEMPLATES } from './constants';
import { ProjectRunner } from './components/ProjectRunner';
import { TemplateEditor } from './components/TemplateEditor';
import { FileLibrary } from './components/FileLibrary';
import { ConfirmationModal } from './components/ConfirmationModal';
import { ExportModal } from './components/ExportModal';
import { SettingsModal } from './components/SettingsModal';
import { Sidebar } from './components/Sidebar';
import { TopNav } from './components/TopNav';
import { ioService, STORAGE_KEYS } from './services/ioService';

type FontSize = 'text-xs' | 'text-sm' | 'text-base';
type UiScale = 8 | 11 | 14 | 16 | 18 | 19 | 20 | 22 | 24;

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [openTabIds, setOpenTabIds] = useState<string[]>([]);
  const [activeTabId, setActiveTabId] = useState<string | null>('library');
  const [editingTemplateId, setEditingTemplateId] = useState<string | null>(null);
  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [fontSize, setFontSize] = useState<FontSize>('text-sm');
  const [uiScale, setUiScale] = useState<UiScale>(16);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [sidebarWidth, setSidebarWidth] = useState(300);
  const [isRightPanelOpen, setIsRightPanelOpen] = useState(true);
  const [rightPanelWidth, setRightPanelWidth] = useState(400);
  const [isResizingSidebar, setIsResizingSidebar] = useState(false);
  const [cardScale, setCardScale] = useState<number>(300);

  const [modalConfig, setModalConfig] = useState<{
    isOpen: boolean; title: string; message: string; isAlert: boolean; onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', isAlert: false, onConfirm: () => {} });

  const openConfirm = (title: string, message: string, onConfirm: () => void) => {
    setModalConfig({ isOpen: true, title, message, isAlert: false, onConfirm: () => { onConfirm(); closeModal(); } });
  };
  const openAlert = (title: string, message: string) => {
    setModalConfig({ isOpen: true, title, message, isAlert: true, onConfirm: () => closeModal() });
  };
  const closeModal = () => setModalConfig(prev => ({ ...prev, isOpen: false }));

  // 初始化加载
  useEffect(() => {
    const init = async () => {
      const lp = await ioService.loadFromDisk<Project[]>(STORAGE_KEYS.PROJECTS);
      if (lp) setProjects(lp.map(p => ({ ...p, customInputs: p.customInputs || [] })));
      const lt = await ioService.loadFromDisk<Template[]>(STORAGE_KEYS.TEMPLATES);
      setTemplates(lt || DEFAULT_TEMPLATES);
      const settings = await ioService.loadFromDisk<any>(STORAGE_KEYS.SETTINGS);
      if (settings) {
        if (settings.uiScale) setUiScale(settings.uiScale);
        if (settings.sidebarWidth) setSidebarWidth(settings.sidebarWidth);
        if (settings.isSidebarOpen !== undefined) setIsSidebarOpen(settings.isSidebarOpen);
        if (settings.fontSize) setFontSize(settings.fontSize);
        if (settings.rightPanelWidth) setRightPanelWidth(settings.rightPanelWidth);
        if (settings.cardScale) setCardScale(settings.cardScale);
      }
    };
    init();
  }, []);

  // 持久化保存
  useEffect(() => { if(templates.length > 0) ioService.saveToDisk(STORAGE_KEYS.TEMPLATES, templates); }, [templates]);
  useEffect(() => { if(projects.length > 0) ioService.saveToDisk(STORAGE_KEYS.PROJECTS, projects); }, [projects]);
  useEffect(() => {
    ioService.saveToDisk(STORAGE_KEYS.SETTINGS, { uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize, cardScale });
    document.documentElement.style.fontSize = `${uiScale}px`;
  }, [uiScale, sidebarWidth, isSidebarOpen, rightPanelWidth, isRightPanelOpen, fontSize, cardScale]);

  // 侧边栏宽度调整监听
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isResizingSidebar) return;
      const newWidth = e.clientX;
      if (newWidth > 180 && newWidth < 600) setSidebarWidth(newWidth);
    };
    const handleMouseUp = () => { setIsResizingSidebar(false); document.body.style.cursor = 'default'; };
    if (isResizingSidebar) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'col-resize';
    }
    return () => { window.removeEventListener('mousemove', handleMouseMove); window.removeEventListener('mouseup', handleMouseUp); };
  }, [isResizingSidebar]);

  const createProject = (templateId: string, name: string) => {
    const template = templates.find(t => t.id === templateId);
    if (!template) return;
    const now = Date.now();
    const newProject: Project = { 
        id: `proj_${now}`, templateId, name: name || `新项目`, createdAt: now, lastModifiedAt: now, lastOpenedAt: now,
        inputValues: {}, customInputs: [], stepOutputs: {}, stepOverrides: {} 
    };
    setProjects(prev => [...prev, newProject]);
    openTab(newProject.id);
  };

  const createTemplate = () => {
    const now = Date.now();
    const newId = `tmpl_${now}`;
    const newTemplate: Template = {
      id: newId,
      name: `新模版`,
      inputs: [{ id: `input_${now}_0`, label: '核心变量' }],
      steps: [{ id: `step_${now}_0`, name: '步骤1', content: '在此处输入模板内容...' }]
    };
    setTemplates(prev => [...prev, newTemplate]);
    setEditingTemplateId(newId);
  };

  const openTab = (id: string) => { 
    if (id === 'library') { setActiveTabId('library'); return; }
    setOpenTabIds(prev => prev.includes(id) ? prev : [...prev, id]); 
    setActiveTabId(id); 
  };

  const closeTab = (id: string, e?: React.MouseEvent) => {
    e?.stopPropagation();
    setOpenTabIds(prev => {
        const next = prev.filter(tid => tid !== id);
        if (activeTabId === id) setActiveTabId(next.length > 0 ? next[next.length - 1] : 'library');
        return next;
    });
  };

  const handleInputChange = (inputId: string, value: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { ...p, lastModifiedAt: Date.now(), inputValues: { ...p.inputValues, [inputId]: value } } : p));
  };

  const handleAddLocalVariable = (name: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    const newInput: TemplateInput = { id: `local_${Date.now()}`, label: name };
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: [...(p.customInputs || []), newInput] 
    } : p));
  };

  const handleDeleteLocalVariable = (varId: string) => {
    if (!activeTabId || activeTabId === 'library') return;
    setProjects(prev => prev.map(p => p.id === activeTabId ? { 
      ...p, 
      lastModifiedAt: Date.now(), 
      customInputs: (p.customInputs || []).filter(i => i.id !== varId) 
    } : p));
  };

  const handleBakeDownload = () => {
    const project = projects.find(p => p.id === activeTabId);
    if (!project) return;
    const template = templates.find(t => t.id === project.templateId);
    if (!template) return;

    const interpolate = (templateStr: string): string => {
        if (!templateStr) return "";
        let result = templateStr;
        template.inputs.forEach((input, index) => {
          const val = project.inputValues[input.id] || "";
          result = result.split(`<${index}>`).join(val);
          result = result.split(`<${input.label}>`).join(val);
        });
        (project.customInputs || []).forEach((input, index) => {
           const val = project.inputValues[input.id] || "";
           result = result.split(`<l${index + 1}>`).join(val);
           result = result.split(`<${input.label}>`).join(val);
        });
        return result;
    };

    let fullText = `项目：${project.name}\n导出时间：${new Date().toLocaleString()}\n\n`;
    template.steps.forEach((step) => {
       const override = project.stepOverrides[step.id];
       const rawContent = override?.content !== undefined ? override.content : (step.content || "");
       fullText += `### ${step.name}\n${interpolate(rawContent)}\n\n`;
    });
    ioService.exportFile(`${project.name}_烘焙结果.txt`, fullText);
  };

  const handleDownloadAllData = () => {
    const backupData = {
      projects,
      templates,
      exportDate: new Date().toISOString(),
      version: "2.0"
    };
    const jsonString = JSON.stringify(backupData, null, 2);
    const dateStr = new Date().toISOString().split('T')[0];
    ioService.exportFile(`prompt_splicer_backup_${dateStr}.json`, jsonString, 'application/json');
  };

  const handleMergeData = (newProjects: Project[], newTemplates: Template[]) => {
    // 处理合并逻辑
    setTemplates(prev => {
      const merged = [...prev];
      newTemplates.forEach(nt => {
        const idx = merged.findIndex(t => t.id === nt.id);
        if (idx !== -1) merged[idx] = nt; // 覆盖已有的ID（如果是overwrite操作）
        else merged.push(nt); // 否则新增
      });
      return merged;
    });

    setProjects(prev => {
      const merged = [...prev];
      newProjects.forEach(np => {
        const idx = merged.findIndex(p => p.id === np.id);
        if (idx !== -1) merged[idx] = np;
        else merged.push(np);
      });
      return merged;
    });
  };

  const editingTemplate = templates.find(t => t.id === editingTemplateId);
  const activeProject = activeTabId !== 'library' ? projects.find(p => p.id === activeTabId) : null;
  const activeProjectTemplate = activeProject ? templates.find(t => t.id === activeProject.templateId) : null;

  return (
    <div className={`flex flex-col h-screen overflow-hidden text-slate-200 font-sans ${fontSize} app-root`}>
      {/* 全屏模板编辑器覆盖层 */}
      {editingTemplateId && editingTemplate && (
        <div className="fixed inset-0 bg-slate-950 z-[100] animate-in fade-in zoom-in-95 duration-200">
           <TemplateEditor 
              template={editingTemplate} 
              onSave={(u) => { setTemplates(prev => prev.map(t => t.id === u.id ? u : t)); setEditingTemplateId(null); }} 
              onCancel={() => setEditingTemplateId(null)} 
              onRequestConfirm={openConfirm} 
           />
        </div>
      )}

      {/* 顶部导航组件 */}
      <TopNav 
        isSidebarOpen={isSidebarOpen}
        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
        onOpenSettings={() => setIsSettingsOpen(true)}
        activeTabId={activeTabId}
        openTabIds={openTabIds}
        projects={projects}
        onOpenTab={openTab}
        onCloseTab={closeTab}
      />

      <div className="flex-1 flex overflow-hidden relative">
        {/* 侧边栏组件 */}
        <Sidebar 
          isOpen={isSidebarOpen}
          width={sidebarWidth}
          onWidthChange={setSidebarWidth}
          isResizing={isResizingSidebar}
          onResizingChange={setIsResizingSidebar}
          activeProject={activeProject || null}
          activeProjectTemplate={activeProjectTemplate || null}
          onInputChange={handleInputChange}
          onAddLocalVariable={handleAddLocalVariable}
          onDeleteLocalVariable={handleDeleteLocalVariable}
          onBakeDownload={handleBakeDownload}
          onRequestAlert={openAlert}
        />

        {/* 主内容区域 */}
        <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden relative">
           {activeTabId === 'library' ? (
             <FileLibrary 
                projects={projects} 
                templates={templates} 
                onOpenProject={openTab} 
                onCreateProject={createProject} 
                onCreateTemplate={createTemplate} 
                onEditTemplate={setEditingTemplateId} 
                onDuplicateTemplate={(id) => { const t = templates.find(x => x.id === id); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: t.name+' (副本)'}]); setEditingTemplateId(nid); } }} 
                onCreateTemplateFromProject={(id) => { const p = projects.find(x => x.id === id); const t = templates.find(x => x.id === p?.templateId); if(t) { const nid = `tmpl_${Date.now()}`; setTemplates([...templates, {...t, id: nid, name: p?.name+' 提取'}]); setEditingTemplateId(nid); } }} 
                onDeleteProject={(id) => openConfirm("删除项目", "确定删除？", () => { setProjects(projects.filter(p => p.id !== id)); closeTab(id); })} 
                onDeleteProjects={(ids) => openConfirm("批量删除", "确定删除？", () => { setProjects(projects.filter(p => !ids.includes(p.id))); ids.forEach(id => closeTab(id)); })}
                onDeleteTemplate={(id) => openConfirm("删除模版", "确定删除？", () => setTemplates(templates.filter(t => t.id !== id)))} 
                onImportData={(p, t) => { setProjects(p); setTemplates(t); }} 
                onMergeData={handleMergeData}
                onOpenExport={() => setIsExportModalOpen(true)} 
                onRequestAlert={openAlert} 
                cardScale={cardScale}
                onCardScaleChange={setCardScale}
             />
           ) : activeProject && activeProjectTemplate ? (
             <ProjectRunner 
                project={activeProject} 
                template={activeProjectTemplate} 
                onUpdateProject={(id, u) => setProjects(prev => prev.map(p => p.id === id ? { ...p, ...u, lastModifiedAt: Date.now() } : p))} 
                onUpdateTemplate={(id, u) => setTemplates(prev => prev.map(t => t.id === id ? { ...t, ...u } : t))} 
                onRequestConfirm={openConfirm} 
                rightPanelWidth={rightPanelWidth} 
                onRightPanelWidthChange={setRightPanelWidth} 
                isRightPanelOpen={isRightPanelOpen} 
                onRightPanelOpenChange={setIsRightPanelOpen} 
             />
           ) : <div className="flex items-center justify-center h-full text-slate-700">请从文件库打开项目</div>}
        </div>
      </div>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} uiScale={uiScale} setUiScale={setUiScale} fontSize={fontSize} setFontSize={setFontSize} />
      <ExportModal isOpen={isExportModalOpen} onClose={() => setIsExportModalOpen(false)} data={{ projects, templates }} onDownload={handleDownloadAllData} />
      <ConfirmationModal isOpen={modalConfig.isOpen} title={modalConfig.title} message={modalConfig.message} isAlert={modalConfig.isAlert} onConfirm={modalConfig.onConfirm} onCancel={closeModal} />
    </div>
  );
};

