import React, { useState, useEffect, useRef } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { ioService } from '../services/ioService';

interface MergeModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentProjects: Project[];
  currentTemplates: Template[];
  onConfirmMerge: (projects: Project[], templates: Template[]) => void;
  onRequestAlert: (title: string, message: string) => void;
}

interface MergeItem<T> {
  data: T;
  status: 'new' | 'conflict' | 'identical';
  action: 'import' | 'skip' | 'overwrite';
  newName: string;
}

export const MergeModal: React.FC<MergeModalProps> = ({
  isOpen,
  onClose,
  currentProjects,
  currentTemplates,
  onConfirmMerge,
  onRequestAlert
}) => {
  const [importedData, setImportedData] = useState<{ projects: Project[]; templates: Template[] } | null>(null);
  const [projectQueue, setProjectQueue] = useState<MergeItem<Project>[]>([]);
  const [templateQueue, setTemplateQueue] = useState<MergeItem<Template>[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  // 动态检测是否在 Tauri 环境中
  const IS_TAURI = typeof window !== 'undefined' && (window as any).__TAURI_INTERNALS__ !== undefined;

  const handleTriggerFileSelect = () => {
    if (IS_TAURI) {
      // Tauri 环境下 ioService.readFileAsText 会直接弹出对话框
      handleFileRead();
    } else {
      // 浏览器环境下触发隐藏的 input 元素
      fileInputRef.current?.click();
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    await handleFileRead(file);
    e.target.value = ''; // 清空以支持重复选择同名文件
  };

  const handleFileRead = async (file?: File) => {
    try {
      const content = await ioService.readFileAsText(file);
      if (!content) return;
      const data = JSON.parse(content);
      if (!data.projects || !data.templates) {
        onRequestAlert('格式错误', '该文件不是有效的备份文件。');
        return;
      }
      analyzeData(data.projects, data.templates);
      setImportedData(data);
    } catch (e) {
      console.error('Merge read error:', e);
      onRequestAlert('解析失败', '无法读取或解析该 JSON 文件。');
    }
  };

  const analyzeData = (newProjs: Project[], newTmpls: Template[]) => {
    // 分析模板
    const tQueue: MergeItem<Template>[] = newTmpls.map(nt => {
      const existing = currentTemplates.find(t => t.name === nt.name);
      if (!existing) return { data: nt, status: 'new', action: 'import', newName: nt.name };
      // 简单判断是否完全一致 (忽略ID)
      const isIdentical = JSON.stringify({ ...nt, id: '' }) === JSON.stringify({ ...existing, id: '' });
      return { 
        data: nt, 
        status: isIdentical ? 'identical' : 'conflict', 
        action: isIdentical ? 'skip' : 'skip', 
        newName: nt.name + '_copy' 
      };
    });

    // 分析项目
    const pQueue: MergeItem<Project>[] = newProjs.map(np => {
      const existing = currentProjects.find(p => p.name === np.name);
      if (!existing) return { data: np, status: 'new', action: 'import', newName: np.name };
      const isIdentical = JSON.stringify({ ...np, id: '', lastModifiedAt: 0 }) === JSON.stringify({ ...existing, id: '', lastModifiedAt: 0 });
      return { 
        data: np, 
        status: isIdentical ? 'identical' : 'conflict', 
        action: isIdentical ? 'skip' : 'skip', 
        newName: np.name + '_copy' 
      };
    });

    setTemplateQueue(tQueue);
    setProjectQueue(pQueue);
  };

  const handleConfirm = () => {
    const finalTemplates = templateQueue
      .filter(item => item.action !== 'skip')
      .map(item => {
        if (item.action === 'overwrite') {
          const existing = currentTemplates.find(t => t.name === item.data.name);
          return { ...item.data, id: existing?.id || item.data.id };
        }
        return { ...item.data, name: item.newName, id: `tmpl_merge_${Date.now()}_${Math.random()}` };
      });

    const finalProjects = projectQueue
      .filter(item => item.action !== 'skip')
      .map(item => {
        if (item.action === 'overwrite') {
          const existing = currentProjects.find(p => p.name === item.data.name);
          return { ...item.data, id: existing?.id || item.data.id };
        }
        return { ...item.data, name: item.newName, id: `proj_merge_${Date.now()}_${Math.random()}` };
      });

    onConfirmMerge(finalProjects, finalTemplates);
    onClose();
  };

  const renderList = (title: string, items: MergeItem<any>[], setItems: React.Dispatch<React.SetStateAction<MergeItem<any>[]>>) => (
    <div className="flex-1 flex flex-col min-w-0">
