              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold uppercase ${
                    item.status === 'conflict' ? 'bg-amber-500/20 text-amber-500' : 
                    item.status === 'identical' ? 'bg-slate-800 text-slate-500' : 
                    'bg-emerald-500/20 text-emerald-500'
                  }`}>
                    {item.status === 'conflict' ? '冲突' : item.status === 'identical' ? '存在' : '新增'}
                  </span>
                  <span className="text-xs font-bold text-slate-200 truncate">{item.data.name}</span>
                </div>
                {item.action === 'import' && item.status === 'conflict' && (
                  <input 
                    className="w-full bg-slate-950 border border-slate-800 rounded px-2 py-1 text-[11px] text-blue-400 mt-1 outline-none focus:border-blue-500"
                    value={item.newName}
                    onChange={(e) => {
                      const next = [...items];
                      next[idx].newName = e.target.value;
                      setItems(next);
                    }}
                    placeholder="新名称..."
                  />
                )}
              </div>
              <div className="flex flex-col gap-1 shrink-0">
                <select 
                  className="bg-slate-950 border border-slate-800 text-[10px] rounded px-1.5 py-1 text-slate-400 outline-none"
                  value={item.action}
                  onChange={(e) => {
                    const next = [...items];
                    next[idx].action = e.target.value as any;
                    setItems(next);
                  }}
                >
                  <option value="skip">跳过</option>
                  <option value="import">{item.status === 'conflict' ? '作为新项导入' : '导入'}</option>
                  {item.status === 'conflict' && <option value="overwrite">覆盖现有</option>}
                </select>
              </div>
            </div>
          </div>
        ))}
        {items.length === 0 && <div className="text-center py-10 text-slate-700 text-xs italic">无数据</div>}
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[110] flex flex-col bg-slate-950 animate-in fade-in duration-200">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">数据合并面板</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">对比并增量导入项目和模版</span>
        </div>
        <div className="flex items-center gap-3">
          {!importedData ? (
            <Button variant="primary" onClick={handleSelectFile} size="sm">选择备份文件 (.json)</Button>
          ) : (
            <>
              <Button variant="ghost" onClick={() => setImportedData(null)} size="sm">重新选择</Button>
              <Button variant="success" onClick={handleConfirm} size="sm" className="px-8 font-black">确认合并执行</Button>
            </>
          )}
          <button onClick={onClose} className="text-slate-400 hover:text-white p-2 rounded-full hover:bg-slate-800 transition-colors ml-4">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-hidden p-8 flex flex-col">
        {!importedData ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6">
            <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center border border-slate-800 shadow-2xl">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-10 h-10 text-blue-500"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg>
            </div>
            <div className="max-w-md">
              <h3 className="text-lg font-bold text-white mb-2">准备合并数据</h3>
              <p className="text-sm text-slate-500 leading-relaxed">点击上方按钮选择一个备份 JSON 文件。我们将自动检测名称冲突，您可以手动决定是覆盖、并存还是忽略。</p>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex gap-8 min-h-0">
            {renderList("待处理模版", templateQueue as any, setTemplateQueue as any)}
            <div className="w-[1px] bg-slate-800 shrink-0 self-stretch my-10"></div>
            {renderList("待处理项目", projectQueue as any, setProjectQueue as any)}
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-900/50 border-t border-slate-800 flex justify-center gap-10">
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">新增项</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-amber-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">名称冲突</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-slate-700"></div><span className="text-[10px] text-slate-500 font-bold uppercase">完全相同</span></div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Project, Template } from '../types';
import { Button } from './Button';
import { ioService } from '../services/ioService';

interface MergeModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentProjects: Project[];
  currentTemplates: Template[];
  onConfirmMerge: (projects: Project[], templates: Template[]) => void;
  onRequestAlert: (title: string, message: string) => void;
}

interface MergeItem<T> {
  id: string; // 使用随机生成的临时 ID 追踪
  originalData: T;
  type: 'project' | 'template';
  status: 'new' | 'conflict' | 'identical';
  action: 'import' | 'overwrite';
  newName: string;
}

export const MergeModal: React.FC<MergeModalProps> = ({
  isOpen,
  onClose,
  currentProjects,
  currentTemplates,
  onConfirmMerge,
  onRequestAlert
}) => {
  const [importedData, setImportedData] = useState<{ projects: Project[]; templates: Template[] } | null>(null);
  const [inventory, setInventory] = useState<MergeItem<any>[]>([]);
  const [queue, setQueue] = useState<MergeItem<any>[]>([]);
  const [previewItem, setPreviewItem] = useState<any | null>(null);

  if (!isOpen) return null;

  const handleSelectFile = async () => {
    try {
      const content = await ioService.selectAndReadFile();
      if (!content) return;
      const data = JSON.parse(content);
      if (!data.projects || !data.templates) {
        onRequestAlert('格式错误', '该文件不是有效的备份文件。');
        return;
      }

      const analyzedInventory: MergeItem<any>[] = [
        ...data.templates.map((t: Template) => {
          const existing = currentTemplates.find(ct => ct.name === t.name);
          const isIdentical = existing ? JSON.stringify({ ...t, id: '' }) === JSON.stringify({ ...existing, id: '' }) : false;
          return {
            id: `merge_t_${Math.random()}`,
            originalData: t,
            type: 'template',
            status: existing ? (isIdentical ? 'identical' : 'conflict') : 'new',
            action: 'import',
            newName: t.name + (existing ? '_copy' : '')
          };
        }),
        ...data.projects.map((p: Project) => {
          const existing = currentProjects.find(cp => cp.name === p.name);
          const isIdentical = existing ? JSON.stringify({ ...p, id: '', lastModifiedAt: 0 }) === JSON.stringify({ ...existing, id: '', lastModifiedAt: 0 }) : false;
          return {
            id: `merge_p_${Math.random()}`,
            originalData: p,
            type: 'project',
            status: existing ? (isIdentical ? 'identical' : 'conflict') : 'new',
            action: 'import',
            newName: p.name + (existing ? '_copy' : '')
          };
        })
      ];

      setInventory(analyzedInventory);
      setQueue([]);
      setImportedData(data);
    } catch (e) {
      onRequestAlert('解析失败', '无法读取或解析该 JSON 文件。');
    }
  };

  const addToQueue = (id: string) => {
    const item = inventory.find(i => i.id === id);
    if (!item) return;
    setInventory(inventory.filter(i => i.id !== id));
    setQueue([...queue, item]);
  };

  const removeFromQueue = (id: string) => {
    const item = queue.find(i => i.id === id);
    if (!item) return;
    setQueue(queue.filter(i => i.id !== id));
    setInventory([...inventory, item]);
  };

  const handleConfirm = () => {
    const finalTemplates = queue
      .filter(i => i.type === 'template')
      .map(item => {
        if (item.action === 'overwrite') {
          const existing = currentTemplates.find(t => t.name === item.originalData.name);
          return { ...item.originalData, id: existing?.id || item.originalData.id };
        }
        return { ...item.originalData, name: item.newName, id: `tmpl_m_${Date.now()}_${Math.random()}` };
      });

    const finalProjects = queue
      .filter(i => i.type === 'project')
      .map(item => {
        if (item.action === 'overwrite') {
          const existing = currentProjects.find(p => p.name === item.originalData.name);
          return { ...item.originalData, id: existing?.id || item.originalData.id };
        }
        return { ...item.originalData, name: item.newName, id: `proj_m_${Date.now()}_${Math.random()}` };
      });

    onConfirmMerge(finalProjects, finalTemplates);
    onClose();
  };

  const renderItem = (item: MergeItem<any>, isQueue: boolean) => {
    return (
      <div key={item.id} className={`p-3 rounded-xl border transition-all ${
        item.status === 'conflict' ? 'bg-amber-500/5 border-amber-500/20' : 
        item.status === 'identical' ? 'bg-slate-900/50 border-slate-800' : 
        'bg-emerald-500/5 border-emerald-500/20'
      }`}>
        <div className="flex justify-between items-start gap-3">
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2 mb-1">
              <span className={`text-[8px] px-1.5 py-0.5 rounded font-black uppercase ${
                item.type === 'template' ? 'bg-blue-600/20 text-blue-400' : 'bg-purple-600/20 text-purple-400'
              }`}>
                {item.type === 'template' ? '模版' : '项目'}
              </span>
              <span className="text-xs font-bold text-slate-200 truncate">{item.originalData.name}</span>
            </div>

            {isQueue && item.action === 'import' && item.status === 'conflict' && (
              <div className="mt-2 space-y-1">
                 <label className="text-[9px] text-slate-600 font-bold uppercase block">重命名存为新项</label>
                 <input 
                  className="w-full bg-slate-950 border border-slate-800 rounded px-2 py-1 text-[11px] text-blue-400 outline-none focus:border-blue-500"
                  value={item.newName}
                  onChange={(e) => {
                    setQueue(queue.map(i => i.id === item.id ? { ...i, newName: e.target.value } : i));
                  }}
                />
              </div>
            )}

            {isQueue && item.status === 'conflict' && (
               <div className="flex gap-2 mt-2">
                 <button 
                  onClick={() => setQueue(queue.map(i => i.id === item.id ? { ...i, action: 'import' } : i))}
                  className={`text-[9px] px-2 py-1 rounded border transition-all font-bold ${item.action === 'import' ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-500'}`}
                 >
                   存为副本
                 </button>
                 <button 
                  onClick={() => setQueue(queue.map(i => i.id === item.id ? { ...i, action: 'overwrite' } : i))}
                  className={`text-[9px] px-2 py-1 rounded border transition-all font-bold ${item.action === 'overwrite' ? 'bg-amber-600 border-amber-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-500'}`}
                 >
                   覆盖现有
                 </button>
               </div>
            )}
          </div>

          <div className="flex items-center gap-1 shrink-0">
            <button 
              onClick={() => setPreviewItem(item.originalData)}
              className="p-1.5 text-slate-500 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
              title="查看详情"
            >
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4"><path d="M8 9.5a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Z" /><path fillRule="evenodd" d="M1.38 8.28a.87.87 0 0 1 0-.56 6.33 6.33 0 0 1 13.24 0 .87.87 0 0 1 0 .56 6.33 6.33 0 0 1-13.24 0ZM8 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z" clipRule="evenodd" /></svg>
            </button>
            {isQueue ? (
              <button 
                onClick={() => removeFromQueue(item.id)}
                className="p-1.5 text-slate-500 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                title="移回待选"
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4"><path d="M3.75 7.25a.75.75 0 0 0 0 1.5h8.5a.75.75 0 0 0 0-1.5h-8.5Z" /></svg>
              </button>
            ) : (
              <button 
                onClick={() => addToQueue(item.id)}
                className="p-1.5 text-slate-500 hover:text-emerald-400 hover:bg-emerald-500/10 rounded-lg transition-colors"
                title="加入合并队列"
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4"><path d="M8.75 3.75a.75.75 0 0 0-1.5 0v3.5h-3.5a.75.75 0 0 0 0 1.5h3.5v3.5a.75.75 0 0 0 1.5 0v-3.5h3.5a.75.75 0 0 0 0-1.5h-3.5v-3.5Z" /></svg>
              </button>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[110] flex flex-col bg-slate-950 animate-in fade-in duration-200">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">数据合并工作台</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">精细化控制增量导入内容</span>
        </div>
        <div className="flex items-center gap-3">
          {!importedData ? (
            <Button variant="primary" onClick={handleSelectFile} size="sm">选择备份文件 (.json)</Button>
          ) : (
            <>
              <Button variant="ghost" onClick={() => setImportedData(null)} size="sm">重新选择文件</Button>
              <Button variant="success" onClick={handleConfirm} size="sm" className="px-8 font-black shadow-lg shadow-emerald-500/20" disabled={queue.length === 0}>
                执行合并 ({queue.length})
              </Button>
            </>
          )}
          <button onClick={onClose} className="text-slate-400 hover:text-white p-2 rounded-full hover:bg-slate-800 transition-colors ml-4">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-hidden p-8 flex flex-col">
        {!importedData ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6">
            <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center border border-slate-800 shadow-2xl">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-10 h-10 text-blue-500"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg>
            </div>
            <div className="max-w-md">
              <h3 className="text-lg font-bold text-white mb-2">载入外部数据以开始</h3>
              <p className="text-sm text-slate-500 leading-relaxed">我们将扫描文件中的所有模版和项目，并与您当前的本地库进行智能比对。您可以手动挑选需要合并的项。</p>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex gap-12 min-h-0">
            {/* 左侧：仓库待选区 */}
            <div className="flex-1 flex flex-col min-w-0">
              <div className="flex items-center justify-between mb-6 px-2">
                 <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">外部文件仓库 ({inventory.length})</h4>
                 <button onClick={() => { setQueue([...queue, ...inventory]); setInventory([]); }} className="text-[10px] text-blue-400 hover:underline">全选</button>
              </div>
              <div className="flex-1 overflow-y-auto space-y-3 pr-4 custom-scrollbar">
                {inventory.map(item => renderItem(item, false))}
                {inventory.length === 0 && (
                  <div className="flex flex-col items-center justify-center py-20 border-2 border-dashed border-slate-900 rounded-2xl opacity-40">
                    <span className="text-xs italic text-slate-600">所有项已在合并队列或已过滤</span>
                  </div>
                )}
              </div>
            </div>

            <div className="w-[1px] bg-slate-800 shrink-0 self-stretch my-10 relative">
               <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-slate-950 p-2">
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4 text-slate-700"><path fillRule="evenodd" d="M12.72 3.22a.75.75 0 0 1 1.06 1.06l-4.25 4.25a.75.75 0 0 1-1.06 0L4.22 4.28a.75.75 0 0 1 1.06-1.06L8 5.94l4.72-2.72ZM12.72 8.22a.75.75 0 0 1 1.06 1.06l-4.25 4.25a.75.75 0 0 1-1.06 0L4.22 9.28a.75.75 0 0 1 1.06-1.06L8 10.94l4.72-2.72Z" clipRule="evenodd" /></svg>
               </div>
            </div>

            {/* 右侧：合并队列 */}
            <div className="flex-1 flex flex-col min-w-0">
              <div className="flex items-center justify-between mb-6 px-2">
                 <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-widest">待合并执行队列 ({queue.length})</h4>
                 <button onClick={() => { setInventory([...inventory, ...queue]); setQueue([]); }} className="text-[10px] text-slate-600 hover:text-white">清空队列</button>
              </div>
              <div className="flex-1 overflow-y-auto space-y-3 pr-4 custom-scrollbar">
                {queue.map(item => renderItem(item, true))}
                {queue.length === 0 && (
                  <div className="flex flex-col items-center justify-center py-20 border-2 border-dashed border-slate-900 rounded-2xl text-center p-6">
                    <div className="w-10 h-10 rounded-full border border-slate-800 flex items-center justify-center mb-3 text-slate-800 font-black">+</div>
                    <p className="text-[10px] text-slate-700 font-bold uppercase tracking-tight">队列为空，请点击左侧 “+” 添加项</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* 预览遮罩层 */}
      {previewItem && (
        <div className="fixed inset-0 z-[120] bg-black/80 backdrop-blur-md flex items-center justify-center p-12" onClick={() => setPreviewItem(null)}>
           <div className="bg-slate-900 border border-slate-800 rounded-3xl w-full max-w-2xl max-h-[80vh] flex flex-col shadow-2xl overflow-hidden" onClick={e => e.stopPropagation()}>
              <div className="p-6 border-b border-slate-800 flex justify-between items-center shrink-0">
                 <h3 className="font-bold text-white tracking-tight">数据详情预览 (只读)</h3>
                 <button onClick={() => setPreviewItem(null)} className="text-slate-500 hover:text-white">✕</button>
              </div>
              <div className="flex-1 overflow-auto p-6">
                 <pre className="text-[10px] font-mono text-slate-400 bg-slate-950 p-6 rounded-xl border border-slate-800">
                    {JSON.stringify(previewItem, null, 2)}
                 </pre>
              </div>
              <div className="p-6 bg-slate-950/50 flex justify-center shrink-0">
                 <Button variant="secondary" size="sm" onClick={() => setPreviewItem(null)}>关闭预览</Button>
              </div>
           </div>
        </div>
      )}

      <div className="p-4 bg-slate-900/50 border-t border-slate-800 flex justify-center gap-10">
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">无冲突新增</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-amber-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">名称冲突</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-slate-700"></div><span className="text-[10px] text-slate-500 font-bold uppercase">数据完全相同</span></div>
      </div>
    </div>
  );
};

import React from 'react';
import { Button } from './Button';

