                    <p className="text-[10px] text-slate-700 font-bold uppercase tracking-tight">队列为空，请点击左侧 “+” 添加项</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* 预览覆盖层 */}
      <DataPreviewOverlay 
        isOpen={!!previewItem} 
        onClose={() => setPreviewItem(null)} 
        data={previewItem} 
      />

      <div className="p-4 bg-slate-900/50 border-t border-slate-800 flex justify-center gap-10">
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">无冲突新增</span></div>
