                 <button 
                  onClick={() => setQueue(queue.map(i => i.id === item.id ? { ...i, action: 'overwrite' } : i))}
                  className={`text-[9px] px-2 py-1 rounded border transition-all font-bold ${item.action === 'overwrite' ? 'bg-amber-600 border-amber-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-500'}`}
                 >
                   覆盖现有
                 </button>
               </div>
            )}
          </div>

          <div className="flex items-center gap-1 shrink-0">
            <button 
              onClick={() => setPreviewItem(item.originalData)}
              className="p-1.5 text-slate-500 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
              title="查看详情"
            >
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4"><path d="M8 9.5a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Z" /><path fillRule="evenodd" d="M1.38 8.28a.87.87 0 0 1 0-.56 6.33 6.33 0 0 1 13.24 0 .87.87 0 0 1 0 .56 6.33 6.33 0 0 1-13.24 0ZM8 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z" clipRule="evenodd" /></svg>
            </button>
            {isQueue ? (
              <button 
                onClick={() => removeFromQueue(item.id)}
                className="p-1.5 text-slate-500 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                title="移回待选"
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4"><path d="M3.75 7.25a.75.75 0 0 0 0 1.5h8.5a.75.75 0 0 0 0-1.5h-8.5Z" /></svg>
              </button>
            ) : (
              <button 
                onClick={() => addToQueue(item.id)}
                className="p-1.5 text-slate-500 hover:text-emerald-400 hover:bg-emerald-500/10 rounded-lg transition-colors"
                title="加入合并队列"
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4"><path d="M8.75 3.75a.75.75 0 0 0-1.5 0v3.5h-3.5a.75.75 0 0 0 0 1.5h3.5v3.5a.75.75 0 0 0 1.5 0v-3.5h3.5a.75.75 0 0 0 0-1.5h-3.5v-3.5Z" /></svg>
              </button>
            )}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[110] flex flex-col bg-slate-950 animate-in fade-in duration-200">
      <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 shrink-0">
        <div className="flex items-center gap-4">
             <h2 className="text-xl font-bold text-white tracking-tight">数据合并工作台</h2>
             <span className="text-xs text-slate-500 border-l border-slate-700 pl-4 py-1">精细化控制增量导入内容</span>
        </div>
        <div className="flex items-center gap-3">
          {!importedData ? (
            <Button variant="primary" onClick={handleSelectFile} size="sm">选择备份文件 (.json)</Button>
          ) : (
            <>
              <Button variant="ghost" onClick={() => setImportedData(null)} size="sm">重新选择文件</Button>
              <Button variant="success" onClick={handleConfirm} size="sm" className="px-8 font-black shadow-lg shadow-emerald-500/20" disabled={queue.length === 0}>
                执行合并 ({queue.length})
              </Button>
            </>
          )}
          <button onClick={onClose} className="text-slate-400 hover:text-white p-2 rounded-full hover:bg-slate-800 transition-colors ml-4">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-hidden p-8 flex flex-col">
        {!importedData ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center space-y-6">
            <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center border border-slate-800 shadow-2xl">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-10 h-10 text-blue-500"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg>
            </div>
            <div className="max-w-md">
              <h3 className="text-lg font-bold text-white mb-2">载入外部数据以开始</h3>
              <p className="text-sm text-slate-500 leading-relaxed">我们将扫描文件中的所有模版和项目，并与您当前的本地库进行智能比对。您可以手动挑选需要合并的项。</p>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex gap-12 min-h-0">
            {/* 左侧：仓库待选区 */}
            <div className="flex-1 flex flex-col min-w-0">
              <div className="flex items-center justify-between mb-6 px-2">
                 <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">外部文件仓库 ({inventory.length})</h4>
                 <button onClick={() => { setQueue([...queue, ...inventory]); setInventory([]); }} className="text-[10px] text-blue-400 hover:underline">全选</button>
              </div>
              <div className="flex-1 overflow-y-auto space-y-3 pr-4 custom-scrollbar">
                {inventory.map(item => renderItem(item, false))}
                {inventory.length === 0 && (
                  <div className="flex flex-col items-center justify-center py-20 border-2 border-dashed border-slate-900 rounded-2xl opacity-40">
                    <span className="text-xs italic text-slate-600">所有项已在合并队列或已过滤</span>
                  </div>
                )}
              </div>
            </div>

            <div className="w-[1px] bg-slate-800 shrink-0 self-stretch my-10 relative">
               <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-slate-950 p-2">
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="w-4 h-4 text-slate-700"><path fillRule="evenodd" d="M12.72 3.22a.75.75 0 0 1 1.06 1.06l-4.25 4.25a.75.75 0 0 1-1.06 0L4.22 4.28a.75.75 0 0 1 1.06-1.06L8 5.94l4.72-2.72ZM12.72 8.22a.75.75 0 0 1 1.06 1.06l-4.25 4.25a.75.75 0 0 1-1.06 0L4.22 9.28a.75.75 0 0 1 1.06-1.06L8 10.94l4.72-2.72Z" clipRule="evenodd" /></svg>
               </div>
            </div>

            {/* 右侧：合并队列 */}
            <div className="flex-1 flex flex-col min-w-0">
              <div className="flex items-center justify-between mb-6 px-2">
                 <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-widest">待合并执行队列 ({queue.length})</h4>
                 <button onClick={() => { setInventory([...inventory, ...queue]); setQueue([]); }} className="text-[10px] text-slate-600 hover:text-white">清空队列</button>
              </div>
              <div className="flex-1 overflow-y-auto space-y-3 pr-4 custom-scrollbar">
                {queue.map(item => renderItem(item, true))}
                {queue.length === 0 && (
                  <div className="flex flex-col items-center justify-center py-20 border-2 border-dashed border-slate-900 rounded-2xl text-center p-6">
                    <div className="w-10 h-10 rounded-full border border-slate-800 flex items-center justify-center mb-3 text-slate-800 font-black">+</div>
                    <p className="text-[10px] text-slate-700 font-bold uppercase tracking-tight">队列为空，请点击左侧 “+” 添加项</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* 预览覆盖层 */}
      <DataPreviewOverlay 
        isOpen={!!previewItem} 
        onClose={() => setPreviewItem(null)} 
        data={previewItem} 
      />

      <div className="p-4 bg-slate-900/50 border-t border-slate-800 flex justify-center gap-10">
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">无冲突新增</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-amber-500"></div><span className="text-[10px] text-slate-500 font-bold uppercase">名称冲突</span></div>
         <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-slate-700"></div><span className="text-[10px] text-slate-500 font-bold uppercase">数据完全相同</span></div>
      </div>
    </div>
  );
};

